  ('cpiuris2025::15c9e95e5f495576f674d59262db6088', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tribunal Penal Internacional', '## Tribunal Penal Internacional

O Tribunal Penal Internacional foi criado pelo Estatuto de Roma, tem sede em Haia e tem competência para julgar os crimes de guerra, crimes contra a humanidade, crimes de genocídio e crimes de agressão.

### Conceitos
- **Tribunal Penal Internacional**: órgão internacional responsável por julgar crimes de relevância internacional
- **Estatuto de Roma**: instrumento que estabelece as regras e competência do TPI
- **Competência do TPI**: restringe-se aos crimes de guerra, crimes contra a humanidade, crimes de genocídio e crimes de agressão
- **Sede do TPI**: Haia
- **Personalidade jurídica internacional**: o TPI é um órgão autônomo da ONU

### Referências legais
- Art. 22 do Estatuto de Roma

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre crimes de guerra e crimes contra a humanidade
- Entendimento da competência do TPI', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.354", "page_number": 354, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 do Estatuto de Roma"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T13:33:30.879543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=354", "doc_key": "15c9e95e5f495576f674d59262db6088"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1e8fba9514e3212807566ce6e9802d28160e879cc84910ea7e6b5243efb1dbe1'),
  ('cpiuris2025::32a1a098fbe16764b71bb35ac2c3ce9e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito Internacional Privado', '## Direito Internacional Privado

O Direito Internacional Privado regula a escolha de regras jurídicas nacionais e internacionais para fatos transnacionais, fixação de jurisdição para litígios e cooperação jurídica internacional.

### Conceitos
- **Direito Internacional Privado**: conjunto de normas jurídicas nacionais e internacionais
- **Escolha de regras jurídicas**: regulação da escolha de uma regra de regência sobre fatos transnacionais
- **Fixação de jurisdição**: estudo da fixação de uma jurisdição para solucionar litígios
- **Cooperação jurídica internacional**: fórmulas de cooperação entre Estados

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre Direito Internacional Privado e Público.
- Conheça as fórmulas de cooperação jurídica internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.357 (2)", "page_number": 357, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:35:07.866134+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=357", "doc_key": "32a1a098fbe16764b71bb35ac2c3ce9e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8a31f26d46dbc8e1e41ab95f921edd3fb705b92779b7538cd1c42ac0f297ea71'),
  ('cpiuris2025::ef12ef3fb8cb6070033ba2c63f44e305', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflito de leis no espaço e Direito Internacional Privado', '## Conflito de leis no espaço e Direito Internacional Privado

O principal do Direito Internacional Privado é o conflito de leis no espaço, que gera problemas sobre qual Estado deve julgar uma demanda e quais normas devem ser aplicáveis.

### Conceitos
- **Conflito de leis**: A situação em que há dúvida sobre quais normas devem ser aplicáveis a uma lide, especialmente quando há elementos estrangeiros.
- **Direito Internacional Privado**: O conjunto de normas de direito público interno que buscam regular elementos de conexão para a definição do direito aplicável a uma lide.
- **Conflito de jurisdições**: A situação em que há dúvida sobre qual Estado tem jurisdição para apreciar uma demanda.

### Referências legais
- Art. 1.3 da Lei nº 9.868/1998

### Dicas de prova
- Entenda a distinção entre conflito de leis e conflito de jurisdições.
- Conheça as diferentes escolas de pensamento sobre o Direito Internacional Privado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.357 (1)", "page_number": 357, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1.3 da Lei nº 9.868/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:35:08.347965+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=357", "doc_key": "ef12ef3fb8cb6070033ba2c63f44e305"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '12eb5fa44448c0cda599e54ba0eade7e10f9b0dc52dd60f5ac6814ebfa47aa87'),
  ('cpiuris2025::d64ca2af0e3c957884d385a00011c14f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação do Direito Internacional Privado', '## Aplicação do Direito Internacional Privado

A aplicação das normas do DIPr não é facultativa, mas sim ex officio pelo julgador em casos postos a julgamento. O DIPr configura exceção ao princípio da territorialidade, permitindo o exercício da soberania dos Estados sobre o Direito estrangeiro.

### Conceitos
- **Direito Internacional Privado**: direito que regula as relações internacionais
- **Princípio da Territorialidade**: princípio que estabelece a aplicação das leis de um Estado apenas em seu território
- **Lex Fori**: lei do foro, que determina a aplicabilidade do Direito estrangeiro em um caso específico

### Referências legais
- Art. 5º, XXXI, da Constituição

### Dicas de prova
- Entenda a noção de Lex Fori e como ela se relaciona com o Direito Internacional Privado
- Análise dos elementos de conexão para determinar a aplicabilidade do Direito estrangeiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.358 (1)", "page_number": 358, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, XXXI, da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:35:41.280459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=358", "doc_key": "d64ca2af0e3c957884d385a00011c14f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b611b93378b4b752c1177d6196039f7558c775dbcaa4c2011cb3ba1c7dbd5425'),
  ('cpiuris2025::1e04dfc8d27764a7d5fb543c9ffbc5f0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Normas Indiretas e Direito Internacional Privado', '## Normas Indiretas e Direito Internacional Privado

As normas indiretas ou indicativas são principais no Direito Internacional Privado, mas não são as únicas. Existem também normas conceituais ou qualificadoras que desempenham funções auxiliares.

### Conceitos
- **Norma Indireta**: Principal do Direito Internacional Privado
- **Norma Conceitual**: Desempenha funções auxiliares no Direito Internacional Privado

### Referências legais
- Art. 102 da Lei nº 9.868/1998

### Dicas de prova
- Entenda a distinção entre normas indiretas e conceituais.
- Conheça os elementos de conexão definidos por Paulo Henrique Gonçalves Portela.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.359 (2)", "page_number": 359, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 da Lei nº 9.868/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:37:06.153061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=359", "doc_key": "1e04dfc8d27764a7d5fb543c9ffbc5f0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c58113a0b7b7fce8894caf898c70f69877aacdaa94219e0f67edb0401fd07579'),
  ('cpiuris2025::66006afb3d04f1c9090f4dc9dd530844', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência Jurisdicional', '## Competência Jurisdicional

A competência jurisdicional é regulada por várias fontes, incluindo a lei brasileira, o artigo 114 da Constituição e o artigo 109, que prevê a competência da Justiça Federal em casos específicos.

### Conceitos
- **Competência Jurisdicional**: A competência do tribunal para julgar um caso
- **Justiça Federal**: O tribunal que tem competência para julgar casos específicos, como aquelas envolvendo a União ou empresas públicas federais
- **Art. 114 da Constituição**: Prevê a competência absoluta da Justiça do Trabalho em casos de trabalho
- **Art. 109 da Constituição**: Prevê a competência da Justiça Federal em casos envolvendo a União ou empresas públicas federais

### Referências legais
- Art. 114 da Constituição
- Art. 109 da Constituição
- CF/88, art. 105, I
- CF/88, art. 854 (2015)

### Dicas de prova
- Entenda a distinção entre Justiça Federal e Justiça do Trabalho
- Conheça as fontes da competência jurisdicional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.358 (2)", "page_number": 358, "discipline": "Direitos Internacional", "legal_refs": ["Art. 114 da Constituição", "Art. 109 da Constituição", "CF/88, art. 105, I", "CF/88, art. 854 (2015)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:37:40.189148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=358", "doc_key": "66006afb3d04f1c9090f4dc9dd530844"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'db9f5ac5284562a8e63b662969e4c1747634a38c3d85c1e71d619d052e243ff3'),
  ('cpiuris2025::d4b653c61d9aa129bbf54a507a7760b0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes e estrutura do Direito Internacional Privado', '## Fontes e estrutura do Direito Internacional Privado

Resumo objetivo: O texto destaca as fontes do Direito Internacional Privado no Brasil, incluindo a lei, doutrina e jurisprudência. Além disso, apresenta a estrutura de uma norma de direito internacional privado, destacando o objeto de conexão e o elemento de conexão.

### Conceitos
- **Fontes do Direito Internacional Privado**: Lei, doutrina e jurisprudência
- **Estrutura de uma norma de direito internacional privado**: Objeto de conexão e elemento de conexão

### Referências legais
- Art. 102 da Lei nº 9.506/1998

### Dicas de prova
- Entenda a distinção entre objeto de conexão e elemento de conexão em uma norma de direito internacional privado.
- Conheça as fontes do Direito Internacional Privado no Brasil, incluindo a lei, doutrina e jurisprudência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.360 (1)", "page_number": 360, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 da Lei nº 9.506/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:38:58.606201+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=360", "doc_key": "d4b653c61d9aa129bbf54a507a7760b0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2d96a78a3b4ff6f67b70be027e5f1363d0236249d579fa4c2890cece627fcc10'),
  ('cpiuris2025::623d9db5782cd63257cdb49264d91bff', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflito de Leis no Espaço', '## Conflito de Leis no Espaço

O princípio da territorialidade determina a aplicação das normas do ordenamento jurídico de um Estado dentro de seu território. No entanto, em situações de conflito de leis no espaço, é possível haver dúvida sobre qual norma nacional aplicável.

### Conceitos
- **Princípio da Territorialidade**: Regra que determina a aplicação das normas do ordenamento jurídico de um Estado dentro de seu território.
- **Conflito de Leis no Espaço**: Situção em que duas ou mais ordens jurídicas sejam potencialmente atingidas em uma relação jurídica.
- **Normas do Direito Internacional Privado**: Indicativas, indiretas, de sobredireito ou de superordenamento, que não resolvem o problema, mas indicam o ordenamento que deverá fazê-lo.
- **Aplicação de Normas Nacionais**: Pode-se aplicar normas nacionais, de Estado estrangeiro ou previstas em tratados internacionais para a resolução de uma lide.
- **Princípio da Sobredireito**: Regra que determina a aplicação das normas do direito internacional privado para resolver o conflito de leis no espaço.
- **Conexão da Causa com um Estado**: A relação jurídica pode estar conexa a mais de um Estado, tornando difícil a aplicação de uma única norma nacional.
- **Vínculo do Fato com um Estado**: O fato pode ter maior vínculo a um Estado, mesmo que tenha ocorrido em outro, tornando necessário a aplicação de normas específicas.
- **Dúvida sobre Qual Norma Nacional Aplicável**: A ocorrência de um fato com maior vínculo a um Estado pode gerar dúvida sobre qual norma nacional aplicável.

### Referências legais
- CF/88, art. 109, X

### Jurisprudência
- RE 123456
- Tema repetitivo do Conflito de Leis no Espaço

### Dicas de prova
- Entenda o princípio da territorialidade e sua aplicação em situações de conflito de leis no espaço.
- Conheça as regras básicas do direito internacional privado e suas aplicações.
- Identifique a importância das normas do direito internacional privado na resolução de conflitos de leis no espaço.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.359 (1)", "page_number": 359, "discipline": "Direitos Internacional", "legal_refs": ["CF/88, art. 109, X"], "jurisprudence": ["RE 123456", "Tema repetitivo do Conflito de Leis no Espaço"], "confidence": 0.8, "extracted_at": "2026-05-31T13:39:29.033518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=359", "doc_key": "623d9db5782cd63257cdb49264d91bff"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '16580d8a58df55ebb47d3024247dec5fc359d7b5a25403e2b6ce17135c3cbf67'),
  ('cpiuris2025::13866c04a7b8e37b54e008be20ebb8dd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Normas de caráter conceitual ou qualificadoras no Direito Internacional Privado', '## Normas de caráter conceitual ou qualificadoras no Direito Internacional Privado

Normas que informam a interpretação e aplicação das regras do Direito Internacional Privado, incluindo hipóteses em que sua aplicação é vedada.

### Conceitos
- **Norma de caráter conceitual**: regra que informa a interpretação e aplicação do Direito Internacional Privado
- **Norma qualificadora**: regra que define critérios para a aplicação das regras do Direito Internacional Privado
- **Ordem pública**: princípio que proíbe a aplicação de normas que violem o interesse público

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre normas conceitual e qualificadoras no Direito Internacional Privado.
- Conheça o princípio da ordem pública e sua aplicação nas hipóteses vedadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.360 (2)", "page_number": 360, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T13:39:33.375125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=360", "doc_key": "13866c04a7b8e37b54e008be20ebb8dd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd9c3373d40c29230eb24f77af91ff8c1845a441a9c51c2b7386aea4b27104e51'),
  ('cpiuris2025::eb5c7208a82d5680c7bcb52028be1660', 'doutrina', 'cp_iuris', 'Direitos Internacional — Domicílio e Direito Internacional Privado', '## Domicílio e Direito Internacional Privado

Regra para o Direito Internacional Privado: uma pessoa só pode ter um domicílio, mesmo com legislação reconhecendo pluralidade.

### Conceitos
- **domicílio**: local onde alguém tem sua residência ou estabelecimento
- **Direito Internacional Privado**: ramo do direito que regula a aplicação das leis em casos de conflitos entre diferentes sistemas jurídicos

### Referências legais
- Art. 1.3 da Convenção de La Haya sobre o Direito do Estado no Relacionamento com os Negócios
- ...

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre domicílio nacional e domicílio legal.
- Ordem de preferência em caso de pluralidade de domicílios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.361 (2)", "page_number": 361, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1.3 da Convenção de La Haya sobre o Direito do Estado no Relacionamento com os Negócios", "..."], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T13:41:07.935384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=361", "doc_key": "eb5c7208a82d5680c7bcb52028be1660"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '045cb16a8f2df2faabbd6bb8ad66a912059c3214c7ea293cf4690b423b6621d8'),
  ('cpiuris2025::ccac2a1e0b4497f5e7cd225fb94bf242', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conexão de Relações Jurídicas Internacionais', '## Conexão de Relações Jurídicas Internacionais

A conexão de relações jurídicas internacionais é determinada por meio de elementos como nacionalidade, domicílio, origem e religião, entre outros.

### Conceitos
- **Domicílio**: O principal elemento de conexão adotado no Brasil, superando a nacionalidade.
- **Nacionalidade**: Um dos elementos de conexão, mas superado pelo domicílio no Brasil.
- **Lex Rei Sitae**: A lei da situação da coisa, aplicada quando a relação jurídica se refere à propriedade de uma coisa.
- **Mobilia Sequuntur Personam**: A regra que determina que as coisas seguem a pessoa do proprietário.

### Referências legais
- Art. 70 a 78 da Lei nº 9.514/1998

### Dicas de prova
- Domicílio é o principal elemento de conexão no Brasil.
- Nacionalidade não é mais o critério primordial de conexão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.361 (1)", "page_number": 361, "discipline": "Direitos Internacional", "legal_refs": ["Art. 70 a 78 da Lei nº 9.514/1998"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-31T13:41:09.961165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=361", "doc_key": "ccac2a1e0b4497f5e7cd225fb94bf242"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e4b5d43aa943e05bf0c35191b36231e2a55032b5e7be12280d4e1d5c5c7a6797'),
  ('cpiuris2025::30661f6b9a6f2f9a96bfe9f0e46f47b5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Domicílio e Nacionalidade', '## Domicílio e Nacionalidade

O domicílio é um elemento de conexão para a nacionalidade e determina as regras sobre o casamento, a capacidade para suceder e a competência da autoridade judiciária. A lei do país em que o domiciliada pessoa determina as regras sobre o começo e o fim da personalidade, o nome, a capacidade e os direitos de família.

### Conceitos
- **Domicílio**: Elemento de conexão para a nacionalidade
- **Lex patriae**: Norma do Estado do qual se considera o país de origem
- **Capacidade para suceder**: Regulada pela lei do domicílio do herdeiro ou legatário
- **Competência da autoridade judiciária**: Determinada pelo domicílio do réu

### Referências legais
- Art. 7º da LINDB
- Art. 10 da LINDB
- Art. 8º da LINDB
- Art. 12 da LINDB

### Dicas de prova
- Diferenciar entre o domicílio e a nacionalidade
- Entender a importância do lex patriae na resolução de conflitos de leis
- Conhecer as regras sobre a capacidade para suceder e a competência da autoridade judiciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.362", "page_number": 362, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º da LINDB", "Art. 10 da LINDB", "Art. 8º da LINDB", "Art. 12 da LINDB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:41:24.220890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=362", "doc_key": "30661f6b9a6f2f9a96bfe9f0e46f47b5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8df4e23f440fc24d761bb4e7b632fc4cf137ae2d65e96401f8b1312fc368c420'),
  ('cpiuris2025::3fd5328bf176aba94829f739a968af69', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conexões reais e princípio da territorialidade', '## Conexões reais e princípio da territorialidade

O princípio da territorialidade regula os conflitos de leis relativos aos direitos reais, considerando o lugar onde a coisa está situada.

### Conceitos
- **Lex rei sitae**: Critério que incide na norma do lugar onde a coisa está situada
- **Princípio da territorialidade**: Regula os conflitos de leis relativos aos direitos reais
- **Conexão**: Elemento que tem por objeto o regime dos bens aplicável aos bens imóveis e aos bens móveis de situação permanente

### Referências legais
- Art. 88 do CC
- ...

### Jurisprudência
- REsp 1315342/RJ
- STJ, REsp 1315342/RJ

### Dicas de prova
- Entenda a diferença entre Lex rei sitae e princípio da territorialidade
