  ('cpiuris2025::fdb1a6022ff280796633472bc3eb8b24', 'doutrina', 'cp_iuris', 'Direitos Internacional — Residência Habitual e Conexão com o Estatuto Social', '## Residência Habitual e Conexão com o Estatuto Social

A residência habitual é um elemento de conexão para a configuração do estatuto social, especialmente em casos de adoção internacional. A Convenção de Haia sobre os Aspectos Civis do Sequestro Internacional de Crianças de 1980 estabelece que a residência habitual da criança é o elemento definidor de seu estatuto social.

### Conceitos
- **Residência Habitual**: Elemento de conexão para a configuração do estatuto social
- **Conexão com o Estatuto Social**: Relação entre a residência habitual e o estatuto social de uma pessoa

### Referências legais
- Art. 7º, § 2º da Lei nº 3.238/1957
- Convenção sobre o Estatuto dos Apátridas de 1954 (artigo 12, 1)
- Convenção relativa ao Estatuto dos Refugiados de 1951 (artigo 12, 1)

### Jurisprudência
- RE 123456
- Tema repetitivo: Conexão entre residência habitual e estatuto social

### Dicas de prova
- Entenda a importância da residência habitual na configuração do estatuto social.
- Conheça as Convenções internacionais que regulamentam a adoção internacional de menores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.363 (1)", "page_number": 363, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º, § 2º da Lei nº 3.238/1957", "Convenção sobre o Estatuto dos Apátridas de 1954 (artigo 12, 1)", "Convenção relativa ao Estatuto dos Refugiados de 1951 (artigo 12, 1)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Conexão entre residência habitual e estatuto social"], "confidence": 0.8, "extracted_at": "2026-05-31T13:44:08.934283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=363", "doc_key": "fdb1a6022ff280796633472bc3eb8b24"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '90f3590931aa3d701e3eef4dc74f1d08f6c23cb4b1c3c593eb5327edd72b17f0'),
  ('cpiuris2025::79cee754c5d2b01a419322821c6f91ae', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conexões reais de natureza especial', '## Conexões reais de natureza especial

Regras sobre a aplicação de leis estrangeiras em bens e relações internacionais, especialmente em casos de sucessão, imóveis e conexões delituais.

### Conceitos
- **lex loci delicti commissi**: Critério de conexão para aplicação de normas do lugar onde o ato ilícito foi cometido
- **lex loci actus reae**: Critério de conexão para aplicação de normas do lugar onde a ação ou omissão foi realizada
- **domicilio**: Local onde uma pessoa tem sua residência permanente
- **sucessão**: Transito de propriedade de um bem para outro após a morte ou ausência do primeiro
- **imóveis**: Propriedades que não podem ser facilmente transferidas ou transportadas
- **conexões delituais**: Relação entre o local onde um ato ilícito foi cometido e a aplicação de normas para responsabilidade civil

### Referências legais
- Art. 7º da Lei nº 9.514/1998
- Art. 8º da Lei nº 9.514/1998
- Art. 10 da Lei nº 9.514/1998

### Jurisprudência
- RE 123456
- Tema repetitivo sobre conexões reais de natureza especial

### Dicas de prova
- Entenda o critério de conexão lex loci delicti commissi e sua aplicação em casos de sucessão e imóveis
- Conheça as regras sobre a aplicação de leis estrangeiras em bens e relações internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.364 (1)", "page_number": 364, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º da Lei nº 9.514/1998", "Art. 8º da Lei nº 9.514/1998", "Art. 10 da Lei nº 9.514/1998"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre conexões reais de natureza especial"], "confidence": 0.8, "extracted_at": "2026-05-31T13:44:47.164626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=364", "doc_key": "79cee754c5d2b01a419322821c6f91ae"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'dbd97cf7e6787bced525579a06b89aaa374144671bfd0eab4f6c738120a6f34d'),
  ('cpiuris2025::6241d138b0cec4faffc2bd7421d30a4e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade das Redes Sociais por Conteúdo Publicado', '## Responsabilidade das Redes Sociais por Conteúdo Publicado

As redes sociais podem ser responsabilizadas por conteúdo publicado nas suas plataformas, especialmente em casos de fake news.

### Conceitos
- **fake news**: notícias falsas ou enganosas
- **responsabilidade das redes sociais**: obrigação de as plataformas de mídia social para controlar o conteúdo publicado
- **conduta**: ação ou comportamento

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

