  ('cpiuris2025::453f2fa48741cf67ecfae041fb741f3b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conexão de Lex Loci Delicti Commissi e Autonomia da Vontade', '## Conexão de Lex Loci Delicti Commissi e Autonomia da Vontade

O texto discute a conexão de lex loci delicti commissi e a autonomia da vontade em contratos internacionais, destacando a limitação da autonomia da vontade pela ordem jurídica estatal.

### Conceitos
- **Lex Loci Delicti Commissi**: Lei do local onde o ato ilícito foi cometido
- **Autonomia da Vontade**: A possibilidade de escolha do Direito aplicável a uma relação privada, com conexão internacional, pelos participantes da relação jurídica
- **Lex Voluntatis**: Lei que escolhe o Direito aplicável à relação jurídica

### Referências legais
- Art. 13 da Lei de Introdução ao Código Civil de 1916

### Dicas de prova
