  ('cpiuris2025::acf5d7f320b498cae22112724fdd7310', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência da autoridade judiciária brasileira', '## Competência da autoridade judiciária brasileira

A autoridade judiciária brasileira tem competência para processar e julgar ações em que as partes se submetem à jurisdição nacional, incluindo eleições do foro.

### Conceitos
- **Competência**: Hábito de agir dentro da esfera jurisdicional
- **Autoridade judiciária brasileira**: Instituição responsável pela aplicação da lei no Brasil
- **Eleição do foro**: Escolha da jurisdição para processar uma ação

### Referências legais
- Art. 22, III; Art. 23, I e II do CPC

### Dicas de prova
- Distinção entre competência absoluta e relativa
