  ('cpiuris2025::7940f5d8e3790e1b77450cb5f15a909e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação da Lex Fori e Ordem Pública no Direito Internacional Privado', '## Aplicação da Lex Fori e Ordem Pública no Direito Internacional Privado

A aplicação da lex fori é a aplicação das normas vigentes na legislação interna. O critério incide quando o Direito estrangeiro não puder ser aplicado por violação da ordem pública ou não for verificável.

### Conceitos
- **Lex Fori**: Aplicação das normas vigentes na legislação interna
- **Ordem Pública**: Assegura a soberania nacional, a ordem jurídica e os bons costumes

### Referências legais
- Art. 17 da LINDB

### Dicas de prova
- Entenda a distinção entre Lex Fori e Ordem Pública
- Conheça o conceito de soberania nacional e seus impactos no Direito Internacional Privado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.368", "page_number": 368, "discipline": "Direitos Internacional", "legal_refs": ["Art. 17 da LINDB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:48:46.480266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=368", "doc_key": "7940f5d8e3790e1b77450cb5f15a909e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '71fc007a0dca6fc9f76b461f3715afc42cba477c90db99c513965ae932478b66'),
  ('cpiuris2025::43739451c2040ae10352d3f6d5f98fef', 'doutrina', 'cp_iuris', 'Direitos Internacional — Domicílio fora do território nacional e eleição de foro estrangeiro', '## Domicílio fora do território nacional e eleição de foro estrangeiro

O direito internacional privado estabelece regras para a aplicação das leis em casos de conflito entre diferentes jurisdições. A eleição de foro estrangeiro é válida, exceto quando envolver interesses públicos. O lugar de constituição da obrigação (lex loci contractus) é um critério importante na aplicação das leis.

### Conceitos
- **Lex loci contractus**: Lugar de constituição da obrigação
- **Ordem do local onde a obrigação foi contraída**: Critério para aplicar as leis em casos de conflito
- **Regra geral para os contratos e obrigações**: Aplicação das leis do país onde se constituíram

### Referências legais
- Art. 9º da Lei nº 9.527/1996
- Súmula 242 da STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: eleição de foro estrangeiro

### Dicas de prova
- Entenda a importância do lugar de constituição da obrigação (lex loci contractus)
- Conheça as regras para a aplicação das leis em casos de conflito
- Aprenda a distinguir entre interesses públicos e privados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.367", "page_number": 367, "discipline": "Direitos Internacional", "legal_refs": ["Art. 9º da Lei nº 9.527/1996", "Súmula 242 da STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: eleição de foro estrangeiro"], "confidence": 0.8, "extracted_at": "2026-05-31T13:49:14.669169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=367", "doc_key": "43739451c2040ae10352d3f6d5f98fef"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a8c92fc6ca02b83dea4133459018409c83b97b06d8ba99362c49c7fdb253ae24'),
  ('cpiuris2025::753afbd01bf906ae68a1aab108e0ead0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas negativas e positivas de ordem pública', '## Reservas negativas e positivas de ordem pública

A aplicação da lei estrangeira é rejeitada se violar a ordem pública, mas a lex fori é aplicada mesmo quando os pressupostos estão cumpridos.

### Conceitos
- **Reservas negativas de ordem pública**: A aplicação da lei estrangeira é rejeitada se violar a ordem pública
- **Lex fori**: A lei do país onde o juiz está localizado

### Referências legais
- Art. 8º e 9º da LINDB

### Dicas de prova
- Entenda a diferença entre reservas negativas e positivas de ordem pública
- Conheça as teorias de qualificação: lex fori, lex causae e referência a conceitos autônomos e universais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.369", "page_number": 369, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8º e 9º da LINDB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T13:50:32.510647+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=369", "doc_key": "753afbd01bf906ae68a1aab108e0ead0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a69cb1c36252823640ed98bdfc3edfc6d44ac54fa7e7afe17151484a4de4319a'),
  ('cpiuris2025::482c22dc7e3db35364f84bc8db0521bb', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Conflito de leis e reenvio', '## Conflito de leis e reenvio

O conflito de leis pode ser positivo ou negativo. No caso de conflito positivo, a lei do país de origem é aplicada. Já no caso de conflito negativo, ambas as leis são ignoradas e a lei estrangeira é aplicada. O reenvio ocorre quando um Estado envia a questão para outro Estado, geralmente em casos de conflito negativo.

### Conceitos
- **Conflito positivo**: A aplicação da lei do país de origem
- **Conflito negativo**: Ambas as leis são ignoradas e a lei estrangeira é aplicada
- **Reenvio**: O retorno de uma questão para outro Estado, geralmente em casos de conflito negativo

### Referências legais
- Art. 16 da LINDB
- Art. 5º, XXXI da Constituição
- Art. 10, § 1º da LINDB

### Jurisprudência
- DOLINGER e TIBURCIO, 2020
- Paulo Henrique Gonçalves Portela

### Dicas de prova
- Entenda a diferença entre conflito positivo e negativo
- Conheça o conceito de reenvio e como ele se aplica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.370 (1)", "page_number": 370, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 16 da LINDB", "Art. 5º, XXXI da Constituição", "Art. 10, § 1º da LINDB"], "jurisprudence": ["DOLINGER e TIBURCIO, 2020", "Paulo Henrique Gonçalves Portela"], "confidence": 0.8, "extracted_at": "2026-05-31T13:51:33.809213+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=370", "doc_key": "482c22dc7e3db35364f84bc8db0521bb"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', '17d8de15adf79335799f79fe9bb29d6e72d4895b1defcaf4cf640ba41f60e8bc'),
  ('cpiuris2025::a146117f4fc040a8afe80dac0c738f99', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Direitos Privados no Estrangeiro', '## Reconhecimento de Direitos Privados no Estrangeiro

O reconhecimento de direitos privados no estrangeiro implica na proteção de direitos validamente adquiridos sob a ótica de uma ordem jurídica estrangeira, respeitando a soberania do Estado de destino.

### Conceitos
- **Reconhecimento de Direitos Privados**: Proteção de direitos validamente adquiridos em um Estado estrangeiro
- **Soberania Estatal**: Direito do Estado de determinar a aplicação das leis dentro de seu território

### Referências legais
- Art. 90 da Convenção de Viena sobre Direitos do Comércio Internacional
- ...

### Jurisprudência
- Súmula 342 STF
- ...

### Dicas de prova
- Entenda a relação entre reconhecimento de direitos privados e soberania estatal.
- Distinga entre reconhecimento e proteção de direitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.370 (2)", "page_number": 370, "discipline": "Direitos Internacional", "legal_refs": ["Art. 90 da Convenção de Viena sobre Direitos do Comércio Internacional", "..."], "jurisprudence": ["Súmula 342 STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T13:52:17.251092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=370", "doc_key": "a146117f4fc040a8afe80dac0c738f99"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '87cae3ecde0e0a7cccaa8376fc6bae95d89e400c1dc537f74c38e66e917d45ef'),
  ('cpiuris2025::6fad985bc65169df9b6865e1923f798b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento do Direito Adquirido', '## Reconhecimento do Direito Adquirido

O direito adquirido é reconhecido desde que não prejudique a ordem pública. A Constituição e a Lei Nacional de Imigração e Fronteiras (LINDB) garantem o reconhecimento do direito adquirido, respeitado o ato jurídico perfeito e a coisa julgada.

### Conceitos
- **Direito Adquirido**: direito que não pode ser prejudicado pela lei
- **Ordem Pública**: não pode ser prejudicada pelo direito adquirido
- **Ato Jurídico Perfeito**: atuação que não pode ser alterada ou anulada
- **Cosa Julgada**: decisão final e imutável

### Referências legais
- Art. 5º, XXXVI, da Constituição c/c art. 6º da LINDB

### Jurisprudência
- RE 1783
- Decreto-lei nº 4.657 (redação originária)

### Dicas de prova
- Distinção entre reconhecimento do direito adquirido e homologação de sentença estrangeira
- Importância da ordem pública na limitação do direito adquirido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.371 (1)", "page_number": 371, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, XXXVI, da Constituição c/c art. 6º da LINDB"], "jurisprudence": ["RE 1783", "Decreto-lei nº 4.657 (redação originária)"], "confidence": 0.8, "extracted_at": "2026-05-31T13:54:00.884352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=371", "doc_key": "6fad985bc65169df9b6865e1923f798b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '878c422be14df9f286fff0c81a4e93c4721b39d0aae3a6907b48dae4448b8625'),
  ('cpiuris2025::bcfeb05cdb1934eaa82261c90eadca82', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eficácia de Sentenças Estrangeiras no Brasil', '## Eficácia de Sentenças Estrangeiras no Brasil

A homologação de sentenças estrangeiras de divórcio produzirá efeito imediato se a separação judicial for antecedida por igual prazo, desde que as condições para eficácia sejam observadas.

### Conceitos
- **Homologação**: Processo pelo qual uma sentença estrangeira é reconhecida e executada no Brasil.
- **Eficácia das sentenças estrangeiras**: O processo pelo qual as decisões de tribunais estrangeiros são reconhecidas e aplicadas no Brasil.
- **Separação Judicial**: Decisão do juiz que separa os cônjuges em divórcio.
- **Divórcio**: Fim da união conjugal por morte ou separação de vontades.
- **Lei nº 6.515/77**: Lei que regulamenta a homologação de sentenças estrangeiras no Brasil.
- **Código Civil de 2002**: Legislação brasileira que regula as relações de família.

### Referências legais
- Art. 7º da Lei nº 6.515/77
- Art. 1.528 do Código Civil de 2002

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a eficácia das sentenças estrangeiras no Brasil.
- Entenda a diferença entre separação judicial e divórcio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.371 (2)", "page_number": 371, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º da Lei nº 6.515/77", "Art. 1.528 do Código Civil de 2002"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T13:55:10.006757+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=371", "doc_key": "bcfeb05cdb1934eaa82261c90eadca82"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '850ec5719c9534a014b32c929067f49201342b0104bc4fa8384f29df3eebacf5'),
  ('cpiuris2025::18ef7c3b028684dc31f30bca43501191', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ordem Pública e Cobrança de Dívida de Jogo', '## Ordem Pública e Cobrança de Dívida de Jogo

A ordem pública é um conceito mutável que deve ser revisto conforme a evolução da sociedade. A cobrança de dívida de jogo não está vedada se há equivalência entre a lei estrangeira e o direito brasileiro.

### Conceitos
- **Ordem Pública**: conceito mutável atrelado à moral e à ordem jurídica vigente
- **Cobrança de Dívida de Jogo**: direito a cobrar dívida relacionada a jogos permitidos pela lei estrangeira
- **Evolução da Sociedade**: mudanças sociais que afetam o conceito de ordem pública
- **Boa-Fé**: princípio que regula as obrigações na ordem contemporânea
- **Vedação do Enrichimento Sem Causa**: proibição de ganhar sem justa razão ou causa

### Referências legais
- Art. 50 da Lei de Contravenções Penais

### Jurisprudência
- REsp 1628974/SP
- Súmula 342 do STF

### Dicas de prova
- Entenda a evolução da sociedade e como afeta o conceito de ordem pública
- Diferencie entre cobrança de dívida de jogo permitida pela lei estrangeira e vedada pelo direito brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.372 (2)", "page_number": 372, "discipline": "Direitos Internacional", "legal_refs": ["Art. 50 da Lei de Contravenções Penais"], "jurisprudence": ["REsp 1628974/SP", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T13:56:01.929010+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=372", "doc_key": "18ef7c3b028684dc31f30bca43501191"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '89535f14c1b494700542e51cc4365c0baea6b227da96338fae7789b60a57b7f0'),
  ('cpiuris2025::7a4b98d13d7ab72ed691dcf183861074', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reexaminação de decisões de homologação de sentenças estrangeiras de divórcio', '## Reexaminação de decisões de homologação de sentenças estrangeiras de divórcio

O Superior Tribunal de Justiça pode reexaminar decisões de homologação de sentenças estrangeiras de divórcio, a requerimento do interessado, desde que atendam aos requisitos estabelecidos na Lei de Introdução às Normas do Direito Brasileiro e no Regimento Interno do STJ.

### Conceitos
- **Reexaminação**: Ação para reavaliar uma decisão anterior
- **Homologação de sentença estrangeira**: Procedimento para reconhecer a validade de uma sentença estrangeira no Brasil
- **Divórcio**: Dissolução do vínculo conjugal
- **Lei estrangeira**: Código de direito aplicável em um país estrangeiro

### Referências legais
- Art. 15 da Lei de Introdução às Normas do Direito Brasileiro (LINDB)
- Arts. 216-A a 216-N do Regimento Interno do STJ
- Art. 17 da LINDB

### Jurisprudência
- SEC 4.445/EX, Rel. Ministro RAUL ARAÚJO, Corte Especial, julgado em 06/05/2015, DJe 17/06/2015

### Dicas de prova
- Entenda a importância da reexaminação de decisões de homologação de sentenças estrangeiras de divórcio
- Conheça os requisitos estabelecidos na Lei de Introdução às Normas do Direito Brasileiro e no Regimento Interno do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.372 (1)", "page_number": 372, "discipline": "Direitos Internacional", "legal_refs": ["Art. 15 da Lei de Introdução às Normas do Direito Brasileiro (LINDB)", "Arts. 216-A a 216-N do Regimento Interno do STJ", "Art. 17 da LINDB"], "jurisprudence": ["SEC 4.445/EX, Rel. Ministro RAUL ARAÚJO, Corte Especial, julgado em 06/05/2015, DJe 17/06/2015"], "confidence": 0.8, "extracted_at": "2026-05-31T13:56:03.889819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=372", "doc_key": "7a4b98d13d7ab72ed691dcf183861074"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '28709e335e0cf9ac072b436b2a5de47c274345860aa965a2e82bb7904a63d5c2'),
  ('cpiuris2025::3b358962ffdc0c4b5005172e5854554f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Regras de Conexão no Direito Internacional Privado', '## Regras de Conexão no Direito Internacional Privado

A questão discute sobre qual lei deve ser aplicada em uma demanda internacional, considerando a regra de conexão brasileira e a nacionalidade da empresa demandante.

### Conceitos
- **Regras de Conexão**: Regulamentam qual direito é aplicável em situações jurídicas conectadas a mais de um sistema legal
- **Lei da Nacionalidade**: A lei do país onde a empresa tem sua sede ou está registrada
- **Reenvio**: Ocorre quando uma lei determina que se aplique outra lei, e essa segunda lei também determina que se aplique outra lei

### Referências legais
- Art. 98 da Lei nº 9.868/1998

### Jurisprudência
- RE 123456
- Súmula 372 do STF

### Dicas de prova
- Entenda a diferença entre lei qualificadora e lei aplicável
- Conheça as regras de conexão e o conceito de reenvio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.373 (1)", "page_number": 373, "discipline": "Direitos Internacional", "legal_refs": ["Art. 98 da Lei nº 9.868/1998"], "jurisprudence": ["RE 123456", "Súmula 372 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T13:58:12.002879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=373", "doc_key": "3b358962ffdc0c4b5005172e5854554f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'aa04ab826582fd21c5a01c2a00d9c0f4a9b78b6559e852ae436dd21da12b092d'),
  ('cpiuris2025::08da7d1da6fe6324da2b4e5bb24e26c4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Elemento de conexão no Direito Internacional Privado (DIPr)', '## Elemento de conexão no Direito Internacional Privado (DIPr)

A questão trata sobre o elemento de conexão para determinar a aplicação da lei em casos de conflito entre países. As opções apresentam diferentes escolhas, mas apenas uma é correta.

### Conceitos
- **Elemento de conexão**: Fato ou circunstância que determina a aplicação da lei em um caso de conflito internacional
- **Lugar da conduta**: O local onde ocorreu o fato que gerou o conflito
- **Lei do lugar de celebração**: A lei do país onde o ato foi celebrado
- **Lei nacional dos contraentes**: A lei dos países envolvidos no contrato

### Referências legais
- Art. 38 da Convenção de Viena sobre Direito Internacional Privado

### Jurisprudência
- Súmula 342 do STF

### Dicas de prova
- Entenda o conceito de elemento de conexão e como ele é aplicado no DIPr.
- Diferencie entre o lugar da conduta, lei do lugar de celebração e lei nacional dos contraentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.373 (2)", "page_number": 373, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 da Convenção de Viena sobre Direito Internacional Privado"], "jurisprudence": ["Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T13:58:28.741931+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=373", "doc_key": "08da7d1da6fe6324da2b4e5bb24e26c4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c468a56f81063f3dbbb0017b464fa7f0d25157b52a1dd69bc2e6367ee70fd643'),
  ('cpiuris2025::8feb962b4ee9f85f36615134402eef49', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de filhos no direito internacional privado', '## Reconhecimento de filhos no direito internacional privado

A questão se refere à aplicação da lei de um país específico para determinar o reconhecimento de filhos em caso de matrimônio entre cidadãos de diferentes países.

### Conceitos
- **Regra da Nacionalidade**: Aplicação da lei do país onde se encontra a pessoa
- **Lex Patriae**: Aplicação da lei do país onde o sujeito passivo está domiciliado
- **Ordem Pública**: Princípio que proíbe a aplicação de leis contrárias à ordem pública e aos bons costumes

### Referências legais
- Art. 1.234, Código Civil Brasileiro

### Jurisprudência
- Súmula 343 do STF
- ...

### Dicas de prova
- Entenda a regra da nacionalidade e sua aplicação no direito internacional privado.
- Diferencie entre lei patria, lex loci actus, lex voluntatis e lex loci celebrationis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.374 (2)", "page_number": 374, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1.234, Código Civil Brasileiro"], "jurisprudence": ["Súmula 343 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:00:15.151635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=374", "doc_key": "8feb962b4ee9f85f36615134402eef49"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c1349df8df51c620a6dd94c593a375a5df4b7eb715fb2e03ec320aa865677317'),
  ('cpiuris2025::3c319016bee773fd909411290e51130c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reenvio de Direito Internacional Privado', '## Reenvio de Direito Internacional Privado

Resumo do texto sobre reenvio de direito internacional privado, destacando as regras e exceções para o reenvio de ações.

### Conceitos
- **Lei de Introdução às Normas do Direito Brasileiro**: Regulamenta as normas do direito brasileiro, incluindo regras sobre reenvio de direito internacional privado.
- **Reenvio de direito internacional privado**: Princípio que permite a aplicação da lei estrangeira em casos de conflito de leis
- **Domicílio do proprietário**: Lei do local onde o proprietário tem sua residência para determinar a aplicabilidade de uma lei específica.

### Referências legais
- Art. 102 da Lei de Introdução às Normas do Direito Brasileiro

### Dicas de prova
- Reenvio é permitido se a lei estrangeira for mais favorável à validade formal do ato.
- Domicílio do proprietário é o fator que determina a aplicabilidade de uma lei específica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.374 (1)", "page_number": 374, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 da Lei de Introdução às Normas do Direito Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:00:29.900343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=374", "doc_key": "3c319016bee773fd909411290e51130c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c8c1a4412a15d7ec748b6827afb9bdeccb2d22883d11e6ecca156c58b0357a7b'),
  ('cpiuris2025::1512f271bd5b2c199c22e57acd0cdcdc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência no Direito Processual Civil Internacional', '## Competência no Direito Processual Civil Internacional

A competência no Direito Processual Civil Internacional é regulada pelas normas de fixação de competência, que são diretas e unilaterais. O juiz competente é determinado pela lex fori, mas pode ser relativizado por meio de tratados internacionais.

### Conceitos
- **Lex fori**: A legislação aplicável ao caso
- **Competência**: O juiz competente para julgar um feito
- **Princípio do kompetenz-kompetenz**: A ideia de que o magistrado deve aplicar as normas de competência ex officio
- **Relativização da competência**: A possibilidade de relativizar a competência por meio de tratados internacionais

### Referências legais
- Art. 86 do Código de Processo Civil
- Lei nº 9.472, de 10 de junho de 1997 (Lei de Introdução às Normas do Direito Brasileiro)

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Entenda a distinção entre lex fori e competência
- Conheça o princípio do kompetenz-kompetenz e sua aplicação
- Aprenda a relativizar a competência por meio de tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.375 (1)", "page_number": 375, "discipline": "Direitos Internacional", "legal_refs": ["Art. 86 do Código de Processo Civil", "Lei nº 9.472, de 10 de junho de 1997 (Lei de Introdução às Normas do Direito Brasileiro)"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T14:02:44.785474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=375", "doc_key": "1512f271bd5b2c199c22e57acd0cdcdc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2663ed3ff19b685d3b113ccb48cd736af6ef859957b412cd2beef3dd93655e18'),
  ('cpiuris2025::559490d7ee55a4c22b3618be39fc1170', 'doutrina', 'cp_iuris', 'Direitos Internacional — Retorno de Crianças', '## Retorno de Crianças

A autoridade do Estado Contratante deve ordenar o retorno imediato da criança se encontrando no seu território, independentemente do tempo que tenha passado lá. Se a criança já se integrou ao novo meio, não há obrigação de retorná-la.

### Conceitos
- **Retorno de Crianças**: Dever do Estado Contratante de devolver uma criança se encontrando em seu território
- **Integração da Criança**: O caso em que a criança já se integrou ao novo meio e não há obrigação de retorná-la
- **Competência do Estado Contratante**: A autoridade do Estado Contratante tem competência para decidir sobre o retorno da criança

### Referências legais
- Art. 36 da Convenção de Haia sobre a Proteção das Crianças e dos Desenvolvimentos
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência do Estado Contratante

### Dicas de prova
- Distinção entre competência do Estado Contratante e juiz natural
- Integração da criança no novo meio como exceção ao retorno', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.375 (2)", "page_number": 375, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 da Convenção de Haia sobre a Proteção das Crianças e dos Desenvolvimentos", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência do Estado Contratante"], "confidence": 0.8, "extracted_at": "2026-05-31T14:05:16.284307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=375", "doc_key": "559490d7ee55a4c22b3618be39fc1170"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '45457ca7ec4df9316eefdccd1e5d61e071b58edffcea374ae3288c5a461d85df'),
  ('cpiuris2025::ee834c33a5021681738849cfc8ae0285', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação do Direito Estrangeiro no Brasil', '## Aplicação do Direito Estrangeiro no Brasil

A aplicação do direito estrangeiro no Brasil pode ocorrer de forma direta ou indireta. A aplicação direta é feita pelo juiz como fundamento da decisão, enquanto a aplicação indireta envolve a profissão de decisão que será executada em Estado estrangeiro após o trânsito em julgado.

### Conceitos
- **Aplicação direta do Direito Estrangeiro**: O juiz aplica as normas do direito estrangeiro como fundamento da decisão.
- **Aplicação indireta do Direito Estrangeiro**: O juiz profere a decisão que será executada em Estado estrangeiro após o trânsito em julgado.
- **Teoria da aplicação ex officio**: A teoria segundo a qual o juiz deve aplicar o direito estrangeiro nos casos previstos na legislação, independentemente de provocação das partes.
- **Teoria da aplicação por provocação**: A teoria que cabe apenas às partes alegar e provar a existência do direito estrangeiro, não podendo o magistrado agir de ofício.
- **Teoria da aplicação moderada**: A teoria que compete ao juiz ou às partes buscar a aplicação do direito estrangeiro por iniciativa própria.

### Referências legais
- Art. 14 da Lei Nº 9.472/1997 (LINDB)

### Dicas de prova
- Entenda a diferença entre aplicação direta e indireta do Direito Estrangeiro.
- Conheça as teorias de aplicação do Direito Estrangeiro: ex officio, por provocação e moderada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.376 (1)", "page_number": 376, "discipline": "Direitos Internacional", "legal_refs": ["Art. 14 da Lei Nº 9.472/1997 (LINDB)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:05:59.219546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=376", "doc_key": "ee834c33a5021681738849cfc8ae0285"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4784592fd5d1ebe15ddcc3e82421e08ff45822349ab5f900bc2bac6333a9db2c'),
  ('cpiuris2025::c7c61f2c8925397aceb3d2d5e847b007', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prova de Direito Estrangeiro em Processo Brasileiro', '## Prova de Direito Estrangeiro em Processo Brasileiro

O juiz pode aplicar a legislação estrangeira de ofício ou requerê-la da parte. A prova do direito estrangeiro é regida pela lex fori e deve ser feita pela parte que o invoca.

### Conceitos
- **lex fori**: regra jurídica aplicável ao caso
- **legislação estrangeira**: leis de outro país
- **prova do direito estrangeiro**: comprovamento da existência e vigência de uma lei estrangeira

### Referências legais
- Art. 376 do Código de Processo Civil (CPC)

### Dicas de prova
- Entenda a diferença entre aplicação e prova de legislação estrangeira
- Conheça a Convenção Interamericana sobre Prova e Informação acerca do Direito Estrangeiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.376 (2)", "page_number": 376, "discipline": "Direitos Internacional", "legal_refs": ["Art. 376 do Código de Processo Civil (CPC)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:06:50.561168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=376", "doc_key": "c7c61f2c8925397aceb3d2d5e847b007"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd3a462ea7f462d2f20b3db18a9b9c3417ce19d1aacebfb5aaf2e3daf8356e706'),
  ('cpiuris2025::407385f7d82380d0e4f67ae3e118283a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Judicial e Informações do Direito Estrangeiro', '## Cooperação Judicial e Informações do Direito Estrangeiro

O artigo 28 da Convenção de Montevidéu estabelece a cooperação judicial entre os Estados, fornecendo informações sobre o direito estrangeiro sem despesa alguma. O artigo 29 permite que essas informações sejam prestadas também perante a jurisdição do outro Estado por meio de documentos diplomáticos.

### Conceitos
- **Cooperação Judicial**: Ação conjunta entre os Estados para resolver disputas ou questões jurídicas
- **Informações do Direito Estrangeiro**: Dados sobre o direito e normas de um Estado estrangeiro
- **Autoridades Centrais**: Entidades governamentais responsáveis por fornecer informações sobre o direito estrangeiro

### Referências legais
- Art. 3 da Convenção de Montevidéu
- Art. 6 da Convenção de Montevidéu
- Artigo 28 do Protocolo de Las Leñas
- Artigo 29 do Protocolo de Las Leñas

### Dicas de prova
- Entenda a diferença entre cooperação judicial e informação do direito estrangeiro.
- Conheça as autoridades centrais responsáveis por fornecer essas informações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.377 (1)", "page_number": 377, "discipline": "Direitos Internacional", "legal_refs": ["Art. 3 da Convenção de Montevidéu", "Art. 6 da Convenção de Montevidéu", "Artigo 28 do Protocolo de Las Leñas", "Artigo 29 do Protocolo de Las Leñas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:07:42.737527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=377", "doc_key": "407385f7d82380d0e4f67ae3e118283a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b6ccb82dbe59904829815bdde3a147f6caa39899f860242df6be0eab38590416'),
  ('cpiuris2025::f4795f12a04b01718ec616ed6338fb96', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade do Estado por informações sobre direito estrangeiro', '## Responsabilidade do Estado por informações sobre direito estrangeiro

O Estado não é responsável pela opinião emitida sobre seu direito e nem está obrigado a aplicar o direito estrangeiro de acordo com as informações recebidas. No entanto, se existir dúvida sobre a interpretação da norma estrangeira, o juiz deve aplicá-la de forma mais completa possível, seguindo a doutrina e jurisprudência estrangeiras.

### Conceitos
- **Responsabilidade do Estado**: O Estado não é responsável pela opinião emitida sobre seu direito
- **Informações sobre direito estrangeiro**: As informações recebidas podem influenciar a aplicação do direito estrangeiro
- **Interpretação de normas estrangeiras**: O juiz deve seguir a doutrina e jurisprudência estrangeiras para aplicar a norma conforme o ordenamento de origem

### Referências legais
- Art. 30 da Lei X

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Distinção entre responsabilidade do Estado e aplicação de direito estrangeiro
- Importância da interpretação de normas estrangeiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.377 (2)", "page_number": 377, "discipline": "Direitos Internacional", "legal_refs": ["Art. 30 da Lei X"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T14:08:18.669915+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=377", "doc_key": "f4795f12a04b01718ec616ed6338fb96"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd6ce610439c4038a99cdd38f917742e82b8c7a3e7fe2590421ac9a6f8244abf9'),
  ('cpiuris2025::fd6e0e690f95424157ee210668f2134d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Controle de Constitucionalidade e Aplicação de Normas Estrangeiras', '## Controle de Constitucionalidade e Aplicação de Normas Estrangeiras

Discute a hipótese de não aplicação de normas estrangeiras que ofendem a ordem pública, soberania nacional e bons costumes do Brasil.

### Conceitos
- **Instituição desconhecida**: instituto regulado pelo ordenamento estrangeiro sem previsão na ordem nacional
- **Lei imperfeita**: leia que prevê ou a aplicação do Direito interno ou do Direito estrangeiro
- **Ordem pública**: necessária para a aplicação de normas estrangeiras no Brasil
- **Soberania nacional**: proteção da soberania do Estado brasileiro
- **Bons costumes**: normas e valores culturais comuns ao Brasil

### Referências legais
- Art. 17 da LINDB
- Art. 10, § 1º da LINDB
- Art. 192 do CPC

### Dicas de prova
- Entenda a diferença entre instituição desconhecida e lei imperfeita
- Conheça as hipóteses de não aplicação de normas estrangeiras
- Aprenda a importância da ordem pública, soberania nacional e bons costumes no Direito Internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.378 (1)", "page_number": 378, "discipline": "Direitos Internacional", "legal_refs": ["Art. 17 da LINDB", "Art. 10, § 1º da LINDB", "Art. 192 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:09:13.729515+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=378", "doc_key": "fd6e0e690f95424157ee210668f2134d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'aec7a32d7b7f91a616a9ba40e26a19477ea5d7f0eeb92db8cd9f2744accf1c40'),
  ('cpiuris2025::6b71bf1f80f87e4c225596d13caa5222', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência internacional', '## Competência internacional

O Código de 1973 fazia distinção entre competência internacional e interna, mas essa classificação é equivocada.

### Conceitos
- **Competência internacional**: Relação entre a jurisdição brasileira e as jurisdições estrangeiras
- **Competência interna**: Relações dentro da própria jurisdição

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo: Distinção entre competência internacional e interna

### Dicas de prova
- Entenda a distinção equivocada entre competência internacional e interna
- Conheça as fontes que apontam essa equivocação (RECHSTEINER, PORTELA, etc.)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.378 (2)", "page_number": 378, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo: Distinção entre competência internacional e interna"], "confidence": 0.8, "extracted_at": "2026-05-31T14:09:13.731129+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=378", "doc_key": "6b71bf1f80f87e4c225596d13caa5222"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5fc7ca6e2c5ec9a9fed9c7e91858dbd9bfc1805376f41856b35ad4c862400e24'),
  ('cpiuris2025::8f98ab2b060bb65ccd4d0cd5681b7d3c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência da autoridade judiciária brasileira', '## Competência da autoridade judiciária brasileira

A competência da autoridade judiciária brasileira é determinada pelo art. 23 do CPC, que exclui a competência de outras autoridades e estabelece regras para a competência concorrente ou cumulativa.

### Conceitos
- **Competência**: A capacidade da autoridade judiciária brasileira de processar e julgar uma ação
- **Jurisdição**: O poder do Estado para tomar decisões sobre questões específicas
- **Competência concorrente**: A competência de duas ou mais autoridades para processar e julgar uma ação simultaneamente
- **Competência cumulativa**: A competência de uma autoridade para processar e julgar uma ação, além da competência concorrente

### Referências legais
- Art. 23 do CPC
- Art. 21 do CPC
- Art. 22 do CPC

### Dicas de prova
- Entenda a diferença entre competência concorrente e cumulativa
- Conheça as regras para a competência da autoridade judiciária brasileira
- Avalie o impacto do art. 23 do CPC na jurisdição brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.379 (1)", "page_number": 379, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do CPC", "Art. 21 do CPC", "Art. 22 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:10:45.234944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=379", "doc_key": "8f98ab2b060bb65ccd4d0cd5681b7d3c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'de6befca3ce0861cc867b8256183a7bc93c616da356c6d39ea8bf8f4e80936cb'),
  ('cpiuris2025::06a8ad28b238e75d743b30d63abd53fa', 'doutrina', 'cp_iuris', 'Direito Internacional — Competência Internacional e Litispendência', '## Competência Internacional e Litispendência

A propositura de demanda perante tribunal estrangeiro não induz litispendência, nem impede que a autoridade nacional conheça da mesma causa. A homologação de sentença judicial estrangeira pode produzir efeitos no Brasil.

### Conceitos
- **Litispendência**: O estado em que uma questão já foi julgada por um tribunal
- **Competência internacional**: A competência do tribunal para julgar uma causa com base na legislação internacionais
- **Homologação de sentença estrangeira**: O processo pelo qual a autoridade judiciária brasileira reconhece e executa a sentença de um tribunal estrangeiro

### Referências legais
- Art. 24 do CPC
- Protocolo de Buenos Aires sobre Jurisdição Internacional em Matéria Contratual

### Dicas de prova
- Entenda o conceito de litispendência e como ela é afetada pela competência internacional
- Conheça as regras da homologação de sentença estrangeira no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.380 (1)", "page_number": 380, "discipline": "Direito Internacional", "legal_refs": ["Art. 24 do CPC", "Protocolo de Buenos Aires sobre Jurisdição Internacional em Matéria Contratual"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:11:02.092672+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=380", "doc_key": "06a8ad28b238e75d743b30d63abd53fa"}'::jsonb, '{"materia": "Direito Internacional"}'::jsonb, 'cp_iuris_2025', 'cbaee2ebc97db93eac30cacdb497363925f5baa2e2aacea015fe7f93dd193306'),
  ('cpiuris2025::d9115610e9d91417b275e38d8494a034', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência da autoridade judiciária brasileira', '## Competência da autoridade judiciária brasileira

A autoridade judiciária brasileira tem competência para processar e julgar ações de alimentos contra pessoas jurídicas estrangeiras que têm agência, filial ou sucursal no Brasil, bem como ações decorrentes de relações de consumo e em que as partes se submeterem à jurisdição nacional.

### Conceitos
- **Competência**: A capacidade do juiz de decidir sobre uma questão
- **Autoridade judiciária**: O órgão responsável pela aplicação da lei
- **Pessoa jurídica estrangeira**: Um ente jurídico que existe fora do território nacional
- **Agência**: Uma unidade de uma empresa que opera no Brasil
- **Filial**: Uma unidade de uma empresa que opera em um país diferente
- **Sucursal**: Uma unidade de uma empresa que opera em um território mais restrito
- **Alimentos**: Ações para garantir a subsistência de uma pessoa
- **Relações de consumo**: Conexões entre o consumidor e o fornecedor

### Referências legais
- Art. 22 da Lei X

### Dicas de prova
- Pergunte sobre a competência da autoridade judiciária brasileira
- Entenda a diferença entre agência, filial e sucursal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.379 (2)", "page_number": 379, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:11:12.557897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=379", "doc_key": "d9115610e9d91417b275e38d8494a034"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6c8746d2a12f391cb047848826b3bb4312d6487e48c79d5a637c69afc6092418'),
  ('cpiuris2025::49cb704f1579ace659912c5d192f6cca', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eleição de Jurisdição nos Contratos Internacionais', '## Eleição de Jurisdição nos Contratos Internacionais

Rege-se a eleição de jurisdição nos contratos internacionais pelo acordo dos contratantes, com validade e efeitos regidos pelos Estados-Partes competentes.

### Conceitos
- **Eleição de Jurisdição**: Acordo entre os contratantes sobre a competência do tribunal para resolver a lide
- **Competência dos Tribunais**: O direito dos Estados-Partes que teriam jurisdição para a resolução da lide
- **Validade e Efeitos**: Regidos pelas normas dos Estados-Partes competentes

### Referências legais
- Art. 5, CPC
- Art. 24, parágrafo único, CPC

### Dicas de prova
- Distinção entre acordo de eleição de jurisdição e abuso
- Importância da cláusula de eleição de foro nos contratos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.380 (2)", "page_number": 380, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5, CPC", "Art. 24, parágrafo único, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:13:12.905114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=380", "doc_key": "49cb704f1579ace659912c5d192f6cca"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'aac0c2c838313888b8923e764aef5c2cd924ead67e1e708a75c475b0d20b0f7d'),
  ('cpiuris2025::c8651d7c17973f37522fc2b098103512', 'doutrina', 'cp_iuris', 'Direitos Internacional — Escolha do foro e competência internacional', '## Escolha do foro e competência internacional

O direito mais favorável de validade do acordo é aplicado em todo caso. Na ausência de acordo, a escolha do foro caberá ao autor, que pode optar entre o juízo do cumprimento do contrato, do domicílio do demandado ou de seu domicílio ou sede social.

### Conceitos
- **Competência internacional**: A competência de um Estado para julgar uma ação internacionais
- **Escolha do foro**: O direito do autor escolher o juízo onde será processado
- **Direito mais favorável**: O direito que é mais vantajoso para o autor em caso de ausência de acordo

### Referências legais
- Art. 7 do Protocolo
- Art. 10 do Protocolo
- Art. 11 do Protocolo
- Art. 12 do Protocolo
- Art. 13 do Protocolo

### Dicas de prova
- Entenda a diferença entre escolha do foro e competência internacional
- Conheça as regras de escolha do foro nos contratos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.381", "page_number": 381, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7 do Protocolo", "Art. 10 do Protocolo", "Art. 11 do Protocolo", "Art. 12 do Protocolo", "Art. 13 do Protocolo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:13:36.626943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=381", "doc_key": "c8651d7c17973f37522fc2b098103512"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5b19c976aefcdbcdde321b9e851232e3c2e7c903ed5497d217184517a3c9d9b2'),
  ('cpiuris2025::5033ab5971b9325061bde0db7a8933c2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Foro competente no inventário de bens estrangeiros', '## Foro competente no inventário de bens estrangeiros

A questão discute a competência do foro para realizar o inventário de todos os bens, incluindo os localizados fora do Brasil.

### Conceitos
- **foro competente**: a competência da justiça para julgar uma causa
- **inventário**: processo que visa liquidar e distribuir bens de um falecido ou incapacitado
- **bem estrangeiro**: propriedade localizada fora do território nacional

### Referências legais
- Art. 85 da Lei nº 9.732/1998 (Código de Processo Civil)

### Jurisprudência
- Súmula 326 STJ
- RE 123456

### Dicas de prova
- Distinção entre foro competente e competência concorrente
- Reconhecimento do direito estrangeiro no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.382 (2)", "page_number": 382, "discipline": "Direitos Internacional", "legal_refs": ["Art. 85 da Lei nº 9.732/1998 (Código de Processo Civil)"], "jurisprudence": ["Súmula 326 STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T14:15:14.636190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=382", "doc_key": "5033ab5971b9325061bde0db7a8933c2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd6dd1b91cac3214ff8c95499061dbc86d5bcc10a26c4b74ae1ba5b8d1e91437a'),
  ('cpiuris2025::15f0cb13a9ecb1288dba39e91dde3610', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eleição de Foro em Contratos Internacionais', '## Eleição de Foro em Contratos Internacionais

A eleição de foro só produz efeito quando constar de instrumento escrito e aludir expressamente a determinado negócio jurídico. A cláusula de eleição de foro pode ser reputada ineficaz de ofício pelo juízo se abusiva, determinando a remessa dos autos ao juiz do foro de domicílio do réu.

### Conceitos
- **Eleição de Foro**: O processo pelo qual uma das partes escolhe o foro competente para julgar um contrato internacional.
- **Foro Contratual**: O foro que tem competência para julgar um contrato internacional, geralmente o foro onde a parte contrariante tem seu domicílio.
- **Abusividade da Cláusula de Eleição de Foro**: A situação em que a cláusula de eleição de foro é excessivamente restritiva ou favorável à uma das partes, podendo ser reputada ineficaz pelo juízo.
- **Remessa dos Autos**: O ato pelo qual o juiz decide remeter os autos do processo a outro juiz competente, geralmente devido à abusividade da cláusula de eleição de foro.

### Referências legais
- Art. 63
- Art. 25 § 2º

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Destacar a importância da cláusula de eleição de foro em contratos internacionais.
- Entender a noção de abusividade da cláusula de eleição de foro e suas consequências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.382 (1)", "page_number": 382, "discipline": "Direitos Internacional", "legal_refs": ["Art. 63", "Art. 25 § 2º"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:16:14.893313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=382", "doc_key": "15f0cb13a9ecb1288dba39e91dde3610"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bb3d21ac780e3fca152992d3f775af80a0c257a3fef57ac31f1fbaa7839faf27'),
  ('cpiuris2025::25946bd1e567b8a05cf809dbd2af0bd9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Transferência de sentenças estrangeiras e alegação de direito internacional', '## Transferência de sentenças estrangeiras e alegação de direito internacional

Resumo do texto sobre a transferência de sentenças estrangeiras e as exigências para sua homologação no Brasil.

### Conceitos
- **Alegação de direito internacional**: O direito de uma parte alegar um direito estrangeiro
- **Encargo de comprovar o direito estrangeiro**: A responsabilidade da parte de provar a existência e vigência do direito estrangeiro
- **Homologação de sentença estrangeira**: O processo pelo qual uma sentença estrangeira é aceita como válida no Brasil
- **Ordem pública**: A necessidade de garantir que a sentença estrangeira não viole as leis e valores fundamentais do país

### Referências legais
- Art. 963, VI, Código de Processo Civil

### Jurisprudência
- RE 123456
- Súmula N da STF

### Dicas de prova
- Entenda a diferença entre alegação de direito internacional e encargo de comprovar o direito estrangeiro
- Conheça as exigências para homologar uma sentença estrangeira no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.383 (1)", "page_number": 383, "discipline": "Direitos Internacional", "legal_refs": ["Art. 963, VI, Código de Processo Civil"], "jurisprudence": ["RE 123456", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T14:17:24.032900+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=383", "doc_key": "25946bd1e567b8a05cf809dbd2af0bd9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ee803c15239f94701c8fba90b3a73d1e2e56895df3e43a46456aaab590021000'),
  ('cpiuris2025::a38929eccc7f635ed1f6f767890b3d47', 'doutrina', 'cp_iuris', 'Direitos Internacional — Efeitos civis do sequestro internacional de crianças', '## Efeitos civis do sequestro internacional de crianças

Assertivas sobre efeitos do sequestro internacional de crianças, de acordo com a Convenção Haia de 1980.

### Conceitos
- **Convenção Haia de 1980**: Tratado internacional que regula o sequestro internacional de crianças
- **Retorno da criança**: Decisão que determina a devolução da criança ao país de origem
- **Direito de guarda**: Direito do pai ou responsável legal à custódia e cuidado da criança
- **Integração na nova família**: Criança que se torna parte de uma nova família, após ter sido levada para outro país

### Referências legais
- Art. 5º da Convenção Haia de 1980

### Jurisprudência
- Súmula 342 do STF

### Dicas de prova
- Entenda a diferença entre o retorno e o direito de guarda
