  ('cpiuris2025::097c342c338622b1dc622ebc66d5b554', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica Internacional', '## Cooperação Jurídica Internacional

Regras para cooperação jurídica internacional, incluindo publicidade processual, autoridade central e reciprocidade.

### Conceitos
- **Reciprocidade**: Manifestação de cooperação por meio de diplomacia
- **Autoridade Central**: Entidade responsável pela cooperação jurídica internacional
- **Publicidade Processual**: Exceção para não divulgar informações em processos
- **Cooperação Jurídica Internacional**: Colaboração entre Estados sobre questões jurídicas

### Referências legais
- Art. 90 da Lei nº 9.472/1997

### Dicas de prova
- Distinção entre cooperação e reciprocidade
- Importância da autoridade central na cooperação jurídica internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.384 (2)", "page_number": 384, "discipline": "Direitos Internacional", "legal_refs": ["Art. 90 da Lei nº 9.472/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:19:13.847929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=384", "doc_key": "097c342c338622b1dc622ebc66d5b554"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bab67da973beee56f2f901bc57f664cf871b3e08903ac7385ac7d6a82bcfafc5'),
  ('cpiuris2025::a48a8bc1bb557abd57c1b8cf524cc185', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica Internacional', '## Cooperação Jurídica Internacional

A cooperação jurídica internacional é definida como o conjunto de técnicas que permitem a colaboração entre dois Estados para cumprir medidas jurisdicionais fora dos territórios. O artigo 26 do CPC estabelece normas gerais para essa cooperação, respeitando as garantias do devido processo legal e garantindo igualdade de tratamento.

### Conceitos
- **Cooperação Jurídica Internacional**: Colaboração entre dois Estados para cumprir medidas jurisdicionais fora dos territórios
- **Tratado de Cooperação Jurídica Internacional**: Acordo internacional que regula a cooperação jurídica entre os países
- **Garantias do Devido Processo Legal**: Direitos e garantias asseguradas ao réu no processo, como a igualdade de tratamento e a assistência judiciária

### Referências legais
- Art. 26 do CPC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de cooperação jurídica internacional e suas implicações
- Conheça as normas gerais estabelecidas pelo artigo 26 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.384 (1)", "page_number": 384, "discipline": "Direitos Internacional", "legal_refs": ["Art. 26 do CPC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:19:54.464143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=384", "doc_key": "a48a8bc1bb557abd57c1b8cf524cc185"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '470a2ff40551c27357f7499d17aad59c50106a7ca4b9ec5cbcd94332f4858aa4'),
  ('cpiuris2025::a5390590751a8ac49359783d0aa6aee1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Designação específica de tratados internacionais', '## Designação específica de tratados internacionais

O Brasil é parte de vários tratados internacionais, incluindo convenções e protocolos, que regulamentam questões como a repressão ao tráfico de pessoas, a prestação de alimentos no estrangeiro e a cooperação jurídica internacional.

### Conceitos
- **Autoridade central**: A entidade responsável por representar o Estado em uma relação internacional
- **Cooperação jurídica internacional**: A colaboração entre os países para resolver questões legais comuns
- **Tratados internacionais**: Acordos entre países que regulamentam questões específicas

### Referências legais
- Art. 27 do CPC
- Decreto n.º 46.981/1959

### Dicas de prova
- Entenda a noção de autoridade central e sua importância na cooperação internacional
- Conheça os diferentes tipos de tratados internacionais e suas áreas de aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.385", "page_number": 385, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27 do CPC", "Decreto n.º 46.981/1959"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:20:19.359017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=385", "doc_key": "a5390590751a8ac49359783d0aa6aee1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c627d06ed6450cae29a6874dd7fd9f2a623928d6f8d1ad5ce6909fbcc38245d8'),
  ('cpiuris2025::fe474535d1ecc5efd65eed87237fa0d8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência Jurisdicional em Auxílio Direto', '## Competência Jurisdicional em Auxílio Direto

A competência jurisdicional para os atos de auxílio-direto com necessidade de atuação judicial será da Justiça Federal, nos termos do art. 34 do CPC.

### Conceitos
- **Competência Jurisdicional**: A capacidade do Poder Judiciário para decidir um caso
- **Auxílio Direto**: A assistência direta de um Estado a outro em uma situação jurídica
- **Justiça Federal**: O sistema judiciário federal no Brasil

### Referências legais
- Art. 34 do CPC

### Dicas de prova
- Entenda a distinção entre auxílio direto e auxílio passivo
- Conheça a competência jurisdicional para os atos de auxílio-direto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.386 (2)", "page_number": 386, "discipline": "Direitos Internacional", "legal_refs": ["Art. 34 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:21:33.530145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=386", "doc_key": "fe474535d1ecc5efd65eed87237fa0d8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cdac4c69434f8f596c2b678f3561798173b902acfb25476fa8ea359f97da55cb'),
  ('cpiuris2025::b4d68b529bec700f1637c0aa7c38f1ca', 'doutrina', 'cp_iuris', 'Direitos Internacional — Auxílio-direto e cooperação internacional', '## Auxílio-direto e cooperação internacional

O auxílio-direto é uma técnica de cooperação internacional que permite a realização de atos jurídicos sem a necessidade da participação do Poder Judiciário requerido. É permitido em atos que não estão dotados de reserva de jurisdição, mas pode ser necessário a atuação judicial em decorrência de norma do ordenamento nacional.

### Conceitos
- **Auxílio-direto**: Técnica de cooperação internacional que permite a realização de atos jurídicos sem a necessidade da participação do Poder Judiciário requerido.
- **Cooperação internacional**: Relacionamento entre Estados ou organizações internacionais para alcançar objetivos comuns
- **Reserva de jurisdição**: Conceito jurídico que se refere à competência exclusiva do Poder Judiciário em determinadas questões
- **Carta rogatória**: Pedidos de cooperação jurídica internacional que envolvem a realização de atos judiciais

### Referências legais
- Art. 28 do Código de Processo Civil (CPC)
- Art. 29 do CPC
- Art. 216-O do Regimento Interno do Superior Tribunal de Justiça

### Dicas de prova
- Entenda a diferença entre auxílio-direto e cooperação internacional.
- Conheça as condições para a realização de atos jurídicos com auxílio-direto.
- Avalie a importância da reserva de jurisdição em determinadas questões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.386 (1)", "page_number": 386, "discipline": "Direitos Internacional", "legal_refs": ["Art. 28 do Código de Processo Civil (CPC)", "Art. 29 do CPC", "Art. 216-O do Regimento Interno do Superior Tribunal de Justiça"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:22:12.719027+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=386", "doc_key": "b4d68b529bec700f1637c0aa7c38f1ca"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'eb6d9651532815c42535d87d80d37f5ed9372104a8ed7c26878942e3400768b4'),
  ('cpiuris2025::612bb783b7308296cbe86c5f059cb0e1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Carta Rogatória', '## Carta Rogatória

A carta rogatória é o principal instrumento de cooperação judiciária internacional, sendo um pedido feito por um Estado estrangeiro ao juiz nacional para a prática de um ato processual. Ela deve ser escrita no idioma da justiça rogada e segue as normas da lex fori.

### Conceitos
- **Carta Rogatória**: Instrumento de cooperação judiciária internacional
- **Lex Fori**: Lei aplicável ao caso específico
- **Autoridade Central**: Entidade responsável pela cooperação jurídica internacional
- **Cooperação Jurídica Internacional**: Ação conjunta entre Estados para resolver disputas

### Referências legais
- Art. 36 do CPC
- Regimento Interno do STJ
- LINDB

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre carta rogatória ativa e passiva
- Conheça as normas da lex fori e suas implicações
- Avalie a importância da cooperação jurídica internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.387 (1)", "page_number": 387, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 do CPC", "Regimento Interno do STJ", "LINDB"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:22:38.166400+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=387", "doc_key": "612bb783b7308296cbe86c5f059cb0e1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bd4b1a11f900b2c2fdb58ca82d4f9bb3d87c19d6e5b9fb84a7df40c375607722'),
  ('cpiuris2025::bc0477b9bb09135ab11cbb4cfea72064', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurisdicional', '## Cooperação Jurisdicional

O pedido de cooperação jurisdicional deve ser encaminhado à autoridade central do Estado requerido, acompanhado de tradução para a língua oficial do Estado.

### Conceitos
- **Carta Rogatória Ativa**: documento que solicita cooperação jurisdicional
- **Autoridade Central**: entidade responsável pela cooperação jurisdicional
- **Tradução**: versão em língua oficial do Estado requerido

### Referências legais
- Art. 38 da Lei X
- Art. 260, 261 e 338 do CPC

### Dicas de prova
- Entenda a diferença entre carta rogatória ativa e passiva.
- Conheça os requisitos para a confecção da carta rogatória ativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.387 (2)", "page_number": 387, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 da Lei X", "Art. 260, 261 e 338 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:23:15.795058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=387", "doc_key": "bc0477b9bb09135ab11cbb4cfea72064"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5a017fc0c74dfe173afed31b4f05c8346bac586d0160c406b68aec848c6e320d'),
  ('cpiuris2025::90ee641fe638b65df919ce95c35992ed', 'doutrina', 'cp_iuris', 'Direitos Internacional — Carta Rogatória', '## Carta Rogatória

A carta rogatória é um ato processual que permite a coleta de provas fora do território nacional, sendo expedida pelo juiz e devendo ser autorizada por um órgão competente. O documento deve conter informações sobre o procedimento a ser adotado, as partes envolvidas e os requisitos necessários para a realização da diligência.

### Conceitos
- **Carta Rogatória**: Ato processual que permite a coleta de provas fora do território nacional
- **Expedição**: Ação do juiz para realizar a diligência
- **Autorização**: Requisito para a expedição da carta rogatória, necessária para que o documento seja válido
- **Provas**: Documentos ou informações coletadas durante a diligência
- **Diligência**: Ação realizada pelo juiz para coletar provas fora do território nacional
- **Competência**: Requisito para a expedição da carta rogatória, necessária para que o documento seja válido

### Referências legais
- Art. 261
- Art. 377
- Parágrafo único de Art. 377

### Jurisprudência
- HC 87759 ED
- ...

### Dicas de prova
- Entenda a competência para a expedição da carta rogatória
- Conheça os requisitos necessários para a expedição do documento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.388 (1)", "page_number": 388, "discipline": "Direitos Internacional", "legal_refs": ["Art. 261", "Art. 377", "Parágrafo único de Art. 377"], "jurisprudence": ["HC 87759 ED", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:24:17.622061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=388", "doc_key": "90ee641fe638b65df919ce95c35992ed"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9586e05f1cd1a1395600638b05397a1b429456dc1b88d0d09449247d656c7deb'),
  ('cpiuris2025::7589edb8230cede28bfcf8196da7758a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica e Soberania', '## Cooperação Jurídica e Soberania

A cooperação jurídica entre Brasil e Itália é permitida, mas com limites. O Ministério Público Italiano não tem competência para determinar a quebra de sigilo bancário ou sequestro de valores. A expedição de carta rogatória em matéria de sucessões é rejeitada pelo Superior Tribunal de Justiça por falta de motivo de ordem pública.

### Conceitos
- **Cooperação Jurídica**: A colaboração entre juízes e procuradores de diferentes países para resolver questões jurídicas.
- **Soberania**: O direito de um Estado de governar-se a si mesmo, sem interferência de outros Estados.
- **Carta Rogatória**: Uma petição formal que pede ajuda de outro país para obter informações ou provas em uma investigação.
- **Sequestro de Valores**: A ação de tomar posse de bens ou valores de alguém sem o seu consentimento.
- **Pluralidade dos Juízos Sucessórios**: O princípio que estabelece que cada país tem seu próprio sistema de sucessões e não pode ser obrigado a aplicar o sistema de outro país.

### Referências legais
- CPC, art. 23, II

### Jurisprudência
- RE 123456
- AgRg na CR .998/IT

### Dicas de prova
- Pergunte sobre a cooperação jurídica e soberania em contextos internacionais.
- Entenda o conceito de carta rogatória e suas limitações.
- Conheça o princípio da pluralidade dos juízos sucessórios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.388 (2)", "page_number": 388, "discipline": "Direitos Internacional", "legal_refs": ["CPC, art. 23, II"], "jurisprudence": ["RE 123456", "AgRg na CR .998/IT"], "confidence": 0.8, "extracted_at": "2026-05-31T14:24:29.301913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=388", "doc_key": "7589edb8230cede28bfcf8196da7758a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5612e35c6ca70bc5e0c5c0b2cf088358d7e325dfc897431835c7ed2233f65d2f'),
  ('cpiuris2025::6c7594a3308d9695411480bbf13b8515', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência para conceder exequatur às cartas rogatórias', '## Competência para conceder exequatur às cartas rogatórias

A competência para conceder o exequatur às cartas rogatórias é do Presidente do STJ ou da Corte Especial, nos termos dos arts. 216-O e 216-T do RISTJ.

### Conceitos
- **Exequatur**: Concessão de eficidade a uma decisão estrangeira
- **Competência**: Atribuição para tomar uma decisão em um caso específico
- **Rogatória**: Pedidos de cooperação jurídica internacional
- **Tradução**: Conversão de documentos de um idioma para outro
- **Autenticidade**: Verificação da autenticidade de um documento
- **Soberania nacional**: Direito do Estado de controlar suas próprias ações e decisões
- **Ordem pública**: Condição necessária para que uma ação ou decisão seja válida

### Referências legais
- Art. 216-O do RISTJ
- Art. 216-T do RISTJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência para conceder exequatur às cartas rogatórias
- Conheça as regras de autenticidade e tradução de documentos estrangeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.390 (1)", "page_number": 390, "discipline": "Direitos Internacional", "legal_refs": ["Art. 216-O do RISTJ", "Art. 216-T do RISTJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:27:00.996292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=390", "doc_key": "6c7594a3308d9695411480bbf13b8515"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e4c5f6ffe454d5514bc30201a8797101c5302a40918d1ff26c114e8fa85b747e'),
  ('cpiuris2025::3b6f7e8ed45359f696e70752bf407fed', 'doutrina', 'cp_iuris', 'Direitos Internacional — Requerimento para expedição de carta rogatória com o objetivo de obter informações a respeito de eventuais depósitos bancários na Suíça', '## Requerimento para expedição de carta rogatória com o objetivo de obter informações a respeito de eventuais depósitos bancários na Suíça

O requerimento de carta rogatória é inviável se for destinado a obter informações sobre depósitos bancários no estrangeiro, pois o princípio da pluralidade de juízos sucessórios torna inviável processar esse tipo de informação no Brasil.

### Conceitos
- **Princípio da territorialidade**: Rege a competência dos tribunais brasileiros sobre bens estrangeiros
- **Pluralidade de juízos sucessórios**: Permite que cada país tenha seu próprio sistema de sucessão de bens
- **Carta rogatória**: Instrumento processual utilizado para obter informações ou provas em outro país

### Referências legais
- Art. 23, II, do CPC/2015
- Art. 89, II, do CPC/1973
- CPC, Art. 377

### Jurisprudência
- REsp 397769/SP
- AgInt no AREsp 1297819/SP

### Dicas de prova
- Distinção entre o princípio da territorialidade e a pluralidade de juízos sucessórios
- Inviabilidade do requerimento de carta rogatória para obter informações sobre depósitos bancários no estrangeiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.389 (1)", "page_number": 389, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23, II, do CPC/2015", "Art. 89, II, do CPC/1973", "CPC, Art. 377"], "jurisprudence": ["REsp 397769/SP", "AgInt no AREsp 1297819/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T14:27:11.956451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=389", "doc_key": "3b6f7e8ed45359f696e70752bf407fed"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4f7b5af541f385092410bd796b52bb32fd9329053c56ee880c211771417816f1'),
  ('cpiuris2025::cf27bac19faebc02f49cb99a7b2136dd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Citação por Edital e Exequatur', '## Citação por Edital e Exequatur

Regra sobre a necessidade de exequatur para carta rogatória cumprida no Brasil.

### Conceitos
- **Carta Rogatória**: Documento que solicita informações ou provas a uma autoridade estrangeira.
- **Exequatur**: Concessão de autoridade para cumprir uma ordem estrangeira.
- **Citação por Edital**: Método de notificação formal para citação de partes em um processo.
- **Autoridade Estrangeira Competente**: Entidade que tem jurisdição para processar uma questão ou solicitar informações.
- **Diligências Deprecadas**: Ações necessárias para cumprir uma ordem estrangeira.
- **Superior Tribunal de Justiça (STJ)**: Entidade que tem jurisdição para homologar sentenças estrangeiras e conceder exequatur.
- **Constituição Brasileira**: Documento que estabelece as regras básicas do país.
- **Lei de Introdução às Normas do Direito Brasileiro**: Legislação que regula a interpretação das leis brasileiras.

### Referências legais
- Art. 105, I, ''i'' da Constituição
- Art. 12, § 2º, da Lei de Introdução às Normas do Direito Brasileiro

### Dicas de prova
