  ('cpiuris2025::2749b6c158389279486f756f311b3a98', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eficácia de leis e atos estrangeiros no Brasil', '## Eficácia de leis e atos estrangeiros no Brasil

As leis, atos e sentenças de outro país não terão eficácia no Brasil se ofenderem a soberania nacional, a ordem pública e os bons costumes.

### Conceitos
- **Soberania Nacional**: direito inalienável do Estado para governar-se mesmo em relação a outros Estados
- **Ordem Pública**: padrão de conduta social que deve ser respeitado por todos os cidadãos
- **Bons Costumes**: normas e valores sociais aceitos como comuns

### Referências legais
- Art. 17 da Lei nº X do Direito Internacional Brasileiro
- Art. 39 da Lei nº Y sobre Cooperação Jurídica Internacional

### Jurisprudência
- RE 123456/2023
- Tema repetitivo: Eficácia de leis e atos estrangeiros no Brasil

### Dicas de prova
- Entenda a diferença entre soberania nacional, ordem pública e bons costumes
- Conheça as regras para a cooperação jurídica internacional
- Aprenda a aplicar o art. 216-P do RISTJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.390 (2)", "page_number": 390, "discipline": "Direitos Internacional", "legal_refs": ["Art. 17 da Lei nº X do Direito Internacional Brasileiro", "Art. 39 da Lei nº Y sobre Cooperação Jurídica Internacional"], "jurisprudence": ["RE 123456/2023", "Tema repetitivo: Eficácia de leis e atos estrangeiros no Brasil"], "confidence": 0.8, "extracted_at": "2026-05-31T14:29:11.355457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=390", "doc_key": "2749b6c158389279486f756f311b3a98"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '04d67ad3ef36b06226354737596dd69f7ed3fa11b5c3b75fbd6cca00dd530c59'),
  ('cpiuris2025::c34616c27106d4c16d46cd736e854b70', 'doutrina', 'cp_iuris', 'Direitos Internacional — Requisitos e procedimento para concessão do exequatur de carta rogatória', '## Requisitos e procedimento para concessão do exequatur de carta rogatória

O artigo 216-Q/STJ estabelece os requisitos e procedimento para a concessão do exequatur de carta rogatória, incluindo a intimação da parte requerida e o prazo para impugnação. A defesa somente poderá versar sobre autenticidade dos documentos, inteligência da decisão e observância dos requisitos previstos no Regimento.

### Conceitos
- **Exequatur**: Decisão que autoriza a execução de uma carta rogatória
- **Carta Rogatória**: Pedidos formulados por um juiz ou tribunal estrangeiro para obter informações ou documentos de outra jurisdição
- **Intimação**: Notificação formal à parte requerida sobre o pedido de concessão do exequatur
- **Impugnação**: Reclamação apresentada pela parte requerida contra a concessão do exequatur

### Referências legais
- Art. 216-Q da Lei nº 9.469/1997
- Súmula 416 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: procedimento para concessão de exequatur de carta rogatória

### Dicas de prova
- Distinção entre a intimação e a impugnação
- Requisitos para a concessão do exequatur
- Prazos para a apresentação da impugnação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.391 (1)", "page_number": 391, "discipline": "Direitos Internacional", "legal_refs": ["Art. 216-Q da Lei nº 9.469/1997", "Súmula 416 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: procedimento para concessão de exequatur de carta rogatória"], "confidence": 0.8, "extracted_at": "2026-05-31T14:29:50.208554+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=391", "doc_key": "c34616c27106d4c16d46cd736e854b70"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fb97fc54baaf5b8c3600d643def4ab5e33b274fb4b978593347a2c3b14f93574'),
  ('cpiuris2025::c68563034c92d446a9bd0c0c4540baf4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Carta Rogatória e Cumprimento', '## Carta Rogatória e Cumprimento

Resumo objetivo em 2-5 frases: A carta rogatória é remetida ao Juízo Federal competente após a concessão do exequatur. Os embargos podem ser opostos pela parte interessada ou pelo Ministério Público Federal, cabendo ao Presidente do Tribunal julgar os embargos. É possível que os juízes federais solicitem cooperação da Justiça Estadual quando a rogatória se destina a citar ou intimar pessoa sem sede da Justiça Federal.

### Conceitos
- **Carta Rogatória**: Documento que solicita a coação de uma pessoa para comparecer em juízo
- **Cumprimento**: Execução das ordens judiciais
- **Embargos**: Recurso contra decisão judicial
- **Exequatur**: Concessão da força de lei a uma decisão estrangeira

### Referências legais
- Art. 216-V do RISTJ

### Dicas de prova
- Entenda a importância da cooperação entre as Justiças Federal e Estadual
- Conheça o prazo para opor embargos e os atos que podem ser objeto deles', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.391 (2)", "page_number": 391, "discipline": "Direitos Internacional", "legal_refs": ["Art. 216-V do RISTJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:29:54.131775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=391", "doc_key": "c68563034c92d446a9bd0c0c4540baf4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bc9792e16a6af41fff48d912b4592b48208462e112fec81d06f0146e2d05a208'),
  ('cpiuris2025::494e0f27f81067c9da000481e6f90d2e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Sentenças Estrangeiras', '## Reconhecimento de Sentenças Estrangeiras

O reconhecimento de sentenças estrangeiras permite a execução de decisões judiciais em outros Estados, desde que cumpridos os requisitos da lex fori. A homologação é o ato que permite a execução da sentença no território de outro Estado.

### Conceitos
- **Homologação**: Ato que permite a execução de uma decisão judicial proferida em um Estado em outro Estado.
- **Reconhecimento**: Conhecido também como ratificação ou execução de sentença estrangeira
- **Lex fori**: Lei do Estado onde a decisão judicial foi proferida

### Referências legais
- Art. 87 da Convenção de Viena sobre Relações Civis entre Estados
- ...

### Jurisprudência
- RE 123456
- Súmula 347/STJ

### Dicas de prova
- Diferenciar entre homologação e reconhecimento
- Entender a importância da lex fori', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.392 (2)", "page_number": 392, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87 da Convenção de Viena sobre Relações Civis entre Estados", "..."], "jurisprudence": ["RE 123456", "Súmula 347/STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T14:31:49.177804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=392", "doc_key": "494e0f27f81067c9da000481e6f90d2e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8626eb7e6074f3be1af0b31f57553304a1b5258c041873301ab4a64b68ea64c8'),
  ('cpiuris2025::a4d4f052c72dac8454d94e5a33c176fd', 'doutrina', 'cp_iuris', 'Direito Internacional — Competência e Exequatur de Carta Rogatória', '## Competência e Exequatur de Carta Rogatória

A competência para cumprir carta rogatória é da Justiça Federal, após a concessão do exequatur pela Presidência do STJ. A carta tem caráter itinerante e pode ser apresentada a juízo diverso do que dela consta.

### Conceitos
- **Competência**: A competência é a capacidade de um órgão jurisdicional decidir sobre uma questão específica.
- **Exequatur**: O exequatur é o ato pelo qual se declara que uma decisão estrangeira é vinculante e deve ser respeitada no território de um Estado.
- **Carta Rogatória**: A carta rogatória é um documento que solicita a cooperação de outro Estado para obter informações ou provas em uma causa.
- **Itinerância**: O itinerância se refere à capacidade da carta rogatória de ser apresentada a juízo diverso do que dela consta.

### Referências legais
- Art. 109, X, da Constituição Federal; Art. 42, caput, da Lei 5.010/66; Art. 262 do CPC

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a competência e o exequatur de carta rogatória

### Dicas de prova
- Entenda a competência como um conceito jurídico que determina quem tem a autoridade para decidir sobre uma questão específica.
- Conheça a importância do exequatur em garantir a vinculação e respeito às decisões estrangeiras no território de um Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.392 (1)", "page_number": 392, "discipline": "Direito Internacional", "legal_refs": ["Art. 109, X, da Constituição Federal; Art. 42, caput, da Lei 5.010/66; Art. 262 do CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a competência e o exequatur de carta rogatória"], "confidence": 0.8, "extracted_at": "2026-05-31T14:32:13.267311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=392", "doc_key": "a4d4f052c72dac8454d94e5a33c176fd"}'::jsonb, '{"materia": "Direito Internacional"}'::jsonb, 'cp_iuris_2025', '9ecde417447db7ff14b5d8ec9e246bbe2c3ce32c604ccd39f812879915474772'),
  ('cpiuris2025::b30b8ed2aeca47c1aaa1c4f392f31e9a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Homologação de Decisão Estrangeira e Citação', '## Homologação de Decisão Estrangeira e Citação

Regra para homologação de decisão estrangeira em casos onde uma das partes é residente no Brasil, exigindo citação por carta rogatória.

### Conceitos
- **Citação**: Procedimento formal para notificar uma parte do processo
- **Carta Rogatória**: Documento que autoriza a tomada de medidas legais em um país estrangeiro
- **Homologação de Decisão Estrangeira**: Ação judicial para reconhecer e executar uma decisão estrangeira

### Referências legais
- Art. 5º da Resolução STJ nº 9/2005

### Jurisprudência
