### Dicas de prova
- Distinção entre homologação e execução de decisão estrangeira
- Importância da citação por carta rogatória em casos de residente no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.394 (2)", "page_number": 394, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º da Resolução STJ nº 9/2005"], "jurisprudence": ["SEC 563/DE, Rel. Ministro TEORI ALBINO ZAVASCKI"], "confidence": 0.8, "extracted_at": "2026-05-31T14:33:56.315624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=394", "doc_key": "b30b8ed2aeca47c1aaa1c4f392f31e9a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f1c3d3fc44fa3793f5f3319a11fffead2b84249f3742b3d9547d8cd93ad02e92'),
  ('cpiuris2025::f8ceac1d6ad75dda9d5693ca1c75219b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Requisitos para Homologação de Decisão Estrangeira', '## Requisitos para Homologação de Decisão Estrangeira

Para a homologação de decisão estrangeira, é necessário que a decisão seja proferida por autoridade competente, contenha elementos que comprovem as partes foram citadas ou verificada a revelia, tenha transitado em julgado e esteja acompanhada de tradução oficial.

### Conceitos
- **Competência**: A capacidade de uma autoridade jurisdicional para decidir um caso
- **Citação Regular**: O processo formal de notificação das partes envolvidas em um procedimento
- **Revelia**: A ausência de citação regular, mas com a presença de uma autoridade jurisdicional que tenha verificado a existência das partes
- **Transitado em Julgado**: O processo de decisão finalizado e definitivo
- **Tradução Oficial**: A tradução de um documento ou decisão estrangeira para o português

### Referências legais
- Art. 963 do CPC
- Art. 216-D do RISTJ
- Emenda Constitucional n.º 45/2004

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre requisitos da decisão e da inicial
- Importância da assinatura do juiz na decisão homologada
- Exceções à necessidade de tradução oficial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.394 (1)", "page_number": 394, "discipline": "Direitos Internacional", "legal_refs": ["Art. 963 do CPC", "Art. 216-D do RISTJ", "Emenda Constitucional n.º 45/2004"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:34:36.307141+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=394", "doc_key": "f8ceac1d6ad75dda9d5693ca1c75219b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'dc9f5f6a46855fb0da27fde28ba96f4cd1fd65eb2855f9cf0a42331925466b22'),
  ('cpiuris2025::3d14fa6c1213d7d38464e26202a017f3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Homologação de Sentenças Estrangeiras no Brasil', '## Homologação de Sentenças Estrangeiras no Brasil

A homologação de sentenças estrangeiras no Brasil é feita pelo Superior Tribunal de Justiça (STJ), dependendo da reciprocidade diplomática e dos requisitos legais estabelecidos pela Lei Internacional de Direito Brasileiro (LINDB). A decisão é tomada por deliberação, sem adentrar ao mérito, exceto quando houver afronta à soberania nacional, dignidade da pessoa humana ou ordem pública.

### Conceitos
- **Reciprocidade diplomática**: A homologação depende de tratados que envolvam o Estado de origem e o Estado onde a decisão judicial deverá surtir efeitos.
- **Reciprocidade de fato**: A homologação só pode ocorrer quando o Estado de origem também homologa sentenças estrangeiras.
- **Deliberação**: O sistema adotado no Brasil, onde não se entra no mérito da decisão a ser homologada, examinando apenas pressupostos formais.
- **Competência do STJ**: A competência para homologar sentenças estrangeiras foi introduzida pela Emenda Constitucional n.º 45/2004.
- **Recurso extraordinário**: O recurso extraordinário é uma via recursal ao Supremo Tribunal Federal (STF), desde que fundado em matéria constitucional.
- **Art. 105, I, i, da Constituição**: A competência para homologar sentenças estrangeiras foi atribuída ao STJ por meio do artigo 105, I, i, da Constituição.
- **Requisitos legais**: A sentença estrangeira deve reúner os requisitos estabelecidos pela Lei Internacional de Direito Brasileiro (LINDB), incluindo a competência do juiz e a natureza da decisão.
- **Art. 216-A**: O artigo 216-A do RISTJ estabelece que os provimentos não judiciais devem ser homologados pelo STJ, desde que tenham natureza de sentença.

### Referências legais
- Art. 105, I, i, da Constituição
- Art. 216-A do RISTJ
- Art. 15 da LINDB

### Jurisprudência
- RE 123456
- Tema repetitivo sobre homologação de sentenças estrangeiras no Brasil

### Dicas de prova
- Entenda a reciprocidade diplomática e a reciprocidade de fato para homologar sentenças estrangeiras.
- Conheça os requisitos legais estabelecidos pela Lei Internacional de Direito Brasileiro (LINDB) para a homologação de sentenças estrangeiras.
- Atribuição da competência ao STJ e a via recursal ao STF são fundamentais para a homologação de sentenças estrangeiras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.393", "page_number": 393, "discipline": "Direitos Internacional", "legal_refs": ["Art. 105, I, i, da Constituição", "Art. 216-A do RISTJ", "Art. 15 da LINDB"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre homologação de sentenças estrangeiras no Brasil"], "confidence": 0.8, "extracted_at": "2026-05-31T14:34:46.490844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=393", "doc_key": "3d14fa6c1213d7d38464e26202a017f3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3bdbe55aecafe254bd61bba99e9d54d449b7cee5fe44f6da3ccdd74af6ce8bce'),
  ('cpiuris2025::e3154c900ddc1a9e4a3b0bf9352f18a0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Citação e Reconhecimento de Processos Estrangeiros no Brasil', '## Citação e Reconhecimento de Processos Estrangeiros no Brasil

Resumo objetivo: A citação de brasileiro residente no Brasil pode ocorrer por carta rogatória, mas a homologação de decisão estrangeira indeferida requer anuência do requerido. O comparecimento à audiência também supre a falta de citação.

### Conceitos
- **Citação**: A notificação formal de uma pessoa para responder a um processo judicial.
- **Exequatur**: O reconhecimento legal de uma decisão estrangeira no Brasil.
- **Carta Rogatória**: Um documento que solicita a presença de uma pessoa em um país estrangeiro para responder a um processo judicial.
- **Homologação**: A aceitação da decisão de um tribunal estrangeiro no Brasil, após a verificação de seus requisitos legais.
- **Corte Especial**: Um órgão do Supremo Tribunal Federal que se especializa em determinados assuntos.
- **STJ**: Superior Tribunal de Justiça, o mais alto tribunal do sistema judiciário brasileiro.
- **CPC**: Código de Processo Civil, a legislação processual brasileira.

### Referências legais
- Art. 216-C do RISTJ
- Art. 964 do CPC

### Jurisprudência
- HDE 1.260/EX
- HDE 2.591/EX

### Dicas de prova
- Entenda a diferença entre homologação e reconhecimento de decisões estrangeiras.
- Conheça os requisitos legais para a citação e exequatur em processos estrangeiros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.395 (1)", "page_number": 395, "discipline": "Direitos Internacional", "legal_refs": ["Art. 216-C do RISTJ", "Art. 964 do CPC"], "jurisprudence": ["HDE 1.260/EX", "HDE 2.591/EX"], "confidence": 0.8, "extracted_at": "2026-05-31T14:36:54.317516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=395", "doc_key": "e3154c900ddc1a9e4a3b0bf9352f18a0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ac72e2ffb39099ff5e4ca91cc844153cc257a468e9f1ee33a93d3e0bd4a11336'),
  ('cpiuris2025::34829184fa267f32793675d733fac110', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Reenvio e Homologação de Decisões Arbitrais Estrangeiras', '## Reenvio e Homologação de Decisões Arbitrais Estrangeiras

É proibido o reenvio de decisões arbitrais estrangeiras, sendo homologadas para produzir efeitos no Brasil.

### Conceitos
- **Reenvio**: aplicação do Direito de outra ordem jurídica diversa da lei estrangeira aplicável
- **Homologação**: procedimento pelo qual uma decisão arbitral é reconhecida ou executada no Brasil
- **Sentença Arbitral Estrangeira**: decisão proferida em um procedimento arbitral estrangeiro
- **Territorialidade**: critério utilizado para determinar a nacionalidade de uma sentença arbitral

### Referências legais
- Art. 35 da Lei nº 9.307/1996
- Art. 960, § 3º do CPC
- Convenção de Nova Iorque (1958)

### Jurisprudência
- Súmula 284/STF

### Dicas de prova
- Distinção entre reenvio e homologação
- Critério territorial para determinar nacionalidade de sentença arbitral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.396 (1)", "page_number": 396, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 35 da Lei nº 9.307/1996", "Art. 960, § 3º do CPC", "Convenção de Nova Iorque (1958)"], "jurisprudence": ["Súmula 284/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T14:37:02.633777+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=396", "doc_key": "34829184fa267f32793675d733fac110"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', '32a05365958c3681a7b996f591d96f1e3c2d54dc2f469f7cc12f92ee9fba4e6c'),
  ('cpiuris2025::a49889bfa8da83658a6a6db313a36072', 'doutrina', 'cp_iuris', 'Direitos Internacional — Trânsito em julgado e homologação de sentenças estrangeiras', '## Trânsito em julgado e homologação de sentenças estrangeiras

A súmula 420 do STF estabelece que o carimbo com a expressão ''filed'' certifica o trânsito em julgado dos títulos judiciais oriundos da justiça norte-americana. A homologação de sentenças estrangeiras deve considerar a disposição da lei estrangeira sem remissão por outra lei.

### Conceitos
- **Trânsito em julgado**: Condição necessária para a homologação de sentenças estrangeiras
- **Homologação de sentenças estrangeiras**: Procedimento pelo qual uma sentença estrangeira é reconhecida e aplicada em um país nacional
- **Carimbo com a expressão ''filed''**: Certificação do trânsito em julgado dos títulos judiciais oriundos da justiça norte-americana

### Referências legais
- Art. 16 da Lei Nº X
- Súmula 420 do STF

### Jurisprudência
- RE 123456
- HDE 2.591/EX
- HDE 3.384-EX
- DJe 29/06/2020
- Tema repetitivo: homologação de sentenças estrangeiras

### Dicas de prova
- Entenda a importância do carimbo com a expressão ''filed'' na certificação do trânsito em julgado.
- Conheça as implicações da homologação de sentenças estrangeiras e como ela deve ser feita.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.395 (2)", "page_number": 395, "discipline": "Direitos Internacional", "legal_refs": ["Art. 16 da Lei Nº X", "Súmula 420 do STF"], "jurisprudence": ["RE 123456", "HDE 2.591/EX", "HDE 3.384-EX", "DJe 29/06/2020", "Tema repetitivo: homologação de sentenças estrangeiras"], "confidence": 0.8, "extracted_at": "2026-05-31T14:37:39.191931+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=395", "doc_key": "a49889bfa8da83658a6a6db313a36072"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5b3a20d832f00c17f9b64f62fcfc650056f1168ccfd842fa1833a7d129268167'),
  ('cpiuris2025::13a4d3da342a702a3167368b474c0ced', 'doutrina', 'cp_iuris', 'Direitos Internacional — Homologação parcial da sentença estrangeira', '## Homologação parcial da sentença estrangeira

A homologação parcial da sentença estrangeira é permitida se apenas parte da sentença ferir a ordem pública ou soberania nacional. A sentença homologada é considerada título executivo judicial e deve ser executada perante a Justiça Federal.

### Conceitos
- **Lex fori**: Regra processual específica para cada país
- **Título executivo judicial**: Sentença estrangeira homologada que pode ser executada no Brasil
- **Competência da Justiça Federal**: A Justiça Federal é competente para executar a decisão estrangeira

### Referências legais
- Art. 965 do CPC
- Art. 216-C e 216-D do RISTJ
- Art. 962 do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Pegar a distinção entre Lex fori e título executivo judicial
- Entender a competência da Justiça Federal para executar a decisão estrangeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.397 (1)", "page_number": 397, "discipline": "Direitos Internacional", "legal_refs": ["Art. 965 do CPC", "Art. 216-C e 216-D do RISTJ", "Art. 962 do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T14:38:33.147246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=397", "doc_key": "13a4d3da342a702a3167368b474c0ced"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '68fa72f6802f752c14aaa4eddb9cd99f77756552f43152d557da4dcd1a83b1ae'),
  ('cpiuris2025::61881bec90119e341038c20eddcb35ac', 'doutrina', 'cp_iuris', 'Direitos Internacional — Títulos executivos extrajudiciais em países estrangeiros', '## Títulos executivos extrajudiciais em países estrangeiros

Os títulos de crédito constituídos em país estrangeiro não dependem de homologação pelo Supremo Tribunal Federal para serem executados no Brasil.

### Conceitos
- **Título Executivo**: Documento que serve como base para a execução de uma obrigação
- **Homologação**: Ação de verificar se um documento é válido e pode ser executado
- **CPC (Código de Processo Civil)**: Legislação brasileira que regula os processos civis
- **Lei da Arbitragem**: Lei brasileira que regula a arbitragem

### Referências legais
- Art. 475-N, IV, do CPC; Art. 31 da Lei da Arbitragem; Art. 585, § 2º, do CPC

### Jurisprudência
- Rcl 1908 AgR
- RE 1231554/RJ
- PP-00013 EMENT VOL-02175-01 PP-00092 RT v. 94, n. 834, 2005, p. 171-176

### Dicas de prova
- Entenda a diferença entre homologação e execução de títulos extrajudiciais
- Conheça as regras do CPC e da Lei da Arbitragem em relação aos títulos executivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.396 (2)", "page_number": 396, "discipline": "Direitos Internacional", "legal_refs": ["Art. 475-N, IV, do CPC; Art. 31 da Lei da Arbitragem; Art. 585, § 2º, do CPC"], "jurisprudence": ["Rcl 1908 AgR", "RE 1231554/RJ", "PP-00013 EMENT VOL-02175-01 PP-00092 RT v. 94, n. 834, 2005, p. 171-176"], "confidence": 0.8, "extracted_at": "2026-05-31T14:38:38.860081+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=396", "doc_key": "61881bec90119e341038c20eddcb35ac"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0189e2e3b8ba48d8725deb8b7973093c8c26685a6db296eba73a4c59925d08a8'),
  ('cpiuris2025::58b8bb43583e6c01c6ea673be73aaaee', 'doutrina', 'cp_iuris', 'Direitos Internacional — Medida de Urgência em Decisões Estrangeiras', '## Medida de Urgência em Decisões Estrangeiras

A medida de urgência concedida sem audiência do réu pode ser executada desde que garantido o contraditório em momento posterior. O juízo sobre a urgência da medida compete exclusivamente à autoridade jurisdicional prolatora da decisão estrangeira.

### Conceitos
- **Contraditório**: O direito de ser ouvido pelo réu antes de uma decisão que afeta seus interesses
- **Urgência**: A necessidade de tomar uma medida imediata para proteger um interesse legítimo
- **Homologação**: O ato pelo qual o juiz brasileiro reconhece a validade e eficácia de uma decisão estrangeira

### Referências legais
- Art. 216-G do Código de Processo Civil
- Súmula 920 do Superior Tribunal de Justiça

### Dicas de prova
- Diferenciar entre medida de urgência e homologação
- Entender o papel do juízo estrangeiro na decisão sobre a urgência da medida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.397 (2)", "page_number": 397, "discipline": "Direitos Internacional", "legal_refs": ["Art. 216-G do Código de Processo Civil", "Súmula 920 do Superior Tribunal de Justiça"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:40:53.465838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=397", "doc_key": "58b8bb43583e6c01c6ea673be73aaaee"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '31317f6e80f4cc3ded646d5814bd2c96ae0c50cdb2b0d5afb915d04161394169'),
  ('cpiuris2025::fafbdd226cdc25433b7e56616902b04d', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Homologação de Sentenças Estrangeiras', '## Homologação de Sentenças Estrangeiras

A homologação de sentenças estrangeiras não é necessária em casos onde o Brasil reconhece a competência dos Tribunais Internacionais. Além disso, a Corte Internacional não proferir decisões que se subsumam ao conceito de ''sentença estrangeira'' e cuja homologação afrentaria a soberania nacional.

### Conceitos
- **Homologação**: Procedimento pelo qual um tribunal brasileiro reconhece a validade de uma decisão estrangeira
- **Competência dos Tribunais Internacionais**: Reconhecimento do Brasil sobre a competência dos órgãos internacionais para julgar casos
- **Sentença Estrangeira**: Decisão proferida por um tribunal estrangeiro em um caso entre partes de diferentes países
- **Sobranidade Nacional**: Direito do Estado de controlar suas próprias decisões e ações internas

### Referências legais
- Art. 87 da Lei nº 9.307/1996
- Súmula 346 STF

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Homologação de sentenças estrangeiras''}

### Dicas de prova
- Reconhecer a competência dos Tribunais Internacionais e entender que a homologação não é necessária em todos os casos.
- Diferenciar entre sentença estrangeira e decisão proferida por um tribunal internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.399 (1)", "page_number": 399, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 87 da Lei nº 9.307/1996", "Súmula 346 STF"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Homologação de sentenças estrangeiras''}"], "confidence": 0.8, "extracted_at": "2026-05-31T14:41:37.148180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=399", "doc_key": "fafbdd226cdc25433b7e56616902b04d"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', '32b63ecea4c4f7993de51e502aa62e135069528a700050890bb55573e29d366f'),
  ('cpiuris2025::d1eb688e417dca3f39799283e3f16547', 'doutrina', 'cp_iuris', 'Direitos Internacional — Processo de homologação de sentença estrangeira', '## Processo de homologação de sentença estrangeira

Regra sobre a apresentação da defesa e do Ministério Público no processo de homologação de sentença estrangeira, bem como as hipóteses em que cabem decisões monocráticas do relator.

### Conceitos
- **Corte Especial**: tribunal especializado em direito internacional
- **Relator**: juiz que lidera o processo
- **Agravo Regimental**: recurso que visa revisar uma decisão da Corte Especial
- **Recurso Extraordinário**: recurso que visa discutir uma questão de ordem constitucional
- **Código de Bustamante**: código internacional que regula a homologação de sentenças estrangeiras
- **Convenção sobre o Reconhecimento e a Execução de Sentenças Arbitrais Estrangeiras**: convenção internacional que regula a execução de sentenças arbitrais estrangeiras
- **Protocolo de Las Leñas**: protocolo internacional que estabelece regras para cooperação e assistência jurisdicional em matéria civil, comercial, trabalhista e administrativa

### Referências legais
- Art. 216-H
- Art. 216-K
- Art. 216-L
- Art. 216-I
- Art. 216-M
- Art. 960, § 2º

### Dicas de prova
- Entenda a importância da apresentação da defesa e do Ministério Público no processo de homologação de sentença estrangeira.
- Conheça as hipóteses em que cabem decisões monocráticas do relator.
- Agravo Regimental e Recurso Extraordinário: entenda a diferença entre esses dois recursos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.398", "page_number": 398, "discipline": "Direitos Internacional", "legal_refs": ["Art. 216-H", "Art. 216-K", "Art. 216-L", "Art. 216-I", "Art. 216-M", "Art. 960, § 2º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:42:09.215373+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=398", "doc_key": "d1eb688e417dca3f39799283e3f16547"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '492c4cff9fa23e92aa544aefe8f25cd51c1d3a1da24de25316e23578f848e829'),
  ('cpiuris2025::9231c2adf00021ec7ae352c9e5212b3c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica Internacional e Reconhecimento de Sentenças Estrangeiras', '## Cooperação Jurídica Internacional e Reconhecimento de Sentenças Estrangeiras

A Corte Internacional de Justiça esclarece que não é cortes ou tribunais estrangeiros, cujos julgamentos não são decisões judiciais ou sentenças estrangeiras que requeiram exequator ou homologação. A empresa Gespart Comércio Participações Ltda. não tem legítimo direito a solicitar tal homologação.

### Conceitos
- **Autoridade Central**: Órgão de comunicação estatal que gerencia o trâmite dos pleitos cooperacionais
- **Legislação de Regência**: Lei que regula a cooperação jurídica internacional
- **Reconhecimento e Execução de Sentenças Estrangeiras**: Procedimento pelo qual um Estado reconhece e executa uma sentença estrangeira

### Referências legais
- Art. 36 da Convenção de Beja, de 5 de Junho de 1993

### Jurisprudência
- SEC 2.707/NL
- RE 123456

### Dicas de prova
- Entenda a diferença entre autoridade central e soberania nacional
- Conheça as regras para o reconhecimento e execução de sentenças estrangeiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.399 (2)", "page_number": 399, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 da Convenção de Beja, de 5 de Junho de 1993"], "jurisprudence": ["SEC 2.707/NL", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T14:43:13.714652+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=399", "doc_key": "9231c2adf00021ec7ae352c9e5212b3c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '32af5544b4c2427ad545b2ad0ec49f3d2c49c32bb8ac009dfdadaa8470bf10f1'),
  ('cpiuris2025::0d29305aa034ce255b8a7eddc1a8dbaa', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica Internacional', '## Cooperação Jurídica Internacional

A cooperação jurídica internacional envolve a colaboração entre os países para resolver disputas legais. O pedido passivo de cooperação jurídica internacional é realizado por órgão estrangeiro, e a cooperação segue parâmetros legais definidos em lei ordinária nacional.

### Conceitos
- **Cooperação Jurídica Internacional**: Colaboração entre os países para resolver disputas legais
- **Pedido Passivo de Cooperação Jurídica Internacional**: Realizado por órgão estrangeiro
- **Fontes do Direito Internacional Privado**: Lei que nele vigorar, quanto ao ônus e aos fatos

### Referências legais
- Art. 90 da Lei nº 9.472/1997
- Súmula 373 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Cooperação Jurídica Internacional

### Dicas de prova
- Entenda a definição de cooperação jurídica internacional e o pedido passivo
- Conheça as fontes do direito internacional privado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.400 (1)", "page_number": 400, "discipline": "Direitos Internacional", "legal_refs": ["Art. 90 da Lei nº 9.472/1997", "Súmula 373 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cooperação Jurídica Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T14:43:45.113576+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=400", "doc_key": "0d29305aa034ce255b8a7eddc1a8dbaa"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bc7c587d305267ac1a86367e91a393720389afb6fdce999c8cd8c4726b4c90f8'),
  ('cpiuris2025::5700479909e98d43c1c20df6118d804b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes e Regras do Direito Internacional Privado', '## Fontes e Regras do Direito Internacional Privado

As fontes do direito internacional privado incluem convenções internacionais, costume internacional e princípios gerais do direito. As partes têm liberdade para escolher a lei de regência em contratos internacionais, mas as decisões judiciais e doutrina dos juristas somente são obrigatórias para as partes litigantes.

### Conceitos
- **Autonomia da Vontade**: A liberdade das partes de escolher a lei de regência em contratos internacionais
- **Fontes do Direito Internacional Privado**: Convenções internacionais, costume internacional e princípios gerais do direito
- **Decisões Judiciais**: Somente obrigatórias para as partes litigantes e a respeito dos casos em questão
- **Doutrina dos Juristas**: Somente obrigatória para as partes litigantes e a respeito dos casos em questão

### Referências legais
- Art. 102 da Lei nº 9.868/1998
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a autonomia da vontade e as fontes do direito internacional privado
- Diferencie entre decisões judiciais e doutrina dos juristas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.400 (2)", "page_number": 400, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 da Lei nº 9.868/1998", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:44:31.890341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=400", "doc_key": "5700479909e98d43c1c20df6118d804b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c77e8cc595658dcca029d0c929336929c9e96ea8583a428248d47314c2c9a7f0'),
  ('cpiuris2025::8c81d745e5f1cc9872b5c240e538866b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Homologação de sentenças estrangeiras e litispendência internacional', '## Homologação de sentenças estrangeiras e litispendência internacional

Requer homologação do STJ para sentenças penal estrangeiras que reconheçam imóveis como produtos de crime de lavagem de dinheiro. A litispendência internacional pode ser conhecida de ofício e impede a ação no Brasil se já submetida a juiz estrangeiro.

### Conceitos
- **Homologação**: Requerimento ao STJ para sentenças penal estrangeiras
- **Litispendência internacional**: Impede a ação no Brasil se já submetida a juiz estrangeiro

### Referências legais
- Art. 95, § 3º da LEXN
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunta sobre homologação de sentenças estrangeiras
- Distinção entre litispendência internacional e ação duplicada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.401 (2)", "page_number": 401, "discipline": "Direitos Internacional", "legal_refs": ["Art. 95, § 3º da LEXN", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:45:29.444600+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=401", "doc_key": "8c81d745e5f1cc9872b5c240e538866b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1a97bbe9c6f80a2194bb9e70d7248d13209f39a7809510d8ece6c07183ba8b1e'),
  ('cpiuris2025::e715a365f749e30a49c432779e6bd94f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Auxílio Direto e Homologação de Sentenças Estrangeiras', '## Auxílio Direto e Homologação de Sentenças Estrangeiras

O auxílio direto é um procedimento que permite ao Estado brasileiro obter informações sobre o ordenamento jurídico e processos administrativos estrangeiros. A homologação de sentenças estrangeiras é um processo que visa reconhecer a eficácia de decisões estrangeiras no Brasil.

### Conceitos
- **Auxílio Direto**: Procedimento pelo qual o Estado brasileiro obteve informações sobre o ordenamento jurídico e processos administrativos estrangeiros
- **Homologação de Sentenças Estrangeiras**: Processo que visa reconhecer a eficácia de decisões estrangeiras no Brasil

### Referências legais
- Art. 336 do Código de Processo Civil
- Súmula 346/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Auxílio Direto e Homologação de Sentenças Estrangeiras

### Dicas de prova
- Entenda a diferença entre auxílio direto e homologação de sentenças estrangeiras
- Conheça as regras para a solicitação e homologação de sentenças estrangeiras no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.401 (1)", "page_number": 401, "discipline": "Direitos Internacional", "legal_refs": ["Art. 336 do Código de Processo Civil", "Súmula 346/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Auxílio Direto e Homologação de Sentenças Estrangeiras"], "confidence": 0.8, "extracted_at": "2026-05-31T14:45:38.232137+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=401", "doc_key": "e715a365f749e30a49c432779e6bd94f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a006ed7c7caa27a5f1ca75f693bed11ff6b39bfa64ccb1cae28f904438840b27'),
  ('cpiuris2025::f3c7e5cac190be63d8142f4b304c9b2d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Autenticação de documentos internacionais', '## Autenticação de documentos internacionais

Para ser autenticada, um documento internacional deve estar acompanhado de tradução e ter sido proferida uma decisão por órgão colegiado ou tribunal. As partes envolvidas devem ser citadas adequadamente.

### Conceitos
- **Autenticação**: Processo pelo qual um documento internacional é verificado como autêntico
- **Tradução juramentada**: Tradução de um documento internacional que pode ser juramentada para comprovar sua autenticidade
- **Revelia**: Situação em que uma parte não comparece a um processo ou procedimento

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Perguntas sobre autenticação e tradução podem ser complexas, então é importante entender as regras de autenticidade.
- A revelia não é aceita em procedimentos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.402 (2)", "page_number": 402, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T14:47:14.666553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=402", "doc_key": "f3c7e5cac190be63d8142f4b304c9b2d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '408d2e6376985d36f0de3726f2fa5d81abd0196c63b369b44325a94815709f35'),
  ('cpiuris2025::2350fc3582e4a81e58fa8e4572768092', 'doutrina', 'cp_iuris', 'Direitos Internacional — Cooperação Jurídica Internacional', '## Cooperação Jurídica Internacional

A cooperação jurídica internacional no Brasil é regida por tratados, observando-se a existência de autoridade central e garantindo igualdade de tratamento entre nacionais e estrangeiros.

### Conceitos
- **Autoridade Central**: Entidade responsável pela recepção e transmissão dos pedidos de cooperação.
- **Cooperação Jurídica Internacional**: Acordo entre países para compartilhar informações e assistência judiciária.
- **Competência Jurisdicional**: A competência da autoridade judiciária brasileira em casos relacionados a imóveis ou extradição.
- **Extradição**: Remessa de uma pessoa estrangeira para cumprir pena ou responder por crime.
- **Homologação de Sentença Estrangeira**: Reconhecimento da sentença estrangeira no Brasil.
- **Publicidade Processual**: O direito do público a conhecer os procedimentos judiciais.

### Referências legais
- Art. 90, § 4º, da Lei nº 9.472/1997
- Súmula 287/STJ

### Jurisprudência
- RE 123456
- Cooperação Jurídica Internacional - Tema Repetitivo ...

### Dicas de prova
- Entenda a noção de Autoridade Central e sua importância na cooperação jurídica internacional.
- Conheça as regras para a homologação de sentença estrangeira no Brasil.
- Avalie a competência jurisdicional brasileira em casos relacionados a imóveis ou extradição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.402 (1)", "page_number": 402, "discipline": "Direitos Internacional", "legal_refs": ["Art. 90, § 4º, da Lei nº 9.472/1997", "Súmula 287/STJ"], "jurisprudence": ["RE 123456", "Cooperação Jurídica Internacional - Tema Repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:47:26.764735+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=402", "doc_key": "2350fc3582e4a81e58fa8e4572768092"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '76c2efe4b23ad1d3e5b62650c7728f539be91ead866a73509966d55191b116df'),
  ('cpiuris2025::3d476e4e560a1b58ad3b0f508c64f79a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Homologação de sentença estrangeira', '## Homologação de sentença estrangeira

A homologação de sentença estrangeira é regulamentada pelo direito internacional e tem regras específicas, como a necessidade de autenticação pela autoridade consular brasileira.

### Conceitos
- **Autenticação**: Procedimento para verificar a autenticidade de documentos estrangeiros
- **Homologação**: Ato pelo qual o Estado brasileiro reconhece a validade de uma sentença estrangeira
- **Autoridade Consular**: Entidade responsável pela autenticação de documentos diplomáticos

### Referências legais
- Art. 90 da Convenção de Viena sobre Relações Civis entre Estados
- Súmula 346 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Homologação de sentença estrangeira

### Dicas de prova
- Diferenciar entre autenticação e homologação
- Conhecer a autoridade responsável pela autenticação de documentos diplomáticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.403 (2)", "page_number": 403, "discipline": "Direitos Internacional", "legal_refs": ["Art. 90 da Convenção de Viena sobre Relações Civis entre Estados", "Súmula 346 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Homologação de sentença estrangeira"], "confidence": 0.8, "extracted_at": "2026-05-31T14:49:00.936209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=403", "doc_key": "3d476e4e560a1b58ad3b0f508c64f79a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6765a5f75d61a9332eb9062ca84151f46d32d0cee7c8db948388e1f78c8556e1'),
  ('cpiuris2025::b98f1b2c70f1f94faf28435d001b4dbf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Exercício da Jurisdição Extraterritorial e Homologação de Sentenças Estrangeiras', '## Exercício da Jurisdição Extraterritorial e Homologação de Sentenças Estrangeiras

A primazia do exercício da jurisdição extraterritorial só é admitida em casos excepcionais, sob pena de ingerência ilícita nos assuntos de exclusiva competência doméstica do Estado territorial. A homologação de sentenças estrangeiras é regulada por regras específicas, incluindo a necessidade de que a sentença não ofenda a soberania nacional, a ordem pública e os bons costumes.

### Conceitos
- **Jurisdição Extraterritorial**: Exercício da jurisdição por um Estado em relação a uma pessoa ou coisa jurídica fora do seu território
- **Homologação de Sentenças Estrangeiras**: Procedimento pelo qual uma sentença estrangeira é reconhecida e executada no país que a proferiu
- **Soberania Nacional**: Direito do Estado de controlar seus assuntos internos e externos
- **Ordem Pública**: Conceito jurídico que se refere à ordem social e política estabelecida por um Estado
- **Bons Costumes**: Normas e valores culturais aceitos por uma sociedade como normas de conduta
- **Reconhecimento das Sentenças Brasileiras**: Procedimento pelo qual uma sentença brasileira é reconhecida e executada em outro país

### Referências legais
- Art. 87, § 2º, da Lei nº 9.472/1997 - Código de Processo Civil
- Súmula 269 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Súmula 269 do Supremo Tribunal Federal

### Dicas de prova
- Pergunte sobre a primazia do exercício da jurisdição extraterritorial e as regras de homologação de sentenças estrangeiras.
- Entenda o conceito de soberania nacional, ordem pública e bons costumes em relação à homologação de sentenças estrangeiras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.403 (1)", "page_number": 403, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87, § 2º, da Lei nº 9.472/1997 - Código de Processo Civil", "Súmula 269 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Súmula 269 do Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-31T14:49:01.634348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=403", "doc_key": "b98f1b2c70f1f94faf28435d001b4dbf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2bfd34916a544f2613b7f5ae811a3760c0a37871a5a450606f82adf63cba5fce'),
  ('cpiuris2025::a42d29592c5d55c7f435925e594b5cb0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teste de Direito Internacional Privado', '## Teste de Direito Internacional Privado

Exame de direito internacional privado com questões de escolha múltipla.

### Conceitos
- **Direito Internacional Privado**: Ramo do direito que regula as relações entre estados e pessoas físicas ou jurídicas em diferentes países.
- **Escolha Múltipla**: Tipo de questão que permite ao candidato escolher mais de uma resposta correta.
- **Gabarito**: Resposta correta para cada questão.
- **Questões**: Perguntas apresentadas ao candidato para avaliação do seu conhecimento.

### Referências legais
- Art. 8 da Convenção de Viena sobre Direito do Comércio Internacional
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Ler atentamente o gabarito para entender a resposta correta.
- Escolher as opções que melhor se adequam ao direito internacional privado.
- Não se esquecer de ler as questões antes de escolher uma resposta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.404", "page_number": 404, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8 da Convenção de Viena sobre Direito do Comércio Internacional", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:49:22.684869+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=404", "doc_key": "a42d29592c5d55c7f435925e594b5cb0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8cbfa9cf2b1f576e5e982e384b24865b05eab87a975b0070532e50f35b6cea64'),
  ('cpiuris2025::eaa1052b9f33318b2eac37effa166a74', 'doutrina', 'cp_iuris', 'Direitos Internacional — Referências Bibliográficas', '## Referências Bibliográficas

Lista de obras bibliográficas relacionadas ao direito internacional, incluindo autores e ediciones.

### Conceitos
- **Manual de Direito Internacional Público**: Obra-prima em direito internacional público
- **Declaração Universal dos Direitos Humanos**: Declaração vinculante de direito internacional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Reconheça as obras mais relevantes na área do direito internacional público
- Entenda a importância da Declaração Universal dos Direitos Humanos no contexto do direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.408 (1)", "page_number": 408, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:50:40.874381+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=408", "doc_key": "eaa1052b9f33318b2eac37effa166a74"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cdca80225e5dad8fbb19b4582ddf316c45ade6c7ef7b1e7b23509d806d594337'),
  ('cpiuris2025::5d83d1ea1fdad6de9386a5b40a68cb60', 'doutrina', 'cp_iuris', 'Direitos Internacional — Resolução do Conselho de Segurança', '## Resolução do Conselho de Segurança

Textos de resoluções do Conselho de Segurança, indicando temas e casos específicos.

### Conceitos
- **Resolução do Conselho de Segurança**: Decisão do órgão internacional
- **Tema**: Assunto abordado na resolução
- **HC**: Habeas Corpus, petição para a liberdade de alguém preso
- **CPF**: Cadastro Pessoal Federal, documento de identidade

### Referências legais
- Art. 22 da Carta das Nações Unidas

### Dicas de prova
- Identificar o órgão internacional e a decisão específica
- Diferenciar entre temas e casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.407", "page_number": 407, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:50:41.996951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=407", "doc_key": "5d83d1ea1fdad6de9386a5b40a68cb60"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5522bf2db238f528ad928cb1edf6599345b967a0de0085ca80b04b7a05fadec4'),
  ('cpiuris2025::f68eeec2265c9002a7cb43d3e5be2c65', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ações Cíveis Originárias e Rescisórias', '## Ações Cíveis Originárias e Rescisórias

Resumo de ações cíveis originárias e rescisórias, incluindo acordos de extradição e ações diretas de inconstitucionalidade.

### Conceitos
- **Ação Cível Originária**: Processo civil que busca resolver um litígio entre duas ou mais partes.
- **Ação Rescisória**: Processo que visa rescindir um acordo ou contrato anteriormente celebrado.
- **Acordo de Extradição**: Acordo internacional que permite a extradição de uma pessoa física ou jurídica de um país para outro.

### Referências legais
- Art. 9.705, Código de Processo Civil
- ACO 522-AgR/SP

### Dicas de prova
- Entenda a diferença entre ação cível originária e rescisória.
- Conheça os acordos de extradição e sua importância nos processos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.406", "page_number": 406, "discipline": "Direitos Internacional", "legal_refs": ["Art. 9.705, Código de Processo Civil", "ACO 522-AgR/SP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T14:50:49.547503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=406", "doc_key": "f68eeec2265c9002a7cb43d3e5be2c65"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3aa11623257f4287504a7cc78b1426f345bef17a914cbbbd56ba6616149b2f4c'),
  ('cpiuris2025::ed127a7a096e0bce4e653b800a6f4fc9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigação de Processar ou Extraditar', '## Obrigação de Processar ou Extraditar

A Corte Internacional de Justiça julgou casos sobre a obrigação de processar ou extraditar países estrangeiros para responder a crimes cometidos dentro do seu território.

### Conceitos
- **Obrigação de Processar**: a obrigação de um país de processar um criminoso estrangeiro que cometeu um crime dentro do seu território
- **Extradição**: a transferência de um criminoso estrangeiro para o país onde o crime foi cometido, para responder ao processo

### Referências legais
- Art. 87 da Convenção de Viena sobre Relações Diplomáticas

### Jurisprudência
- Caso Questões relativas à obrigação de processar ou extraditar (Bélgica v. Senegal)
- Súmula 342 da Corte Internacional de Justiça

### Dicas de prova
- Entenda a distinção entre processamento e extradição
- Conheça as regras da Convenção de Viena sobre Relações Diplomáticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.409 (2)", "page_number": 409, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87 da Convenção de Viena sobre Relações Diplomáticas"], "jurisprudence": ["Caso Questões relativas à obrigação de processar ou extraditar (Bélgica v. Senegal)", "Súmula 342 da Corte Internacional de Justiça"], "confidence": 0.8, "extracted_at": "2026-05-31T14:52:49.517746+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=409", "doc_key": "ed127a7a096e0bce4e653b800a6f4fc9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b43191db19237986679982d0911dd215035e058a9a5e5babfa5d7f995432fb00'),
  ('cpiuris2025::91dc288cd4c622e69b6060f44e47a0e1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados e Publicações de Autores Renomados no Direito Internacional', '## Tratados e Publicações de Autores Renomados no Direito Internacional

Resumo objetivo sobre a publicação de autores renomados no direito internacional, destacando trabalhos como o Tratado de Direito Internacional dos Direitos Humanos de Antônio Augusto Cançado Trindade.

### Conceitos
- **Tratado**: Acordo internacional que estabelece regras e normas para a relação entre os Estados
- **Publicação acadêmica**: Obra escrita por um autor sobre um tema específico, como o direito internacional
- **Autores renomados**: Pessoas que são conhecidas e respeitadas por sua expertise em uma área específica, como o direito internacional
- **Direitos Humanos**: Direitos fundamentais das pessoas humanas, protegidos pela lei internacional
- **Corte Internacional de Direitos Humanos**: Entidade que procura garantir e proteger os direitos humanos em todo o mundo
- **Edição**: Versão revisada e corrigida de uma obra original
- **Editora**: Pessoa ou empresa responsável pela publicação de uma obra

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância dos tratados e publicações acadêmicas no direito internacional.
- Conheça os autores renomados que contribuem para o desenvolvimento do direito internacional.
- Destaque a relevância dos direitos humanos na área do direito internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.408 (2)", "page_number": 408, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T14:53:47.832581+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=408", "doc_key": "91dc288cd4c622e69b6060f44e47a0e1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3980663445b8d5ea10f29de719ff9ec5d520ba4bd39186ddecb705e347e8cf7b'),
  ('cpiuris2025::b1f3ccbb109f4639a3def60aa6085b82', 'doutrina', 'cp_iuris', 'Direitos Internacional — Referências bibliográficas em Direito Internacional', '## Referências bibliográficas em Direito Internacional

Lista de obras e casos jurídicos citados como referências bibliográficas no texto.

### Conceitos
- **Corte Internacional de Justiça**: Entidade responsável por julgar disputas entre Estados
- **Caso Al-Adsani vs. Reino Unido**: Julgamento da Corte Europeia dos Direitos Humanos sobre um caso de direitos humanos
- **Caso Aloeboetoe e outros Vs. Surinam**: Julgamento da Corte Interamericana de Direitos Humanos sobre um caso de direitos humanos
- **Caso Blake Vs. Guatemala**: Julgamento da Corte Interamericana de Direitos Humanos sobre um caso de direitos humanos
- **Caso da Companhia Barcelona Traction Light and Power Ltda. (Bélgica Vs. Espanha)**: Julgamento da Corte Internacional de Justiça sobre uma disputa entre dois Estados
- **Caso da Pesca**: Julgamento da Corte Internacional de Justiça sobre um caso de pesca internacional

### Referências legais
- Art. 36 do Estatuto do Tribunal Penal Internacional

### Jurisprudência
- Súmula 292 do STF
- Caso Al-Adsani vs. Reino Unido (Corte Europeia dos Direitos Humanos)

### Dicas de prova
- Entenda a importância das referências bibliográficas em Direito Internacional.
- Conheça os casos e obras citadas como referências para aplicar o conhecimento em provas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.409 (1)", "page_number": 409, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 do Estatuto do Tribunal Penal Internacional"], "jurisprudence": ["Súmula 292 do STF", "Caso Al-Adsani vs. Reino Unido (Corte Europeia dos Direitos Humanos)"], "confidence": 0.8, "extracted_at": "2026-05-31T14:54:03.297793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=409", "doc_key": "b1f3ccbb109f4639a3def60aa6085b82"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2ebff365595544bc738ed3dd2d00a021b76e2d897b2265b320c02526f1b389f7'),
  ('cpiuris2025::ea4184ee8772edb90a79b9144a83ac97', 'doutrina', 'cp_iuris', 'Direitos Internacional — Referências bibliográficas', '## Referências bibliográficas

Lista de fontes utilizadas como referência para o estudo do Direito Internacional.

### Conceitos
- **Corte Permanente de Justiça Internacional**: Entidade responsável por julgar disputas internacionais.
