  ('cpiuris2025::30fc8f0fdfe03f45b9a59d98b0944850', 'doutrina', 'cp_iuris', 'Execução Penal — Terceirização de atividades em estabelecimentos penais', '## Terceirização de atividades em estabelecimentos penais

Discute a possibilidade de terceirização de atividades desenvolvidas nos estabelecimentos penais, destacando a necessidade de autorização prévia do juiz competente.

### Conceitos
- **Terceirização**: A transferência de atividades penitenciárias para terceiros, com ou sem autorização prévia do juiz competente.
- **Autorização prévia**: O requisito legal que exige a aprovação do juiz competente antes da realização de atividade penal.
- **Estabelecimento penal**: Instituição prisional onde são mantidos os presos.
- **Atividades penitenciárias**: Todas as ações desenvolvidas dentro de um estabelecimento penal, como educação, saúde e trabalho.

### Referências legais
- Art. 32 da Lei nº 7.210/82

