  ('cpiuris2025::03e256a82cb497e660e09ccce8a020d7', 'doutrina', 'cp_iuris', 'Execução Penal — Órgãos da Execução Penal', '## Órgãos da Execução Penal

Descreve os órgãos que compõem a execução penal, incluindo o CNPCP, Juízo de Execução, Ministério Público e outros.

### Conceitos
- **Órgão da Execução Penal**: Entidade responsável pela aplicação das penas
- **CNPB**: Conselho Nacional de Política Criminal e Penitenciária
- **Juízo de Execução**: Unidade judiciária responsável pela aplicação das penas
- **Ministério Público**: Órgão responsável por investigar e prosseguir os crimes
- **COPEN**: Conselho Penitenciário
- **Departamentos Penitenciários**: Unidades responsáveis pela gestão das prisões
- **Patronato**: Entidade responsável pela gestão de recursos e bens da execução penal
- **Counil da Comunidade**: Órgão responsável por promover a reintegração social dos presos

### Referências legais
- Art. 26 da LEP
- Art. 73 a 77 da LEP

