  ('cpiuris2025::7ad3cbc4a6e01ca7a8cee91778cb6c92', 'doutrina', 'cp_iuris', 'Execução Penal — Progressão para regimes mais favoráveis', '## Progressão para regimes mais favoráveis

Condenado pode progredir do regime fechado para semiaberto e depois aberto, após cumprimento de pena e bom comportamento carcerário.

### Conceitos
- **Regime Fechado**: Regra mais restritiva
- **Progressão**: Mudança para regime mais favorável
- **Bom Comportamento Carcerário**: Cumprimento de requisitos subjetivos
- **Semiaberto**: Regime com restrições, mas mais flexível do que fechado
- **Aberto**: Regime mais flexível e menos restringido

### Referências legais
- Art. 42 da Lei nº 7.210/82

### Dicas de prova
- Distinção entre regimes
- Requisitos para progressão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Execução Penal", "legal_refs": ["Art. 42 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:04:25.309074+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=6", "doc_key": "7ad3cbc4a6e01ca7a8cee91778cb6c92"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '5915b53ce08281c0964bc8516c6f201a8be5c0f4805d4532dabafa4429c23d6d'),
  ('cpiuris2025::893c5684f47d01c952af27a82b4278e2', 'doutrina', 'cp_iuris', 'Execução Penal — Incidentes da Execução Penal', '## Incidentes da Execução Penal

Capítulo que aborda incidentes que podem ocorrer durante a execução penal, como anomalias psíquicas, autorização de saída e agravo em execução.

### Conceitos
- **Anomalia Psíquica**: Condição que afeta a capacidade do réu para compreender a gravidade das suas ações
- **Livramento Condicional**: Decisão do juiz que permite ao réu sair da prisão condicionalmente, sob certas condições
- **Saída Temporária**: Permissão temporária de saída da prisão para realizar uma atividade específica

### Referências legais
- Art. 77, § 3º, do Código de Processo Penal

### Dicas de prova
- Entenda a diferença entre anomalia psíquica e livramento condicional
- Conheça as condições para autorização de saída temporária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Execução Penal", "legal_refs": ["Art. 77, § 3º, do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:04:39.702577+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=5", "doc_key": "893c5684f47d01c952af27a82b4278e2"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '3b8fcea203ad21515f6fb48f86b945ef8b785ef817a7fd95e32740cf10449977'),
  ('cpiuris2025::65a127f84b9647922caa9d99191eea6d', 'doutrina', 'cp_iuris', 'Execução Penal — Noções introdutórias sobre a Lei 7.210/84', '## Noções introdutórias sobre a Lei 7.210/84

A execução penal tem como objetivo efetivar as disposições da sentença criminal e proporcionar condições para a reintegração social do condenado ou internado.

### Conceitos
- **Execução Penal**: conjunto de normas e princípios que têm por objetivo tornar efetivo o comando judicial determinado na sentença
- **Medida de Segurança**: aplicável aos inimputáveis ou semi-imputáveis com periculosidade, com objetivo de oferecer tratamento à pessoa com alguma desordem psíquica
- **Reintegração Social**: harmônica integração do condenado ou internado na sociedade
- **Sistema Progressivo**: o indivíduo não cumprirá a pena integralmente enclausurado, sem qualquer contato com o mundo exterior

### Referências legais
- Art. 1º da Lei n.º 7.210/84

### Dicas de prova
- Entenda a distinção entre penas e medidas de segurança
- Conheça o conceito de reintegração social
- Aprenda com o sistema progressivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Execução Penal", "legal_refs": ["Art. 1º da Lei n.º 7.210/84"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:05:11.815948+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=6", "doc_key": "65a127f84b9647922caa9d99191eea6d"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '2bf3a25a1738bcf310d98617b18577f138e9624de5fc66fc4e801ed5d169c456'),
  ('cpiuris2025::6b6251499e5626bdd6ff3232080906b4', 'doutrina', 'cp_iuris', 'Execução Penal — Natureza jurídica da execução penal', '## Natureza jurídica da execução penal

A natureza jurídica da execução penal é objeto de debate na doutrina. A Lei Especial de Execução Penal (LEP) regula o processo, mas não define a natureza jurídica.

### Conceitos
- **Natureza jurídica**: Característica ou essência da execução penal
- **Doutrina**: Científico estudo das leis e costumes
- **Lei Especial de Execução Penal (LEP)**: Regulamenta o processo de execução penal

### Referências legais
- Art. 2º da LEP
- Súmula 439/STF

### Dicas de prova
- Entenda a diferença entre a natureza jurídica e a regulamentação da execução penal.
- Conheça a Lei Especial de Execução Penal (LEP) e sua aplicabilidade aos presos provisórios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Execução Penal", "legal_refs": ["Art. 2º da LEP", "Súmula 439/STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:06:27.962516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=7", "doc_key": "6b6251499e5626bdd6ff3232080906b4"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '2e77c0401c744e29b8b870e7e5b0a14a1cb404b618e805bff8b7b7bec38b4377'),
  ('cpiuris2025::49d458fa8e233a4b692b3775ca778d8b', 'doutrina', 'cp_iuris', 'Execução Penal — Natureza da Execução Penal', '## Natureza da Execução Penal

A execução penal possui natureza mista e complexa, com presença de viés administrativo e jurisdicional.

### Conceitos
- **Viés Administrativo**: Atividade de proferir decisões de caráter jurisdicional
- **Viés Jurisdicional**: Atividade de proferir decisões de caráter jurisdicional
- **Natureza Mista**: Execução penal possui elementos tanto administrativos quanto jurisdicionais
- **Complexidade**: Característica da execução penal devido à presença de vieses administrativo e jurisdicional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre viés administrativo e jurisdicional
- Entender a natureza mista e complexa da execução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Execução Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T15:06:34.595836+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=7", "doc_key": "49d458fa8e233a4b692b3775ca778d8b"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '04c5b6f9368fc3860a2880c31fa7099fef0f04381d9bbd7e811c50599afa33a4'),
  ('cpiuris2025::d4257f26e3e949f8fe123dd31ff61b32', 'doutrina', 'cp_iuris', 'Execução Penal — Unificação de Penas e Limites de Execução', '## Unificação de Penas e Limites de Execução

O juiz da execução deve unificar penas superiores a 40 anos, considerando crime continuado e progressão de regime. A natureza jurisdicional prevalece sobre a administrativa.

### Conceitos
- **Unificação de Penas**: Soma ou uniificação de penas privativas de liberdade
- **Limites de Execução**: Máximo de 40 anos para tempo de cumprimento de pena
- **Crime Continuado**: Fato que se desenvolve ao longo do tempo
- **Progressão de Regime**: Aumento da liberdade do preso com o tempo
- **Natureza Jurisdicional**: Característica da execução penal como atividade jurisdicional
- **Natureza Administrativa**: Característica da execução penal como atividade administrativa
- **Novatio Legis In Mellius**: Retroatividade benéfica de novas leis favoráveis aos acusados
- **Abolitio Criminis**: Abolição do crime do ordenamento jurídico

### Referências legais
- Art. 75 do Código Penal
- Lei n.º 13.964 de 2019
- Lei n.º 7.209 de 1984

### Jurisprudência
- Súmula 611/STF

### Dicas de prova
- Entenda a unificação de penas e limites de execução
- Discorra sobre natureza jurisdicional e administrativa da execução penal
- Conheça o princípio da novatio legis in mellius e abolitio criminis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Execução Penal", "legal_refs": ["Art. 75 do Código Penal", "Lei n.º 13.964 de 2019", "Lei n.º 7.209 de 1984"], "jurisprudence": ["Súmula 611/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T15:08:13.828257+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=8", "doc_key": "d4257f26e3e949f8fe123dd31ff61b32"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '80b6e519470a21f9d9ae3c74e7af2be34ffed2ef26fea7b9a8225e9cc88f6a46'),
  ('cpiuris2025::c3fd364697d844c9ffd177fb261d74ed', 'doutrina', 'cp_iuris', 'Execução Penal — Revisão da Lei sobre emprego de arma em sentença', '## Revisão da Lei sobre emprego de arma em sentença

A lei foi revogada e substituída por uma nova, que estabelece um patamar fixo de aumento da pena de roubo quando cometido com emprego de arma de fogo. A pessoa que praticou roubo com arma branca antes de 2018 será beneficiada pela novatio legis in mellius.

### Conceitos
- **Novatio legis in mellius**: Benefício concedido à pessoa que praticou crime antes da entrada em vigor da nova lei
- **Retroatividade**: A aplicação de uma lei antiga a um caso posterior
- **Iretroatividade**: A não aplicação de uma lei antiga a um caso posterior

### Referências legais
- Art. 157 do CP
- Lei n.º 13.964/2019

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Verificar a data de vigência da lei e se é hipótese de retroatividade benéfica ou de irretroatividade
- Entender a diferença entre novatio legis in mellius e retroatividade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Execução Penal", "legal_refs": ["Art. 157 do CP", "Lei n.º 13.964/2019"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T15:08:38.012517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=9", "doc_key": "c3fd364697d844c9ffd177fb261d74ed"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '3495ff815a4af047a6abab8d52fd7c7220aa4deae403a2dfb4dbc78d8374c8dd'),
  ('cpiuris2025::cb32d0745ea9b58845638db47ecf6fa0', 'doutrina', 'cp_iuris', 'Execução Penal — Abolitio Criminis e Cessação da Punibilidade', '## Abolitio Criminis e Cessação da Punibilidade

A abolitio criminis permite a cessação da punibilidade do indivíduo que estava cumprindo pena por crime abolido, com aplicação da lei mais benéfica. O apenado pode ter a dosimetria revista se uma nova lei o favorecer.

### Conceitos
- **Abolitio Criminis**: Princípio que permite a cessação da punibilidade do indivíduo que estava cumprindo pena por crime abolido
- **Cessação da Punibilidade**: Fim da punibilidade do indivíduo que estava cumprindo pena por crime abolido
- **Lei mais Benéfica**: A lei aplicada ao caso, considerando a evolução da sociedade e a mudança das leis
- **Novatio Legis in Mellius**: Mudança da lei para torná-la mais favorável ao réu

### Referências legais
- Art. 2º do Código Penal
- Súmula 611 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a Abolitio Criminis e sua aplicação na Execução Penal
- Conheça as exceções para a revisão da dosimetria, como a Lei n.º 13.654/2018', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Execução Penal", "legal_refs": ["Art. 2º do Código Penal", "Súmula 611 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.9, "extracted_at": "2026-05-31T15:09:02.985728+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=8", "doc_key": "cb32d0745ea9b58845638db47ecf6fa0"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '100b062849ca97e7e42b7f64baa320a8a6accb54f516d6ec603dbff3ce4abcb2'),
  ('cpiuris2025::65df737d313a4925e860ce635d38980e', 'doutrina', 'cp_iuris', 'Execução Penal — Execução Provisória', '## Execução Provisória

O preso cautelar tem direito aos benefícios da execução penal, incluindo a progressão de regime, desde que cumpra tempo suficiente. A execução provisória é pautada em título executivo ainda não transitado em julgado e busca garantir os benefícios da LEP.

### Conceitos
- **Execução Provisória**: execução penal que ocorre antes de sentença final
- **Título Executivo**: instrumento processual que pauta a execução provisória
- **Benefícios da LEP**: progressão de regime, liberdade condicional, etc.

### Referências legais
- Art. 515 do Código de Processo Civil
- Súmula 646/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da execução provisória

### Dicas de prova
- Diferenciar a execução provisória da execução antecipada
- Entender o papel do título executivo na execução provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Execução Penal", "legal_refs": ["Art. 515 do Código de Processo Civil", "Súmula 646/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da execução provisória"], "confidence": 0.8, "extracted_at": "2026-05-31T15:10:18.907373+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=9", "doc_key": "65df737d313a4925e860ce635d38980e"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '4b03a028da12b8ea9373dd70e60a972f815f18fcaadf545a4a21a90a83e14979'),
  ('cpiuris2025::dbb813bba25a8b9f5530075028c71b27', 'doutrina', 'cp_iuris', 'Execução Penal — Trânsito em julgado para execução de penas restritivas de direito', '## Trânsito em julgado para execução de penas restritivas de direito

É necessário o trânsito em julgado da sentença para executar penas restritivas de direito, conforme art. 147 da LEP e Súmula 643 do STJ.

### Conceitos
- **Trânsito em julgado**: Condição necessária para a execução de penas restritivas de direito
- **Penas restritivas de direitos**: Penas autônomas que substituem as privativas de liberdade
- **Execução provisória**: Não é permitida, necessitando-se do trânsito em julgado da sentença

### Referências legais
- Art. 147 da LEP
- Súmula 643 do STJ

### Jurisprudência
- ADCs 43 e 44

### Dicas de prova
- Distinção entre execução provisória e trânsito em julgado
- Importância da Súmula 643 do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Execução Penal", "legal_refs": ["Art. 147 da LEP", "Súmula 643 do STJ"], "jurisprudence": ["ADCs 43 e 44"], "confidence": 0.8, "extracted_at": "2026-05-31T15:11:05.369224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=10", "doc_key": "dbb813bba25a8b9f5530075028c71b27"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '4997e225d3860afd877f73104b6e2cb160795e692e614f4a10bd230b2c8c3401'),
  ('cpiuris2025::b5a2fa40902781cb33562b13e515f753', 'doutrina', 'cp_iuris', 'Execução Penal — Possibilidade de execução provisória da condenação', '## Possibilidade de execução provisória da condenação

O STF decidiu que não é necessário o recolhimento após a condenação em segunda instância para iniciar o cumprimento da pena, permitindo que o réu aguarde o trânsito em julgado definitivo em liberdade.

### Conceitos
- **Princípio da não culpabilidade**: Garantia constitucional que proíbe a prisão de alguém sem prova concreta de sua culpa.
- **Trânsito em julgado**: O momento em que a sentença condenatória se torna definitiva e imutável, após o qual não há mais recurso possível.
- **Reclusão provisória**: Execução da pena antes do trânsito em julgado da sentença condenatória.

### Referências legais
- Art. 283 do Código de Processo Penal
- STF. ADC 43, Relator(a): MARCO AURÉLIO

### Jurisprudência
- Súmula 716/STF
- ADC 43,44 e 54

### Dicas de prova
- Entenda o princípio da não culpabilidade e sua relação com a execução provisória da condenação.
- Conheça a diferença entre trânsito em julgado e sentença condenatória definitiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Execução Penal", "legal_refs": ["Art. 283 do Código de Processo Penal", "STF. ADC 43, Relator(a): MARCO AURÉLIO"], "jurisprudence": ["Súmula 716/STF", "ADC 43,44 e 54"], "confidence": 0.8, "extracted_at": "2026-05-31T15:11:24.646008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=10", "doc_key": "b5a2fa40902781cb33562b13e515f753"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '1b151ac9af86de1a5031a96c3e537790c1a0575acfd6bcb63a1f56e739ea67f7'),
  ('cpiuris2025::f1be78de319d4021bbccab58caba74c2', 'doutrina', 'cp_iuris', 'Execução Penal — Execução Penal - Introdução', '## Execução Penal - Introdução

A execução penal se desenvolverá por impulso oficial, sem necessária nova intimação ao réu (I). O CPP pode ser aplicado subsidiariamente na execução penal (II). A teoria adotada na execução penal é a punição desalinhada da prevenção (III).

### Conceitos
- **Execução Penal**: processo que visa cumprir a pena imposta pela sentença
- **Impulso Oficial**: procedimento que não requer nova intimação ao réu
- **Teoria Adotada**: punição desalinhada da prevenção

### Referências legais
- Art. 1 do CPP
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a teoria adotada na execução penal e suas implicações.
- Conheça as diferenças entre impulso oficial e intimação ao réu.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.11", "page_number": 11, "discipline": "Execução Penal", "legal_refs": ["Art. 1 do CPP", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T15:12:16.098126+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=11", "doc_key": "f1be78de319d4021bbccab58caba74c2"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '6abea07f87e54a974ede4f76a2dbf67b592d2ceb1d59e9d89098054c19e50f98'),
  ('cpiuris2025::d502407ef6c4ec8aa00daf467c16c769', 'doutrina', 'cp_iuris', 'Execução Penal — Objetivo e Teoria da Execução Penal', '## Objetivo e Teoria da Execução Penal

A execução penal tem como objetivo efetivar as disposições de sentença ou decisão criminal, proporcionando condições para a harmônica integração social do condenado. A teoria eclética da pena é adotada, com a reintegração harmônica do condenado ao meio social.

### Conceitos
- **Teoria Eclética da Pena**: Reintegração harmônica do condenado ao meio social
- **Objetivos da Execução Penal**: Efetivar as disposições de sentença ou decisão criminal, proporcionar condições para a integração social

### Referências legais
- Art. 1º da Lei 7.210/84

### Dicas de prova
- Entenda a teoria eclética da pena e seus objetivos
- Conheça as duas espécies de execução: definitiva e provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Execução Penal", "legal_refs": ["Art. 1º da Lei 7.210/84"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:12:58.301093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=12", "doc_key": "d502407ef6c4ec8aa00daf467c16c769"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'ff77ff5860e787177af28877df5d1a32e955c401b07852d37d29f4f90fa63fd1'),
  ('cpiuris2025::3af925add1b2095ebabceb5ca194ad44', 'doutrina', 'cp_iuris', 'Execução Penal — Execução Provisória e Condenação em Segunda Instância', '## Execução Provisória e Condenação em Segunda Instância

A execução provisória não pode ser confundida com a execução após condenação em segunda instância. A condenação em segunda instância não autoriza a execução antecipada da pena, pois o condenado pode aguardar o trânsito em julgado para dar início à execução.

### Conceitos
- **Execução Provisória**: execução temporária da pena
- **Condenação em Segunda Instância**: condenação após recurso e confirmação da sentença pelo Tribunal
- **Trânsito em Julgado**: ocorrido após a conclusão do processo

### Referências legais
- Art. 512 do Código de Processo Penal
- ...

### Jurisprudência
- Súmula 444/STF

### Dicas de prova
- Diferenciar entre execução provisória e condenação em segunda instância
- Entender o conceito de trânsito em julgado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Execução Penal", "legal_refs": ["Art. 512 do Código de Processo Penal", "..."], "jurisprudence": ["Súmula 444/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T15:13:21.924848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=12", "doc_key": "3af925add1b2095ebabceb5ca194ad44"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'ccf6c685b21130847bf852110c4e153b7b8a0838dda3a7bbca14e18b0c824a37'),
  ('cpiuris2025::b90c81dd59bf6dfb85ce850a59ac455e', 'doutrina', 'cp_iuris', 'Execução Penal — Classificação de Condenados', '## Classificação de Condenados

A classificação dos condenados é feita com base em seus antecedentes e personalidade, visando orientar a individualização da execução penal.

### Conceitos
- **Individualização da Execução Penal**: Procedimento que visa adaptar a punição à personalidade do condenado
- **Antecedentes Criminais**: Histórico de infrações cometidas pelo condenado

### Referências legais
- Art. 5º da LEP

### Dicas de prova
- Entenda a importância da individualização da execução penal
- Conheça os critérios utilizados para classificar os condenados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.13", "page_number": 13, "discipline": "Execução Penal", "legal_refs": ["Art. 5º da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:13:32.025532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=13", "doc_key": "b90c81dd59bf6dfb85ce850a59ac455e"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '90c489ceb765a73747852c73b35239ecc10968c001680325db548e52dbd031bc'),
  ('cpiuris2025::dad85936274da9e25b8802c19049f320', 'doutrina', 'cp_iuris', 'Execução Penal — Classificação dos Presos e Individualização da Pena', '## Classificação dos Presos e Individualização da Pena

A classificação dos presos é fundamental para a individualização da execução penal, considerando antecedentes e personalidade do condenado. A pena não pode ser calculada apenas com base em critérios aritméticos, mas sim analisar todas as circunstâncias e peculiaridades do caso concreto.

### Conceitos
- **Individualização da Pena**: O processo de adaptar a pena às peculiaridades individuais do condenado
- **Âmbito Legislativo**: Penas estabelecidas em abstrato pelo Poder Legislativo
- **Âmbito Judicial**: Pena aplicada na sentença condenatória
- **Âmbito Executivo**: Pena adaptada às peculiaridades individuais, até mesmo para melhor se aferir o direito ou não do indivíduo aos benefícios da execução

### Referências legais
- Art. 5º da Lei de Execução Penal

### Dicas de prova
- Entenda a importância da individualização da pena e como ela é alcançada em diferentes âmbitos (legislativo, judicial e executivo).
- Análise as fases da individualização da pena e como elas se relacionam entre si.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Execução Penal", "legal_refs": ["Art. 5º da Lei de Execução Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:14:05.584180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=14", "doc_key": "dad85936274da9e25b8802c19049f320"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '4afd3a9851a73bac803f218dc15a9b71f2a35629dd40dedb98fcdabcea499a20'),
  ('cpiuris2025::eb76379631df7ccb811c19c70c38ac2c', 'doutrina', 'cp_iuris', 'Execução Penal — Classificação de Presos', '## Classificação de Presos

A classificação de presos é um direito do preso para diferenciá-lo e favorecer o seu processo de reinserção social. É realizada pela CTC e não confunde-se com o exame criminológico.

### Conceitos
- **Regra de Mandela**: Mínimas da Organização das Nações Unidas para o tratamento dos presos
- **Classificação de Presos**: Diferenciação do preso para favorecer a sua reinserção social
- **Exame Criminológico**: O exame criminológico é realizado para definir o cumprimento da pena em regime inicial fechado e pode ser utilizado na concessão de benefícios

### Referências legais
- Art. 8º da LEP
- Súmula 345/STF

### Jurisprudência
- RE 456.789

### Dicas de prova
- Entenda a importância da classificação de presos e como ela se relaciona com o exame criminológico
- Conheça as Regras de Mandela e suas finalidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Execução Penal", "legal_refs": ["Art. 8º da LEP", "Súmula 345/STF"], "jurisprudence": ["RE 456.789"], "confidence": 0.8, "extracted_at": "2026-05-31T15:16:11.357084+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=15", "doc_key": "eb76379631df7ccb811c19c70c38ac2c"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'a649f67dd61605364629eb4907ad78f8c460f35b409ee0ef193584eec610db09'),
  ('cpiuris2025::81a6a52d75add543f4b8701e222c4492', 'doutrina', 'cp_iuris', 'Execução Penal — Individualização da pena na fase executória', '## Individualização da pena na fase executória

A individualização da pena na execução é baseada nas características do apenado e nas intercorrências do processo de execução, com o objetivo de ressocialização, prevenção e conscientização.

### Conceitos
- **Individualização da pena**: Processo de determinação de uma pena específica para cada condenado
- **Fase executória**: Período após a sentença condenatória, em que a pena é aplicada e o condenado é submetido às medidas de segurança
- **Ressocialização**: Processo pelo qual o condenado se reintegra à sociedade
- **Prevenção**: Medida destinada a evitar futuras infrações criminais
- **Conscientização**: Ação de informar e educar o condenado sobre as consequências da sua conduta

### Referências legais
- Art. 5º da LEP

### Dicas de prova
- Entenda a importância da individualização da pena na execução
- Conheça os objetivos da ressocialização, prevenção e conscientização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Execução Penal", "legal_refs": ["Art. 5º da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:16:28.092800+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=14", "doc_key": "81a6a52d75add543f4b8701e222c4492"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '0420dad9973506c453d3ccf0428c0286e83dbb3eef180cf260af5a85ccebe820'),
  ('cpiuris2025::0648c395bb2d810e63ce0d6db0e11d31', 'doutrina', 'cp_iuris', 'Execução Penal — Veto Presidencial e Vacatio Legis', '## Veto Presidencial e Vacatio Legis

A derrubada de veto presidencial deve ser observada em relação à vacatio legis, que é o período de 30 dias após a promulgação da lei. Isso significa que as novas previsões do artigo 9º-A só entraram em vigor em 30 maio de 2021.

### Conceitos
- **Veto Presidencial**: Ato pelo qual o Presidente da República rejeita uma proposta legislativa apresentada pelo Congresso Nacional.
- **Vacatio Legis**: O período de 30 dias após a promulgação de uma lei, durante o qual não se pode aplicar a lei em questão.
- **Derrubada de Veto**: Ação do Congresso Nacional para anular um veto presidencial apresentado por um projeto de lei.
- **Art. 9º-A da LEP**: Lei que estabelece a obrigação de identificação do perfil genético, mediante extração de DNA, para condenados por crimes dolosos contra a pessoa ou pela vida.

### Referências legais
- Art. 9º-A da Lei nº X
- Súmula N da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre a vacatio legis e derrubada de veto presidencial podem ser complexas, mas é importante entender o período de 30 dias após a promulgação da lei.
- A identificação do perfil genético é um aspecto importante do art. 9º-A da LEP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Execução Penal", "legal_refs": ["Art. 9º-A da Lei nº X", "Súmula N da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T15:16:56.440319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=15", "doc_key": "0648c395bb2d810e63ce0d6db0e11d31"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'a995bce3ee01f2423bda542328f6bb4016f05c1c6fc96f5765367f4156f23ed2'),
  ('cpiuris2025::56c9542bb12d184bc1eb261958b1a9a1', 'doutrina', 'cp_iuris', 'Execução Penal — Identificação do Perfil Genético', '## Identificação do Perfil Genético

A lei exige que os condenados por crimes hediondos sejam submetidos à identificação do perfil genético, mediante extração de DNA, por técnica adequada e indolor.

### Conceitos
- **DNA**: material genético deixado no corpo das vítimas
- **Banco de dados sigiloso**: armazenamento de informações sobre identificação do perfil genético
- **Técnica adequada e indolor**: método de extração de DNA que não cause dor ao indivíduo

### Referências legais
- Art. 9º-A da LEP

### Dicas de prova
- Entenda a noção de crime hediondo e sua relação com a identificação do perfil genético
- Conheça as garantias mínimas de proteção de dados genéticos estabelecidas pela lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Execução Penal", "legal_refs": ["Art. 9º-A da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:18:04.383357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=16", "doc_key": "56c9542bb12d184bc1eb261958b1a9a1"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b04231fba05b493acaa4419ca8c7a981717e2f85e000964d0c6d0735af1aba37'),
  ('cpiuris2025::31d2d9542e4c0549f1db4ac11818382a', 'doutrina', 'cp_iuris', 'Execução Penal — Requisição de acesso ao banco de dados para identificação do perfil genético', '## Requisição de acesso ao banco de dados para identificação do perfil genético

A autoridade policial pode solicitar ao juiz competente o acesso ao banco de dados para obter a identificação do perfil genético do condenado por crimes graves contra a pessoa.

### Conceitos
- **Requisição de acesso ao banco de dados**: Solicitação feita pela autoridade policial para obter informações ou dados armazenados em um banco de dados
- **Identificação do perfil genético**: Procedimento que envolve a extração e análise do DNA para determinar o perfil genético de uma pessoa
- **Banco de dados sigiloso**: Arquivo ou sistema de armazenamento de informações que mantém a privacidade e a segurança dos dados
- **Regulamentação**: Ação de estabelecer regras e normas para a implementação de uma política ou procedimento

### Referências legais
- Art. 9º-A da Lei n.º 13.964/2019
- Lei n.º 12.654/2012
- Súmula N da STF

### Dicas de prova
- Entenda a importância da identificação do perfil genético no contexto da execução penal
- Conheça as regulamentações e garantias de proteção de dados genéticos estabelecidas pela lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Execução Penal", "legal_refs": ["Art. 9º-A da Lei n.º 13.964/2019", "Lei n.º 12.654/2012", "Súmula N da STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:19:02.121018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=16", "doc_key": "31d2d9542e4c0549f1db4ac11818382a"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '4547139d988be4acb9d30234515cc008721e83f1cdc2647d2e4824d3a37bd246'),
  ('cpiuris2025::2da2aec647075eb6b3f6e253c2cbd9fc', 'doutrina', 'cp_iuris', 'Execução Penal — Identificação de Perfil Genético', '## Identificação de Perfil Genético

Regras para a identificação de perfil genético em condenados, incluindo o acesso aos dados genéticos e documentos da cadeia de custódia.

### Conceitos
- **Lei n.º 12.654**: Lei que incluiu a identificação de perfil genético
- **Lei n.º 13.964**: Lei que regulamentou a identificação de perfil genético em condenados
- **Banco de perfis genéticos**: Banco de dados que armazena informações de identificação de perfil genético
- **Procedimento de identificação do perfil genético**: Atividade realizada para identificar o perfil genético de um condenado
- **Amostra biológica coletada**: Materiais biológicos coletados para a identificação do perfil genético

### Referências legais
- Art. 12.654, Lei nº 12.654
- Art. 13.964, Lei nº 13.964

### Dicas de prova
- Entenda a importância da identificação de perfil genético em condenados
- Conheça as regras para o acesso aos dados genéticos e documentos da cadeia de custódia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Execução Penal", "legal_refs": ["Art. 12.654, Lei nº 12.654", "Art. 13.964, Lei nº 13.964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:19:22.462861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=17", "doc_key": "2da2aec647075eb6b3f6e253c2cbd9fc"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '50314902e7d64c39abd43febb797a84584c8da5b81c1da57ba43841644cdf248'),
  ('cpiuris2025::dbb746ebc16e1a390e0d563421aaafe3', 'doutrina', 'cp_iuris', 'Execução Penal — Identificação do Perfil Genético', '## Identificação do Perfil Genético

A identificação do perfil genético é permitida apenas para fins exclusivos e não pode ser utilizada para outras práticas, de acordo com a Lei n.º 13.964/2019.

### Conceitos
- **Perfil Genético**: Identidade genética de uma pessoa
- **Fenotipagem Genética**: Análise da expressão das características físicas e biológicas de um indivíduo
- **Busca Familiar**: Procedimento utilizado para encontrar familiares de uma pessoa desconhecida

### Referências legais
- Art. 13.964, de 2019

### Dicas de prova
- Entenda a distinção entre identificação do perfil genético e fenotipagem genética.
- Conheça as consequências da recusa do condenado em submeter-se ao procedimento de identificação do perfil genético.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Execução Penal", "legal_refs": ["Art. 13.964, de 2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:19:55.814347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=17", "doc_key": "dbb746ebc16e1a390e0d563421aaafe3"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '7ae19c60e0f50ae2b77d3e62fe07d642f5b7beb471e4434185d05f0fb05ea9a0'),
  ('cpiuris2025::c3a499a6e91f16dcecd407f6065fc8ea', 'doutrina', 'cp_iuris', 'Execução Penal — Trabalho no Presídio', '## Trabalho no Presídio

O trabalho do condenado é um direito e dever, com finalidade educativa e produtiva, e deve ser remunerado. A recusa pode representar falta grave, mas não há vagas de trabalho para todos os internos.

### Conceitos
- **Trabalho no Presídio**: Condição de dignidade humana e meio de ressocialização
- **Direito ao Trabalho**: Dever do condenado, com finalidade educativa e produtiva
- **Remuneração pelo Trabalho**: Obrigação de pagar ao condenado pelo trabalho desempenhado

### Referências legais
- Art. 28 da Lei de Execução Penal

### Dicas de prova
- Distinção entre direito e dever
- Importância do trabalho para ressocialização
- Consequências da recusa ao trabalho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Execução Penal", "legal_refs": ["Art. 28 da Lei de Execução Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:21:12.093004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=18", "doc_key": "c3a499a6e91f16dcecd407f6065fc8ea"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '4be33ed4d6aff8b82a38e1c11a960aa4624a6b31ecb8f4f2ef79acd6ad5ce1a9'),
  ('cpiuris2025::99c8557c405a5c15d951ed4a7f376049', 'doutrina', 'cp_iuris', 'Execução Penal — Acesso aos bancos de perfis genéticos no sistema prisional', '## Acesso aos bancos de perfis genéticos no sistema prisional

O titular dos dados genéticos tem acesso aos bancos de perfis para contestar a cadeia de custódia e contradizer a utilização do material. O condenado não é obrigado a fornecer o material genético, mas pode ser incriminado por outros delitos.

### Conceitos
- **Acesso aos bancos de perfis**: O direito do titular dos dados genéticos de acessar os bancos de perfis para contestar a cadeia de custódia e contradizer a utilização do material.
- **Não preclusão**: A não perda do direito ao processo, mesmo que o condenado não seja submetido à identificação do perfil genético no momento do ingresso no sistema prisional.
- **Fenotipagem**: Práticas de busca familiar ou análise de características físicas para obter informações sobre a pessoa.
- **Nemo tenetur se detegere**: A garantia constitucional que proíbe a obrigação de uma pessoa a produzir prova contra si mesma.

### Referências legais
- Art. 50 da LEP

### Dicas de prova
- Entenda a importância do acesso ao banco de perfis genético e as consequências para o condenado.
- Conheça a noção de não preclusão e como ela se aplica à execução penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Execução Penal", "legal_refs": ["Art. 50 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:21:45.511602+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=18", "doc_key": "99c8557c405a5c15d951ed4a7f376049"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b1e46a3292b61b3c64d0b3d5047132b2ffac0eea2fd3426b9373ec3b0ef5de13'),
  ('cpiuris2025::edfb5eb768374dc2036ae695d0786037', 'doutrina', 'cp_iuris', 'Execução Penal — Remuneração dos Presos', '## Remuneração dos Presos

O artigo 29 da LEP estabelece que o trabalho do preso será remunerado, com um patamar mínimo diferenciado de remuneração que não pode ser inferior a ¾ do salário-mínimo.

### Conceitos
- **Remuneração**: valor pago aos presos pelo trabalho realizado
- **Patamar mínimo**: nível de remuneração estabelecido pela lei
- **Lei de Execução Penal (LEP)**: lei que regula a execução das penas

### Referências legais
- Art. 29 da LEP
- Art. 31 da LEP
- Art. 36 da LEP

### Jurisprudência
- ADPF 336 do STF

### Dicas de prova
- Entenda a diferença entre o trabalho intramuros e externo dos presos.
- Conheça as cautelas para a realização de obras públicas com presos em regime fechado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Execução Penal", "legal_refs": ["Art. 29 da LEP", "Art. 31 da LEP", "Art. 36 da LEP"], "jurisprudence": ["ADPF 336 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T15:21:58.428578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=19", "doc_key": "edfb5eb768374dc2036ae695d0786037"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'a46a226abc6304d2a38412bf3338e7608e28a18562ba0988dfb1a5b8a286b9d8'),
  ('cpiuris2025::7dac8a3fda7d2cdee4adbdfa55558d2d', 'doutrina', 'cp_iuris', 'Execução Penal — Trabalho Externo e Remição', '## Trabalho Externo e Remição

Presos em regime fechado podem executar trabalho externo, com direito à remição que reduz o tempo de expiação.

### Conceitos
- **Remição**: direito do condenado a reduzir o tempo de expiação
- **Trabalho Externo**: execução de trabalho fora da prisão

### Referências legais
- Art. 34, § 3º, da Lei nº 7.210/82

### Jurisprudência
- 1 STF. Plenário. ADPF 336/DF
- Súmula 443 do STF

### Dicas de prova
- Entenda a diferença entre trabalho externo e remição
- Conheça o valor de um dia de pena para cada doze horas de estudo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Execução Penal", "legal_refs": ["Art. 34, § 3º, da Lei nº 7.210/82"], "jurisprudence": ["1 STF. Plenário. ADPF 336/DF", "Súmula 443 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T15:22:48.809863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=19", "doc_key": "7dac8a3fda7d2cdee4adbdfa55558d2d"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'cd2bd4ac6cf019d3140d0105d45f8e7744e2a9ba3d62f6c4f82851b161b8a60f'),
  ('cpiuris2025::db70460e6fbd9e0b1aa9c7ecc6d6700f', 'doutrina', 'cp_iuris', 'Execução Penal — Direito à Remição', '## Direito à Remição

O preso tem direito à remição se a instituição de ensino for credenciada ao SISTEC do MEC, conforme Resolução 391 do CNJ.

### Conceitos
- **Remição**: Direito concedido ao preso para reduzir sua pena
- **SISTEC**: Sistema de Informação sobre o Ensino e Currículo do Exército Brasileiro
- **LEP**: Lei da Execução Penal
- **CNJ**: Conselho Nacional do Ministério Público

### Referências legais
- Art. 126 da LEP
- Resolução 391 do CNJ

### Jurisprudência
- HC 461.047/SP
- Recomendação 44 do CNJ

### Dicas de prova
- Distinção entre instituições de ensino credenciadas ao SISTEC e não.
- Interpretação extensiva do artigo 126 da LEP
- Diferença entre aprovação em exames e estudo formal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Execução Penal", "legal_refs": ["Art. 126 da LEP", "Resolução 391 do CNJ"], "jurisprudence": ["HC 461.047/SP", "Recomendação 44 do CNJ"], "confidence": 0.8, "extracted_at": "2026-05-31T15:23:55.068857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=20", "doc_key": "db70460e6fbd9e0b1aa9c7ecc6d6700f"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'cdd7165975833d388aea5e7cdc5f70529118082c26c1d5a3ce3eb1e395766100'),
  ('cpiuris2025::4f0b2df37ae9054d3ea1b69d3ed50cc5', 'doutrina', 'cp_iuris', 'Execução Penal — Remição da Execução Penal', '## Remição da Execução Penal

A remição da execução penal é uma forma de estímulo ao apenado para se engajar em atividades produtivas e intelectuais durante a execução da pena. É prevista no ECA e no Direito Tributário.

### Conceitos
- **Remição**: Forma de estímulo ao apenado para se engajar em atividades produtivas e intelectuais
- **Regime Fechado**: Regime em que o condenado é mantido em prisão perpétua ou por tempo indeterminado
- **Remição por Trabalho**: Período de tempo remido pelo trabalho, previsto no art. 126 da LEP
- **Remição por Estudo**: Período de tempo remido pelo estudo, previsto no art. 126 da LEP
- **Progressão do Regime**: Mudança do regime de execução da pena para um regime mais leniente
- **Livramento Condicional**: Condição que permite ao condenado sair da prisão antes do tempo previsto

### Referências legais
- Art. 126 da LEP
- Súmula 562/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre remição

### Dicas de prova
- Entenda a diferença entre remição por trabalho e remição por estudo
- Conheça as regras para calcular o tempo de remição
- Aprenda a aplicar a Súmula 562/STJ em casos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Execução Penal", "legal_refs": ["Art. 126 da LEP", "Súmula 562/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre remição"], "confidence": 0.8, "extracted_at": "2026-05-31T15:24:37.346318+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=20", "doc_key": "4f0b2df37ae9054d3ea1b69d3ed50cc5"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '74079e509fd539d88c416e87dba1aaa29bfb29e6e867fe327e4e83751bb73388'),
  ('cpiuris2025::e0b957baa3ee7838434ed293a0b727ef', 'doutrina', 'cp_iuris', 'Execução Penal — Remição da Pena', '## Remição da Pena

A remição é um instituto que permite ao condenado reduzir sua pena, sendo comum em casos de falta grave ou quando o condenado está autorizado a estudar fora do estabelecimento penal. O artigo 127 da LEP estabelece as regras para a revogação dos remidos.

### Conceitos
- **Remição**: Instituto que permite ao condenado reduzir sua pena
- **Falta grave**: Olapso da fuga do estabelecimento prisional ou falta grave que justifica a revogação dos remidos
- **Revogação dos remidos**: Ação do juiz para reduzir o tempo remido pelo trabalho ou pelo estudo

### Referências legais
- Art. 127 da LEP

### Jurisprudência
- Súmula Vinculante 9

### Dicas de prova
- Entenda a diferença entre falta grave e olapso da fuga do estabelecimento prisional
- Conheça as regras para a revogação dos remidos estabelecidas no artigo 127 da LEP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Execução Penal", "legal_refs": ["Art. 127 da LEP"], "jurisprudence": ["Súmula Vinculante 9"], "confidence": 0.8, "extracted_at": "2026-05-31T15:25:04.012525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=21", "doc_key": "e0b957baa3ee7838434ed293a0b727ef"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '02df9d3ea8206cf384747962aa22552e035257fc75b42c67e2ef0e8daa6a7622'),
  ('cpiuris2025::fc54ac2e4ed52f80e49a89271e0932e1', 'doutrina', 'cp_iuris', 'Execução Penal — Identificação de Perfil Genético', '## Identificação de Perfil Genético

Condenados por crimes dolosos com violência grave contra a pessoa ou contra a vida terão que se submeter a identificação de perfil genético.

### Conceitos
- **Crime Doloso**: Ato ilegal cometido com intenção de prejudicar alguém
- **Violência Grave**: Atáo que cause dano irreparável à pessoa
- **Banco de Perfis Genéticos**: Repositório de dados genéticos coletados por meio de procedimentos de identificação

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Perguntas sobre a identificação de perfil genético podem ser muito específicas, então leia atentamente o texto.
- Apenas as disposições legais mencionadas no texto são relevantes para essa questão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Execução Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:25:24.923077+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=21", "doc_key": "fc54ac2e4ed52f80e49a89271e0932e1"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'ba76acd9cff7ad33d1efb028aa3ad466ec920882c80469b19387145f05879d21'),
  ('cpiuris2025::763afcfe8cd5ca2aa1e0550f8a2d296e', 'doutrina', 'cp_iuris', 'Execução Penal — Remição e Benefícios aos Presos', '## Remição e Benefícios aos Presos

Resumo do texto sobre a remição e benefícios aos presos, incluindo a leitura como forma de remição.

### Conceitos
- **Apenas I está correta**: O trabalho do condenado apenas terá finalidade produtiva
- **Apenas II está correta**: O trabalho do preso não está sujeito ao regime da Consolidação das Leis do Trabalho
- **Apenas II e III estão corretas**: Aplicam-se à organização e aos métodos de trabalho as precauções relativas à segurança e à higiene
- **Todas estão incorretas**: 

### Referências legais
- Art. 129, § 1º da LEP
- Art. 126, § 4º da LEP
- Resolução 391 do CNJ

### Jurisprudência
- STJ
- STF
- RE 123456

### Dicas de prova
- Entenda a diferença entre remição e benefícios aos presos.
- Conheça as regras da Consolidação das Leis do Trabalho.
- Aprenda sobre a leitura como forma de remição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.22", "page_number": 22, "discipline": "Execução Penal", "legal_refs": ["Art. 129, § 1º da LEP", "Art. 126, § 4º da LEP", "Resolução 391 do CNJ"], "jurisprudence": ["STJ", "STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T15:25:52.381968+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=22", "doc_key": "763afcfe8cd5ca2aa1e0550f8a2d296e"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'afa8964a61e4b86b1fba37cf0403fc13d98b5b9294c0785d5f888423fcadd5f0'),
  ('cpiuris2025::9039bfeee403e3e3e3a294e0cf820f70', 'doutrina', 'cp_iuris', 'Execução Penal — Garantia de não produção de prova contra si', '## Garantia de não produção de prova contra si

A garantia de não produção de prova contra si é mencionada, mas ainda não foi debatida no STF.

### Conceitos
- **garantia de não produção de prova contra si**: direito do acusado de não ser obrigado a responder por fatos que não sejam comprovados
- **Art. 28 da LEP**: Lei do Processo Penal

### Referências legais
- Art. 28 da LEP

### Dicas de prova
- Entenda a garantia de não produção de prova contra si e como ela está relacionada à Lei do Processo Penal.
- Leia atentamente o artigo 28 da LEP e seus parágrafos para responder às questões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Execução Penal", "legal_refs": ["Art. 28 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:27:34.009641+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=23", "doc_key": "9039bfeee403e3e3e3a294e0cf820f70"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'e3aa18369879acf38bf7064b63782dd577428ededbb698f9ccbcbd0104be2358'),
  ('cpiuris2025::28edd64a5cfc8d9561ab198ea05ef54c', 'doutrina', 'cp_iuris', 'Execução Penal — Remição Ficta e Acrecimento de Tempo de Remição', '## Remição Ficta e Acrecimento de Tempo de Remição

A remição ficta não pode ser concedida em caso de falta de vagas nos estabelecimentos prisionais. No entanto, é possível acréscimo de 1/3 do tempo de remição se o preso concluir um curso superior durante o cumprimento da pena.

### Conceitos
- **Remição Ficta**: Concessão de redução da pena sem que haja sido cometido ato equivalente
- **Acrecimento de Tempo de Remição**: Adição de tempo à remição ficta em caso de conclusão de curso superior durante o cumprimento da pena

### Referências legais
- Art. 126, § 5º, Código de Processo Penal

### Dicas de prova
- Distinção entre remição ficta e acrécimo de tempo de remição
- Importância da conclusão de curso superior para o acrécimo de tempo de remição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Execução Penal", "legal_refs": ["Art. 126, § 5º, Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:28:03.957818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=23", "doc_key": "28edd64a5cfc8d9561ab198ea05ef54c"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '1be741b88ac34b807d7d3f280787fe19c30cbbee5302ce7776d6b1f34ba4182d'),
  ('cpiuris2025::a59af50fd31f34cd9926e622beae8ee7', 'doutrina', 'cp_iuris', 'Execução Penal — Deveres e Direitos dos Sentenciados', '## Deveres e Direitos dos Sentenciados

O artigo 39 da LEP estabelece os deveres do condenado, incluindo comportamento disciplinado, obediência e respeito. Já o artigo 40 estabelece os direitos do preso, como alimentação suficiente, atribuição de trabalho e previdência social.

### Conceitos
- **Deveres**: obrigações impostas ao condenado
- **Direitos**: benefícios concedidos ao preso
- **Comportamento disciplinado**: conduta correta e respeitosa
- **Obediência**: respeito às autoridades e ordens
- **Alimentação suficiente**: direito ao alimento adequado
- **Atribuição de trabalho**: direito à remuneração por trabalho realizado

### Referências legais
- Art. 39 da Lei n.º 7.210/84
- Art. 40 da Lei n.º 7.210/84

### Dicas de prova
- Entenda a distinção entre deveres e direitos dos sentenciados.
- Conheça as faltas graves, médias e leves previstas na LEP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.25", "page_number": 25, "discipline": "Execução Penal", "legal_refs": ["Art. 39 da Lei n.º 7.210/84", "Art. 40 da Lei n.º 7.210/84"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:28:32.245752+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=25", "doc_key": "a59af50fd31f34cd9926e622beae8ee7"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b82c515ff3b99b7291d246f42490dc3e3c7684db3f9d514464f906fb8e03f952'),
  ('cpiuris2025::84bca34051753ad3858c89779368e762', 'doutrina', 'cp_iuris', 'Execução Penal — Direitos dos Presos em Estabelecimentos Penais', '## Direitos dos Presos em Estabelecimentos Penais

Os presos têm direitos que podem ser suspensos ou restringidos por ato motivado do juiz da execução penal, exceto os direitos não mencionados no §1º.

### Conceitos
- **Direitos dos Presos**: direitos previstos para os presos em estabelecimentos penais
- **Suspensão de Direitos**: ação do juiz da execução penal que suspende ou restringe um direito do preso
- **Restrição de Liberdade**: restricção das liberdades do preso, como suspensão de visitas ou entrada em estabelecimento

### Referências legais
- Art. §1º da Lei nº 14.994/2024
- Súmula N da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre suspensão e restrição de direitos dos presos.
- Conheça os direitos não mencionados no §1º do artigo que podem ser suspenso ou restringido.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Execução Penal", "legal_refs": ["Art. §1º da Lei nº 14.994/2024", "Súmula N da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T15:29:53.511897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=26", "doc_key": "84bca34051753ad3858c89779368e762"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '6ed1b2937e0d74a50bfc3c2c16328d50355e28103f309c625a0e1b9ff7c01a80'),
  ('cpiuris2025::63a31d66c578ca047d0c6f0179eae8cc', 'doutrina', 'cp_iuris', 'Execução Penal — Preservação da Integridade Moral e Uso de Algemas', '## Preservação da Integridade Moral e Uso de Algemas

A execução penal deve preservar a integridade moral, evitando a divulgação de informações que possam perturbar a segurança e disciplina dos estabelecimentos penais. O uso de algemas é excepcional e deve ser justificado por escrito.

### Conceitos
- **Integridade Moral**: Preservação da dignidade e respeito aos direitos humanos do preso
- **Uso de Algemas**: Excepcional utilização para casos de resistência, fundado receio de fuga ou perigo à integridade física

### Referências legais
- Art. 198 da LEP
- Súmula Vinculante 11

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre uso de algemas excepcional e não excepcional
- Entender a importância da preservação da integridade moral no sistema penitenciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Execução Penal", "legal_refs": ["Art. 198 da LEP", "Súmula Vinculante 11"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T15:30:02.437378+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=26", "doc_key": "63a31d66c578ca047d0c6f0179eae8cc"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '5b763c20388b631f474448502bd584dcaecfebb1c55278239ac2bd484d61bc18'),
  ('cpiuris2025::03f94a19dd8691d9206cc7bb38d19a14', 'doutrina', 'cp_iuris', 'Execução Penal — Uso de algemas em prisões', '## Uso de algemas em prisões

O uso de algemas em prisões é sujeito a cautela e pode ser considerado excessivo, gerando notoriedade. A regra é que o preso possa ficar sem as algemas, exceto se houver fundamentação concreta.

### Conceitos
- **Cautela**: exigência de cautela para evitar abuso de poder
- **Nulidade da prisão**: anulação do ato processual que resultou na prisão
- **Direito à comunicação com o meio exterior**: direito do preso a receber cartas de terceiros

### Referências legais
- Art. 41, parágrafo único, da Lei n.º 7.210/84

### Jurisprudência
- HC 70814, STF - Min. CELSO DE MELLO

### Dicas de prova
- Distinção entre o direito à comunicação com o meio exterior e a interceptação de cartas
- Importância da cautela no uso de algemas em prisões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Execução Penal", "legal_refs": ["Art. 41, parágrafo único, da Lei n.º 7.210/84"], "jurisprudence": ["HC 70814, STF - Min. CELSO DE MELLO"], "confidence": 0.8, "extracted_at": "2026-05-31T15:30:45.562135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=27", "doc_key": "03f94a19dd8691d9206cc7bb38d19a14"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '27736813cfcff449e1442dfc4f79f074afa7ea185abc765c06a2f78af2c040cb'),
  ('cpiuris2025::3f91d42749732df4ab98ea6a37f8eda1', 'doutrina', 'cp_iuris', 'Disciplina nos Estabelecimentos Prisionais — Conceito e Importância da Disciplina', '## Conceito e Importância da Disciplina

A disciplina é um grande desafio nos estabelecimentos prisionais, diante da estrutura física precária e falta de servidores. O condenado deve cumprir as normas disciplinares.

### Conceitos
- **Disciplina**: Conceito de disciplina nos estabelecimentos prisionais
- **Normas Disciplinares**: Regras que os condenados devem seguir para manter a ordem e a segurança no estabelecimento prisional

### Referências legais
- Art. 44 da LEP

### Dicas de prova
- Entenda o conceito de disciplina nos estabelecimentos prisionais
- Conheça as normas disciplinares e suas importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Disciplina nos Estabelecimentos Prisionais", "legal_refs": ["Art. 44 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:31:40.172409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=27", "doc_key": "3f91d42749732df4ab98ea6a37f8eda1"}'::jsonb, '{"materia": "Disciplina nos Estabelecimentos Prisionais"}'::jsonb, 'cp_iuris_2025', 'ef7d7a0915952234e82aaf2adeb12fb329a24e95a20e65f0384ffe84ac110e8b'),
  ('cpiuris2025::6f4b486fcb2069db9adfc779da405a2c', 'doutrina', 'cp_iuris', 'Execução Penal — Disciplina e Princípios', '## Disciplina e Princípios

A disciplina é a colaboração com a ordem, obediência às autoridades e desempenho do trabalho. Estão sujeitos à disciplina condenados à pena privativa de liberdade ou restritiva de direitos, presos provisórios e outros que cumprem medida de segurança.

### Conceitos
- **Disciplina**: Colaboração com a ordem, obediência às autoridades e desempenho do trabalho
- **Princípio da legalidade e da anterioridade**: Necessidade de expressa e anterior previsão legal ou regulamentar para aplicar sanções disciplinares
- **Vedação às penas cruéis e desumanas**: Proibição de punir com morte, caráter perpétuo, trabalhos forçados, banimento ou penas cruéis

### Referências legais
- Art. 44, LEP
- Art. 45, LEP
- Art. 5º, XLVII da CF/88

### Dicas de prova
- Entenda a noção de disciplina e seus princípios
- Conheça as limitações da execução penal
- Aprenda a aplicar o princípio da legalidade e da anterioridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.28", "page_number": 28, "discipline": "Execução Penal", "legal_refs": ["Art. 44, LEP", "Art. 45, LEP", "Art. 5º, XLVII da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:32:33.828000+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=28", "doc_key": "6f4b486fcb2069db9adfc779da405a2c"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b12e507b0922ae4b12e23c2b73ef0c301207ff03a9e2bcc0f676d64bc11fb486'),
  ('cpiuris2025::251683337ddfa99c1c3942e6b9035c3d', 'doutrina', 'cp_iuris', 'Execução Penal — Princípio da Pessoalidade e Individualização das Sanções', '## Princípio da Pessoalidade e Individualização das Sanções

A sanção disciplinar deve ser individualizada, não permitindo sanções coletivas, mesmo em casos de autoria coletiva. A individualização é necessária para evitar a imposição de falta grave ao executado sem prova de autoria.

### Conceitos
- **Princípio da Pessoalidade**: A responsabilidade objetiva do Estado
- **Individualização das Sanções**: A aplicação de sanção específica a cada indivíduo, considerando suas circunstâncias
- **Autoria Coletiva**: Onde mais de uma pessoa está envolvida na prática de um crime
- **Sanção Coletiva**: A aplicação de sanção a todos os envolvidos em uma situação, sem individualização
- **In Dubio pro Reo**: A aplicação da sanção mais benéfica ao reeducando, quando não é possível determinar a autoria

### Referências legais
- Art. 45, §3°, LEP
- Art. 5º, XLV, CRFB

### Jurisprudência
- STJ - Tese 146
- Súmula N STF

### Dicas de prova
- Entenda a importância da individualização das sanções em casos de autoria coletiva.
- Conheça o princípio da intranscendência e como ele se aplica à execução penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.29 (1)", "page_number": 29, "discipline": "Execução Penal", "legal_refs": ["Art. 45, §3°, LEP", "Art. 5º, XLV, CRFB"], "jurisprudence": ["STJ - Tese 146", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T15:33:35.941159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=29", "doc_key": "251683337ddfa99c1c3942e6b9035c3d"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '047caf3323957754c77c4c032225658c44929fb4f28142fcfc0dabd4a0b13464'),
  ('cpiuris2025::279f67b45b5b50823f7b0bd2ff07d68a', 'doutrina', 'cp_iuris', 'Execução Penal — Normas Disciplinares na Execução Penal', '## Normas Disciplinares na Execução Penal

As normas disciplinares devem ser explicitadas ao condenado no início do cumprimento da pena, sendo um regramento diferenciado que não é considerado conhecimento presumido.

### Conceitos
- **Normas Disciplinares**: Regulamentação específica para os condenados em execução penal
- **Conhecimento Presumido**: A crença implícita de que uma regra é conhecida sem necessidade de explicitação
- **Falta Disciplinar**: O descumprimento das normas disciplinares, podendo ser classificado como leve, média ou grave

### Referências legais
- Art. 46, LEP
- Art. 50 e 52 da LEP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre conhecimento presumido e regramento diferenciado
- Conheça as consequências do descumprimento das normas disciplinares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Execução Penal", "legal_refs": ["Art. 46, LEP", "Art. 50 e 52 da LEP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T15:33:47.057110+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=29", "doc_key": "279f67b45b5b50823f7b0bd2ff07d68a"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '3fc7c1b17647f98696a8cd024df09603993961b6ab6d0c49a1d42fc683cffac9'),
  ('cpiuris2025::7869551aa5db0738ecc0c5e1c53c602f', 'doutrina', 'cp_iuris', 'Execução Penal — Princípio da Ressocialização', '## Princípio da Ressocialização

A pena tem como finalidade ressocializar o condenado, com caráter retributivo e preventivo especial para evitar que ele volte a praticar crimes.

### Conceitos
- **Ressocialização**: Processo pelo qual o condenado é reintroduzido na sociedade
- **Pena retributiva**: Caráter da pena que visa punir o condenado
- **Pena preventiva especial**: Caráter da pena que visa evitar que o condenado volte a praticar crimes

### Referências legais
- Art. 10 da LEP

### Jurisprudência
- HC-292.869/SP. Relatora Ministra MARIA THEREZA DE ASSIS MOURA. SEXTA TURMA, Dje 29/10/2014

### Dicas de prova
- Entenda o conceito de ressocialização e sua importância na execução penal
- Diferencie entre pena retributiva e preventiva especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Execução Penal", "legal_refs": ["Art. 10 da LEP"], "jurisprudence": ["HC-292.869/SP. Relatora Ministra MARIA THEREZA DE ASSIS MOURA. SEXTA TURMA, Dje 29/10/2014"], "confidence": 0.8, "extracted_at": "2026-05-31T15:34:43.711657+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=30", "doc_key": "7869551aa5db0738ecc0c5e1c53c602f"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '90cc14dad0ba89f764a3fc44a5a92ab9d48a462b41f50fdd40a92271a4c07ef3'),
  ('cpiuris2025::8ea489973faa84fd471a7548b9e68cee', 'doutrina', 'cp_iuris', 'Execução Penal — Classificação de faltas disciplinares', '## Classificação de faltas disciplinares

A teoria é linda, mas a realidade é outra. A classificação de faltas disciplinares em leves, médias e graves é feita pelo artigo 49 da LEP, com sanções específicas para cada uma.

### Conceitos
- **Falta grave**: Classificação taxativa prevista na LEP
- **Falta leve**: Previsão na legislação local
- **Falta média**: Previsão na legislação local
- **Sanção correspondente**: Pena aplicada à tentativa com a sanção da falta consumada

### Referências legais
- Art. 49, LEP

### Dicas de prova
- Diferença entre tentativa e consumação de falta
- Sanções para faltas graves e leves', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Execução Penal", "legal_refs": ["Art. 49, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:35:22.698371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=30", "doc_key": "8ea489973faa84fd471a7548b9e68cee"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '7206d59bdafe03b0679d6398e83721b364c29e86ee774c1f8eca01739eef872f'),
  ('cpiuris2025::cac234b1cbf5de31ab7bda6602083daa', 'doutrina', 'cp_iuris', 'Execução Penal — Faltas graves', '## Faltas graves

As faltas graves são previstas no art. 50, I a VIII, e no art. 51, I a III do Código de Processo Penal, e incluem infrações como fugir, possuir instrumentos capazes de ofender a integridade física de outrem, provocar acidente de trabalho e descumprimento das condições impostas.

### Conceitos
- **Fuga**: Saiar do estabelecimento prisional sem autorização
- **Possuir instrumentos capazes de ofender a integridade física de outrem**: Possuir objetos que possam causar dano a outrem
- **Provocar acidente de trabalho**: Causar um acidente no local de trabalho de forma dolosa
- **Descumprimento das condições impostas**: Não cumprir as regras e condições impostas no regime aberto

### Referências legais
- Art. 50, I a VIII, Código de Processo Penal

### Dicas de prova
- Perguntas sobre faltas graves podem ser respondidas com base nos incisos do artigo 50 e 51 do Código de Processo Penal
- Lembre-se de que a fuga é considerada falta grave, independentemente da situação do preso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Execução Penal", "legal_refs": ["Art. 50, I a VIII, Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:36:19.484402+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=31", "doc_key": "cac234b1cbf5de31ab7bda6602083daa"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '8f75d1534e2bcbd81702b97fca5428d373cd9392235be6696477c9f3fe69fd5e'),
  ('cpiuris2025::384e9c0a75c8b36792151855ed1a4141', 'doutrina', 'cp_iuris', 'Execução Penal — Falta Grave', '## Falta Grave

A posse, utilização ou fornecimento de aparelho telefônico, rádio ou instrumento similar que permite comunicação com outros presos ou ambiente externo é considerado falta grave.

### Conceitos
- **Falta Grave**: ofensa grave cometida por um detento
- **Posse/uso de aparelho celular**: considerado falta grave desde que possua apenas o chip do celular

### Referências legais
- Art. X da Lei Y
- Súmula N STJ
- STJ, AgRg no HC n. 671.045/GO
- STJ, T6, AgRg no HC 845565 / SP

### Jurisprudência
- RE 123456
- Súmula 660 STJ

### Dicas de prova
- Distinção entre posse e uso de aparelho celular
- Importância da materialidade da infração disciplinar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Execução Penal", "legal_refs": ["Art. X da Lei Y", "Súmula N STJ", "STJ, AgRg no HC n. 671.045/GO", "STJ, T6, AgRg no HC 845565 / SP"], "jurisprudence": ["RE 123456", "Súmula 660 STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T15:36:39.401210+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=31", "doc_key": "384e9c0a75c8b36792151855ed1a4141"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '1a99e069c5873701b48b8d5c47218703f2926073d4fab495328d4c923aa6ce97'),
  ('cpiuris2025::ebf161e157162b058a5ab454e27659dd', 'doutrina', 'cp_iuris', 'Execução Penal — Faltas graves e consequências para condenados à pena restritiva de direitos', '## Faltas graves e consequências para condenados à pena restritiva de direitos

Descreve as faltas graves cometidas por condenados à pena restritiva de direitos, incluindo a falta de cumprimento das restrições impostas, o retardamento do cumprimento da obrigação e a inobservância dos deveres previstos no artigo 39.

### Conceitos
- **Falta grave**: Cometimento de uma infração que implica sanção disciplinar
- **Pena restritiva de direitos**: Tipo de pena que substitui a privativa de liberdade, com restrições ao direito de exercer certas atividades
- **Deveres previstos no artigo 39**: Requisitos legais que devem ser cumpridos pelos condenados à pena restritiva de direitos
- **Falta grave cometida**: Cometimento de uma infração que implica sanção disciplinar, como a falta de cumprimento das restrições impostas ou o retardamento do cumprimento da obrigação

### Referências legais
- Art. 39
- Art. 44
- Art. 50
- Art. 51

### Jurisprudência
- Súmula 661 STJ

### Dicas de prova
- Entenda a diferença entre falta grave e pena restritiva de direitos
- Conheça as consequências para condenados que cometem falta grave
- Análise do artigo 39 e seus deveres', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Execução Penal", "legal_refs": ["Art. 39", "Art. 44", "Art. 50", "Art. 51"], "jurisprudence": ["Súmula 661 STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T15:37:32.100159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=32", "doc_key": "ebf161e157162b058a5ab454e27659dd"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '4e189e701a94a145452f77be5bd57c340d58c67eec6af6ab29e2ed397c01f2b5'),
  ('cpiuris2025::15d39816d0e357e35483691fc3bb687a', 'doutrina', 'cp_iuris', 'Execução Penal — Faltas e Sanções na Execução Penal', '## Faltas e Sanções na Execução Penal

Resumo objetivo: A falta grave no curso da execução penal é considerada como uma falta permanente, com a aplicação de sanções disciplares. A progressão de regime prisional é determinada pela data da recaptura, não pela data da falta ou fuga.

### Conceitos
- **Falta grave**: Considerada como uma falta permanente
- **Progressão de regime prisional**: Determinada pela data da recaptura, não pela data da falta ou fuga

### Referências legais
- Art. 52 da LEP

### Jurisprudência
- {''term'': ''Súmula 533 do STJ'', ''definition'': ''Importância do procedimento administrativo pelo diretor do estabelecimento prisional para o reconhecimento da falta disciplinar''}

### Dicas de prova
- Distinção entre falta grave e progressão de regime prisional
- Reconhecimento da falta disciplinar pelo Poder Judiciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Execução Penal", "legal_refs": ["Art. 52 da LEP"], "jurisprudence": ["{''term'': ''Súmula 533 do STJ'', ''definition'': ''Importância do procedimento administrativo pelo diretor do estabelecimento prisional para o reconhecimento da falta disciplinar''}"], "confidence": 0.8, "extracted_at": "2026-05-31T15:37:35.718744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=32", "doc_key": "15d39816d0e357e35483691fc3bb687a"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '3d903895719165fbc58cd8709dee5725c75300cfa2f0c9b365887941c9826e7c'),
  ('cpiuris2025::0589b4cddcc20a8e88a80665fd9d92a6', 'doutrina', 'cp_iuris', 'Execução Penal — Regressão do regime de execução', '## Regressão do regime de execução

A regressão do regime de execução ocorre quando o condenado comete falta grave ou frustra os fins da execução. Isso pode levar à transferência para um regime mais rigoroso, como o fechado.

### Conceitos
- **Regressão do regime**: Mudança de regime de execução para um mais rigoroso
- **Falta grave**: Comportamento que configura crime doloso ou falta grave
- **Transferência para regime mais rigoroso**: Mudança de regime de execução para um mais rigoroso, como o fechado
- **Frustrar os fins da execução**: Comportamento que impede a realização dos objetivos da execução
- **Multas cumulativas**: Sancionações adicionais impostas ao condenado por falta grave

### Referências legais
- Art. 118, §2°, LEP

### Dicas de prova
- Reconhecer a falta grave e sua consequência na regressão do regime
- Entender a diferença entre perda de remidos e recontagem dos lapsos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Execução Penal", "legal_refs": ["Art. 118, §2°, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:39:55.404224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=34", "doc_key": "0589b4cddcc20a8e88a80665fd9d92a6"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '6ef5f7dd1fae82d86caf73466047fa907878cf81573326d5086ed5d617295dbe'),
  ('cpiuris2025::c178e5dd21e0b3ff5b8a247dcbdf4b5b', 'doutrina', 'cp_iuris', 'Execução Penal — Homologação de Falta em Execução Penal', '## Homologação de Falta em Execução Penal

O PAD não é mais imprescindível e a homologação de falta pode ser feita sem prévia conclusão do documento, desde que garantido o contraditório e da ampla defesa.

### Conceitos
- **Contraditório**: Direito do réu de se manifestar sobre as acusações
- **Ampla Defesa**: Direito do réu de ter assistência jurídica adequada
- **Audiência de Justificação**: Procedimento em que o acusado tem a oportunidade de se manifestar sobre as acusações

### Referências legais
- Art. 59 da Lei nº 7.210/82 (LEP)
- Súmula 635 do STF
- Art. 118 da LEP

### Jurisprudência
- RE 123456
- Tema repetitivo: Audiência de Justificação

### Dicas de prova
- Entenda a importância do contraditório e da ampla defesa no procedimento de execução penal
- Conheça o artigo 59 da LEP e sua relação com a audiência de justificação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Execução Penal", "legal_refs": ["Art. 59 da Lei nº 7.210/82 (LEP)", "Súmula 635 do STF", "Art. 118 da LEP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Audiência de Justificação"], "confidence": 0.8, "extracted_at": "2026-05-31T15:40:00.426651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=33", "doc_key": "c178e5dd21e0b3ff5b8a247dcbdf4b5b"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '10cc3f67cb19d89541aa81ed0fa48eea6a83a371cb981bfd824532ce4995e84d'),
  ('cpiuris2025::a3ea3c38801ba4303080b6f1614271a5', 'doutrina', 'cp_iuris', 'Execução Penal — Necessidade de Procedimento Administrativo Disciplinar (PAD) em execução penal', '## Necessidade de Procedimento Administrativo Disciplinar (PAD) em execução penal

O STF entendeu que a audiência de justificação realizada na presença do defensor e do Ministério Público afasta a necessidade de prévia conclusão do PAD, desde que o condenado seja ouvido.

### Conceitos
- **Audiência de justificação**: ouvir o condenado na presença do defensor e do Ministério Público
- **Procedimento Administrativo Disciplinar (PAD)**: procedimento que apura a prática de falta grave durante o cumprimento da pena
- **Contraditório e ampla defesa**: direito do condenado de ser ouvido e representado por um advogado

### Referências legais
- Art. 515, Código de Processo Penal
- STF - RE 972598
- Súmula 533/STJ

### Jurisprudência
- RE 972598 (2020)
- HC 581.854/PR (2020)

### Dicas de prova
- Entenda a importância da audiência de justificação na execução penal
- Conheça o conceito de PAD e sua necessidade em determinadas situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Execução Penal", "legal_refs": ["Art. 515, Código de Processo Penal", "STF - RE 972598", "Súmula 533/STJ"], "jurisprudence": ["RE 972598 (2020)", "HC 581.854/PR (2020)"], "confidence": 0.8, "extracted_at": "2026-05-31T15:40:18.650738+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=33", "doc_key": "a3ea3c38801ba4303080b6f1614271a5"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '54119d20858e744c82823c486dc92d260b3ed50032634ad694a610835f4dd680'),
  ('cpiuris2025::4dc41b12b2cfea809eaa0223adb2f8e1', 'doutrina', 'cp_iuris', 'Execução Penal — Prescrição de Faltas Disciplinares', '## Prescrição de Faltas Disciplinares

A prescrição das faltas disciplinares é estabelecida pela jurisprudência, com base no prazo prescricional previsto no Código Penal (art. 109, inciso VI), que é de três anos.

### Conceitos
- **Prescrição**: O período durante o qual uma ação não pode ser iniciada ou prosseguida
- **Falta Disciplinar**: Infração cometida por um funcionário público que não é punível segundo o Código Penal
- **Prazo Prescricional**: O período durante o qual uma ação pode ser iniciada ou prosseguida

### Referências legais
- Art. 109, inciso VI do Código Penal
- Súmula 342 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre prescrição e prazo prescricional
- Conheça o artigo 109, inciso VI do Código Penal
- Aprenda com os exemplos de faltas disciplinares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Execução Penal", "legal_refs": ["Art. 109, inciso VI do Código Penal", "Súmula 342 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T15:42:17.682724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=35", "doc_key": "4dc41b12b2cfea809eaa0223adb2f8e1"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'd8dd5db46725b94ae2ae3f87ca8b0c07ec40207d9d4b4d54350565cd58f82392'),
  ('cpiuris2025::5e29ecfad0de945daa15d155490b9b92', 'doutrina', 'cp_iuris', 'Execução Penal — Livramento Condicional e Princípios do Pacote Anticrime', '## Livramento Condicional e Princípios do Pacote Anticrime

O livramento condicional é concedido se o réu não cometer falta grave nos últimos 12 meses. A contagem do prazo para progressão de regime de cumprimento de pena é interrompida com o cometimento de falta grave.

### Conceitos
- **Livramento Condicional**: Concessão da liberdade condicional ao réu que não cometeu falta grave nos últimos 12 meses
- **Pacote Anticrime**: Lei n.º 13.964/2019, que inseriu o entendimento sumulado no artigo 112 da LEP em seu parágrafo 6º
- **Falta Grave**: Infração que justifica a interrupção da contagem do prazo para progressão de regime de cumprimento de pena
- **Progressão de Regime**: Mudança do regime de cumprimento de pena, geralmente com redução da pena ou aumento da liberdade

### Referências legais
- Art. 83, inc. III, ''b'' do Código Penal
- Súmula 534/STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre livramento condicional e outros regimes de cumprimento de pena
- Conheça o Pacote Anticrime e suas implicações no direito penal brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Execução Penal", "legal_refs": ["Art. 83, inc. III, ''b'' do Código Penal", "Súmula 534/STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T15:42:32.741506+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=34", "doc_key": "5e29ecfad0de945daa15d155490b9b92"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '7d3ec8f97fe73ce19da5e55ae71d039bb612147e2575b48736b6189bf9f3ecae'),
  ('cpiuris2025::a55881cd923fa047aaa0e88a147e1315', 'doutrina', 'cp_iuris', 'Execução Penal — Falta grave e benefícios', '## Falta grave e benefícios

A falta grave durante a execução da pena privativa de liberdade interrompe o prazo para obtenção da progressão no regime de cumprimento da pena, mas não afeta os prazos para livramento condicional, indulto e comutação.

### Conceitos
- **Falta grave**: Cometimento de falta durante a execução da pena privativa de liberdade
- **Progressão no regime de cumprimento da pena**: Requisito objetivo para obtenção da progressão no regime de cumprimento da pena
- **Livramento condicional**: Benefício concedido ao réu que comete falta grave durante a execução da pena
- **Indulto**: Atividade do Poder Executivo para reduzir ou extinguir a pena de um réu
- **Comutação**: Atividade do Poder Executivo para reduzir a pena de um réu

### Referências legais
- Art. 112, § 6º, LEP
- Súmula 441/STJ
- Súmula 535/STJ
- Súmula 526/STJ
- Decreto nº 11.302/2022

### Jurisprudência
- RE 123456
- Tema repetitivo Súmula 441/STJ
- Tema repetitivo Súmula 535/STJ
- Tema repetitivo Súmula 526/STJ

### Dicas de prova
- Entenda a diferença entre falta grave e progressão no regime de cumprimento da pena
- Conheça os requisitos para obtenção de livramento condicional, indulto e comutação
- Lembre-se de que a prática de falta grave não afeta o prazo para livramento condicional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Execução Penal", "legal_refs": ["Art. 112, § 6º, LEP", "Súmula 441/STJ", "Súmula 535/STJ", "Súmula 526/STJ", "Decreto nº 11.302/2022"], "jurisprudence": ["RE 123456", "Tema repetitivo Súmula 441/STJ", "Tema repetitivo Súmula 535/STJ", "Tema repetitivo Súmula 526/STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T15:43:25.669896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=35", "doc_key": "a55881cd923fa047aaa0e88a147e1315"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '9d8bb130b51bf1cbace310c67ed859adc10363f0dfd11a564252a780f8b8278d'),
  ('cpiuris2025::966993d03ca895e3c76899b98c348d79', 'doutrina', 'cp_iuris', 'Execução Penal — Livramento Condicional', '## Livramento Condicional

A Lei PM Sargento Dias acrescentou os incisos VI, VII e VIII ao art. 146-C da LEP, aumentando as hipóteses de utilização da tornozeleira eletrônica.

### Conceitos
- **Livramento Condicional**: Concessão do direito de liberdade condicional a um condenado
- **Lei PM Sargento Dias**: Lei que acrescentou os incisos VI, VII e VIII ao art. 146-C da LEP

### Referências legais
- Art. 14.843/2024
- Art. 12.258/2010

### Dicas de prova
- Entenda a diferença entre livramento condicional e liberdade condicional
- Conheça as hipóteses de utilização da tornozeleira eletrônica previstas na Lei PM Sargento Dias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Execução Penal", "legal_refs": ["Art. 14.843/2024", "Art. 12.258/2010"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:44:17.085923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=36", "doc_key": "966993d03ca895e3c76899b98c348d79"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '0d480eb998b9467e5717d2b314caaca3ffea031177d2ea33d86c18a3e3780e9b'),
  ('cpiuris2025::6e34ba99ac2570055182d5f82ee58751', 'doutrina', 'cp_iuris', 'Execução Penal — Fuga e falta grave', '## Fuga e falta grave

A fuga é considerada uma falta grave de natureza permanente, mas os indivíduos são reabilitados após um período e retornam ao bom comportamento carcerário.

### Conceitos
- **Fuga**: falta grave de natureza permanente
- **Reabilitação**: restabelecimento da condição de bom comportamento carcerário após um período
- **Tornozeleira eletrônica**: sistema de monitorização eletrônica para controle do preso
- **Falta grave**: falta que configura falta grave de natureza permanente

### Referências legais
- Art. 151, Código Penitenciário do DF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre fuga e reabilitação

### Dicas de prova
- Distinção entre falta grave e reabilitação
- Entendimento da tornozeleira eletrônica como meio de monitorização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Execução Penal", "legal_refs": ["Art. 151, Código Penitenciário do DF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre fuga e reabilitação"], "confidence": 0.8, "extracted_at": "2026-05-31T15:44:22.800187+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=36", "doc_key": "6e34ba99ac2570055182d5f82ee58751"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '808c08130e7a0df23a671dfa91dd37b6e940db6724b70caa92fce8c52bd1a2f3'),
  ('cpiuris2025::ed20e1dac4ff8959558e6c3543f0afcb', 'doutrina', 'cp_iuris', 'Execução Penal — Consequências da violação dos deveres previstos no caput do artigo', '## Consequências da violação dos deveres previstos no caput do artigo

O parágrafo único do artigo estabelece as consequências para quem violar os deveres previstos, incluindo a revogação do livramento condicional e a conversão de pena restritiva de direitos em pena privativa de liberdade.

### Conceitos
- **Falta grave**: Prática que caracteriza-se pela violação das condições estabelecidas para o reeducando
- **Tornozeleira eletrônica**: Dispositivo utilizado para monitorar a localização do reeducando
- **Permissão de uso da tornozeleira**: Autorização para o reeducando circular livremente dentro de um determinado perímetro

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre falta grave e falta leve
- Conheça as consequências para o reeducando que violar as condições estabelecidas
- Aprenda a importância da permissão de uso da tornozeleira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Execução Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:45:41.728940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=37", "doc_key": "ed20e1dac4ff8959558e6c3543f0afcb"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '991563100ff7ff49cda33e260cda6c59ef1c7ee950cff751fd47b6695ff742fd'),
  ('cpiuris2025::6bacc01eab85781513102c69e3967fb6', 'doutrina', 'cp_iuris', 'Execução Penal — Regime Disciplinar Diferenciado (RDD)', '## Regime Disciplinar Diferenciado (RDD)

O RDD é uma sanção disciplinar aplicada em determinadas situações graves, com o objetivo de tutelar a ordem e a disciplina internas no curso da execução penal.

### Conceitos
- **Regime Disciplinar Diferenciado (RDD)**: Sanção disciplinar aplicada em situações graves para tutelar a ordem e a disciplina internas.
- **Crime Doloso**: Ação ou omissão que causa dano à ordem e à disciplina internas.
- **Subversão da Ordem**: Repercussão negativa do crime doloso no ambiente carcerário e na estabilidade institucional do sistema carcerário.

### Referências legais
- Art. 52, caput e §1º da LEP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre o RDD e os outros regimes de cumprimento de pena.
- Identifique as hipóteses de aplicação do RDD.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Execução Penal", "legal_refs": ["Art. 52, caput e §1º da LEP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T15:46:23.149496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=38", "doc_key": "6bacc01eab85781513102c69e3967fb6"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '76905a625a7da7cd462db643595f1fb0de377e1f527b42e22ea394c0211a42ad'),
  ('cpiuris2025::1e1155b9be5e7b18ec7e1f43d25874ee', 'doutrina', 'cp_iuris', 'Execução Penal — Faltas graves e monitoração eletrônica', '## Faltas graves e monitoração eletrônica

O indivíduo que esquece o carregador de tornozeleira pode perder contato com a central de monitoração, qualificando a falta como grave. O rompimento da tornozeleira também é considerado falta grave. A monitoração eletrônica pode ser revogada se o acusado violar os deveres ou cometer falta grave.

### Conceitos
- **Falta grave**: Qualidade da infração que a qualifica como sendo de natureza mais grave
- **Monitoração eletrônica**: Método utilizado para fiscalizar o cumprimento das penas
- **Deveres do condenado**: Obrigações previstas na Lei de Execução Penal que devem ser cumpridas pelo condenado

### Referências legais
- Art. 50, LEP
- Art. 39, LEP
- Art. 146-D, LEP

### Dicas de prova
- Diferenciar entre falta grave e falta leve
- Entender a importância da monitoração eletrônica no cumprimento das penas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Execução Penal", "legal_refs": ["Art. 50, LEP", "Art. 39, LEP", "Art. 146-D, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:46:36.362565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=37", "doc_key": "1e1155b9be5e7b18ec7e1f43d25874ee"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'd33cea6b8503ecd4f4ed0eec9140142d43e63ed55b86dac99e9cc5d611945113'),
  ('cpiuris2025::f8638403a3c7d6a2fa9b817e664456d1', 'doutrina', 'cp_iuris', 'Execução Penal — Fundadas suspeitas de envolvimento ou participação em organização criminosa', '## Fundadas suspeitas de envolvimento ou participação em organização criminosa

O §1º, inciso II, da Lei nº X, tratam presos provisórios ou condenados com fundadas suspeitas de envolvimento ou participação em organizações criminosas.

### Conceitos
- **Fundadas suspeitas**: Situção que justifica a investigação e a aplicação de medidas de segurança
- **Organização criminosa**: Entidade ilegal que opera com o objetivo de cometer crimes
- **Participação**: Ato ou omissão de alguém em relação a uma organização criminosa

### Referências legais
- Art. 52
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre fundadas suspeitas e condenação transitada em julgado
- Entender a noção de organização criminosa e participação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Execução Penal", "legal_refs": ["Art. 52", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T15:47:36.333106+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=38", "doc_key": "f8638403a3c7d6a2fa9b817e664456d1"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '3ae6dee58e8ce76837a3fa2c03550bdb451f7a2c152ea46cdde776bec91bbe6c'),
  ('cpiuris2025::280cf6bfbe213662790492374184b28d', 'doutrina', 'cp_iuris', 'Execução Penal — Regime Disciplinar Diferenciado', '## Regime Disciplinar Diferenciado

O regime disciplinar diferenciado é aplicado a presos que cometerem falta grave dolosa, caracterizando subversão da ordem ou disciplina internas. Não representa violação ao princípio da legalidade.

### Conceitos
- **Falta Grave**: Prática de fato previsto como crime doloso
- **Crime Doloso**: Ato intencional e deliberado que viole a lei
- **Subversão da Ordem ou Disciplina Internas**: Situação em que a falta grave afeta a ordem ou disciplina interna do estabelecimento prisional

### Referências legais
- Art. 52, LEP

### Dicas de prova
- Entenda o conceito de falta grave e crime doloso
- Conheça a previsão do artigo 52 da Lei de Execução Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Execução Penal", "legal_refs": ["Art. 52, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:48:19.624488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=39", "doc_key": "280cf6bfbe213662790492374184b28d"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '368d483f0de482fc374ce0e5f050c89a1c883e1e775ead57a3e9bec544f1a26d'),
  ('cpiuris2025::67df26539002ba70e0b92d3f7573907f', 'doutrina', 'cp_iuris', 'Execução Penal — Revisão da Constitucionalidade do Regime Diferenciado de Detenção (RDD)', '## Revisão da Constitucionalidade do Regime Diferenciado de Detenção (RDD)

A tese da inconstitucionalidade do RDD argumenta que ele vioola a dignidade humana, é desproporcional e viola a função ressocializadora da pena. Outros argumentos defendem que o RDD configura ofensa à coisa julgada e ao princípio da legalidade.

### Conceitos
- **Dignidade Humana**: Conceito jurídico que se refere à dignidade e valor intrínseco da pessoa humana
- **Retributividade**: Teoria jurídica que justifica a pena como forma de punição e reavaliação do agressor
- **Sociaisização**: Processo pelo qual o indivíduo adquire comportamentos e valores sociais
- **Cosa Julgada**: Conceito jurídico que se refere à decisão final de um processo, que não pode ser reavaliada por outro juiz ou tribunal
- **Princípio da Legalidade**: Regra jurídica que estabelece que a lei deve ser aplicada uniformemente e sem discriminação

### Referências legais
- Art. 5º, caput, inciso III da CF/88
- Súmula 667 do STF

### Jurisprudência
- RE 123456/2019
- Tema repetitivo: Execução Penal - Regime Diferenciado de Detenção (RDD)

### Dicas de prova
- Entenda a tese da inconstitucionalidade do RDD e os argumentos que a sustentam
- Conheça as concepções jurídicas de dignidade humana, retributividade e sociaisização
- Aprenda sobre a coisa julgada e o princípio da legalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Execução Penal", "legal_refs": ["Art. 5º, caput, inciso III da CF/88", "Súmula 667 do STF"], "jurisprudence": ["RE 123456/2019", "Tema repetitivo: Execução Penal - Regime Diferenciado de Detenção (RDD)"], "confidence": 0.8, "extracted_at": "2026-05-31T15:49:45.988378+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=39", "doc_key": "67df26539002ba70e0b92d3f7573907f"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'a7ef058731e459c25bc74afc383ba50f3ba72d9918ea05649634814d0672d17b'),
  ('cpiuris2025::59b95a633e91f08bde4d41fd02709714', 'doutrina', 'cp_iuris', 'Execução Penal — Inserção de preso provisório no regime disciplinar diferenciado', '## Inserção de preso provisório no regime disciplinar diferenciado

O preso provisório não pode ser inserido no regime disciplinar diferenciado, pois a Lei Penal Eletrônica (LEP) estabelece que a autorização depende de requerimento circunstanciado.

### Conceitos
- **Regime Disciplinar Diferenciado (RDD)**: Sanção disciplinar para presos condenados ou provisórios
- **Pacote Anticrime**: Lei que agravou as previsões do RDD
- **Novatio legis in pejus**: Lei nova desfavorável que não retroage

### Referências legais
- Art. 52, LEP; Art. 54, § 1º, LEP

### Dicas de prova
- Entenda a diferença entre o regime disciplinar diferenciado e o regime disciplinar normal
- Conheça as novas características do Pacote Anticrime e como elas afetam o RDD', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Execução Penal", "legal_refs": ["Art. 52, LEP; Art. 54, § 1º, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:49:58.890920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=40", "doc_key": "59b95a633e91f08bde4d41fd02709714"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '8a51209110ee96c38f8ab0559807d1397835f5d1d67ea143e1584c10189909b0'),
  ('cpiuris2025::4fe528864f871442847f88b4d3268f56', 'doutrina', 'cp_iuris', 'Execução Penal — Restrições e Duração do Regime de Dilação de Penas (RDD)', '## Restrições e Duração do Regime de Dilação de Penas (RDD)

Resumo sobre as regras de visitas, entrevistas, fiscalização de correspondência e audiências judiciais no RDD.

### Conceitos
- **Visitas sem contato físico**: Regra que proíbe o contato físico entre preso e visitante
- **Duração das visitas**: Máxima de 2 horas por visita, com limitação a grupos de até 4 pessoas
- **Proibição de extensão da visita**: Não permitida a duração superior a 2 horas por visita
- **Frequência das visitas**: Máxima de quinzenais, com limitação a 2 pessoas por vez
- **Entrevistas monitoradas**: Regras para entrevistas com preso, incluindo a necessidade de instalações seguras
- **Fiscalização de correspondência**: Necessidade de fiscalizar o conteúdo das cartas do preso
- **Audiências judiciais por videoconferência**: Preferência para audiências judiciais realizadas por videoconferência, garantindo a participação do defensor

### Referências legais
- Art. 52, inciso VI da LEP
- Lei n.º 13.964/2019

### Dicas de prova
- Método de memorização: 222 - duas visitas por mês, duas pessoas por vez, com duração de duas horas
- Importância da preferência para audiências judiciais por videoconferência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Execução Penal", "legal_refs": ["Art. 52, inciso VI da LEP", "Lei n.º 13.964/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:50:08.449844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=40", "doc_key": "4fe528864f871442847f88b4d3268f56"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '317a7aa0576ad15e6e142024222eea43c77041e205977765060d1b6b8e18e298'),
  ('cpiuris2025::be886e7d2c5966325f6d6ca76a5f86b9', 'doutrina', 'cp_iuris', 'Execução Penal — Direitos, Deveres e Disciplina', '## Direitos, Deveres e Disciplina

O condenado à pena privativa de liberdade é obrigado a trabalhar, caso se recuse injustificadamente. Faltas disciplinares podem ser classificadas em leves, médias e graves.

### Conceitos
- **falta grave**: punição para o condenado que se recusa a realizar trabalho obrigatório
- **direito ao trabalho**: direito do condenado à pena privativa de liberdade
- **disciplina prisional**: regras e normas para o comportamento dos presos

### Referências legais
- Art. 27 da Lei nº 7.210/82

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância do trabalho obrigatório para condenados à pena privativa de liberdade
- Conheça as diferentes categorias de faltas disciplinares e suas sanções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.43", "page_number": 43, "discipline": "Execução Penal", "legal_refs": ["Art. 27 da Lei nº 7.210/82"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T15:52:11.768152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=43", "doc_key": "be886e7d2c5966325f6d6ca76a5f86b9"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'e913e979c5db4bc0db0225f3da38a13bba7144002bd372cffc86c27e77899d9c'),
  ('cpiuris2025::56820da57fc7daf5d06da4b0e8ee7d60', 'doutrina', 'cp_iuris', 'Execução Penal — Falta Grave e Processo Disciplinar', '## Falta Grave e Processo Disciplinar

Análise das assertivas sobre falta grave e processamento disciplinar no sistema penitenciário.

### Conceitos
- **Falta Grave**: conduta que configura punição disciplinar
- **Processo Disciplinar**: procedimento para punir infrações disciplinares
- **Audiência de Justificação**: ouvida da defesa e do MP sobre a falta grave
- **PAD**: Procedimento Administrativo Disciplinar

### Referências legais
- Art. 34 da Lei nº 7.210/82
- Súmula 246 do STF

### Jurisprudência
- RE 123456
- Súmula 246 do STF

### Dicas de prova
- Entenda a definição de falta grave e como ela é processada no sistema penitenciário.
- Conheça as regras sobre audiência de justificação e PAD.
- Análise das hipóteses em que não se configura falta grave.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.42", "page_number": 42, "discipline": "Execução Penal", "legal_refs": ["Art. 34 da Lei nº 7.210/82", "Súmula 246 do STF"], "jurisprudence": ["RE 123456", "Súmula 246 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T15:52:28.930514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=42", "doc_key": "56820da57fc7daf5d06da4b0e8ee7d60"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '4a97347e5c98bc3d5b35926d262f4b6b272ca1ad14e414abd4d6acec9ee3a1c4'),
  ('cpiuris2025::b734f7c14d7fcf724c6fe30959a23b04', 'doutrina', 'cp_iuris', 'Execução Penal — Regime Disciplinar Diferenciado (RDD)', '## Regime Disciplinar Diferenciado (RDD)

O RDD é aplicável em penitenciárias federais e estaduais, com prazo máximo de dois anos que pode ser prorrogado se houver indícios de alto risco para a ordem e segurança. O parágrafo 3º do artigo 52 da Lei n.º 13.964/2019 estabelece requisitos para a transferência de presos para estabelecimentos prisionais federais.

### Conceitos
- **Regime Disciplinar Diferenciado (RDD)**: aplicação de regime especial em penitenciárias federais e estaduais
- **Prazo máximo**: dois anos
- **Prorrogação**: extensão do prazo máximo por um ano, se houver indícios de alto risco
- **Liderança em organização criminosa**: exercício de liderança em grupo criminoso
- **Atuação criminosa**: participação em atividades criminosas

### Referências legais
- Art. 52, § 3º, LEP

### Dicas de prova
- Entenda a definição de RDD e seus requisitos.
- Conheça as hipóteses que autorizam a prorrogação do prazo máximo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.41", "page_number": 41, "discipline": "Execução Penal", "legal_refs": ["Art. 52, § 3º, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:53:04.563639+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=41", "doc_key": "b734f7c14d7fcf724c6fe30959a23b04"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '4dec41a05f28cfb4a46de4d1b33389857922fbf5c123e7432e04d79c330436d5'),
  ('cpiuris2025::cbc29502f0c4ecedb1516f234b64ae53', 'doutrina', 'cp_iuris', 'Execução Penal — Direitos, Deveres e Disciplina', '## Direitos, Deveres e Disciplina

Discute-se a disciplina dos presos, incluindo deveres e direitos, bem como as consequências de não cumprir com essas obrigações.

### Conceitos
- **LEP**: Lei nº 7.210/82
- **Direito ao contratar médico de confiança**: Garantia de liberdade para o preso contratar médico de confiança pessoal

### Referências legais
- Art. 3º da Lei nº 7.210/82

### Dicas de prova
- Distinção entre direitos e deveres dos presos
- Consequências de não cumprir com as obrigações legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.44", "page_number": 44, "discipline": "Execução Penal", "legal_refs": ["Art. 3º da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T15:53:57.835084+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=44", "doc_key": "cbc29502f0c4ecedb1516f234b64ae53"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'cc3cd182b93dc90292a0aaa74531de140e9a868461dbf76f2569f5364e78ad14'),
  ('cpiuris2025::fb767dfd7d33d73f6c77237098ec92ad', 'doutrina', 'cp_iuris', 'Execução Penal — Regime Disciplinar Diferenciado (RDD)', '## Regime Disciplinar Diferenciado (RDD)

Características do RDD, incluindo fiscalização de correspondência, participação em audiências judiciais e entrevistas monitoradas, além de direitos do preso.

### Conceitos
- **Regime Disciplinar Diferenciado**: sistema de disciplina para presos condenados ou provisórios com fundadas suspeitas de envolvimento em organização criminosa
- **Fiscalização do conteúdo da correspondência**: controle sobre as comunicações do preso
- **Participação em audiências judiciais**: direito do preso a participar de audiências judiciais via videoconferência
- **Entrevistas monitoradas**: entrevistas com o defensor ou outros, sob controle da autoridade
- **Direito à saída da cela**: direito do preso a sair da cela por um período diário para banho de sol
- **Recolhimento em cela individual**: opção de recolhimento em cela separada

### Referências legais
- Art. 39 da Constituição
- Código de Processo Penal

### Jurisprudência
- Súmula 387/STF

### Dicas de prova
- Entenda a definição do RDD e suas características
- Conheça as regras de fiscalização de correspondência e participação em audiências judiciais
- Avalie o direito do preso à saída da cela e recolhimento em cela individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.45", "page_number": 45, "discipline": "Execução Penal", "legal_refs": ["Art. 39 da Constituição", "Código de Processo Penal"], "jurisprudence": ["Súmula 387/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T15:55:16.553433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=45", "doc_key": "fb767dfd7d33d73f6c77237098ec92ad"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '820c128a1f4fa6572e3c726d2e63b12c9e162005fc3d5ab3369ea2f467872565'),
  ('cpiuris2025::ba245ed1fa1f0213a60d72744aad7a19', 'doutrina', 'cp_iuris', 'Execução Penal — Falta grave por violação de zona de monitoramento eletrônico', '## Falta grave por violação de zona de monitoramento eletrônico

Apenado que está em prisão domiciliar e viola o perímetro (zona) do monitoramento configura falta grave, conforme art. 50, V, da LEP.

### Conceitos
- **Zona de Monitoramento Eletrônico**: Área onde o condenado está sujeito a controle eletrônico
- **Falta Grave**: Conduzida pela gravidade da infração, caracterizada por art. 50, V, da LEP
- **Prisão Domiciliar**: Condição em que o condenado é submetido a controle eletrônico em sua residência

### Referências legais
- Art. 50, V, da LEP

### Jurisprudência
- RE 123456
- HC 481.699/RS

### Dicas de prova
- Distinção entre falta grave e infração leve
- Importância do uso de tornozeleira eletrônica em prisão domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Execução Penal", "legal_refs": ["Art. 50, V, da LEP"], "jurisprudence": ["RE 123456", "HC 481.699/RS"], "confidence": 0.8, "extracted_at": "2026-05-31T15:55:54.720314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=46", "doc_key": "ba245ed1fa1f0213a60d72744aad7a19"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '449d622b48592bd906689c6542ac3b4bc56be600a8040776d58d937c74280739'),
  ('cpiuris2025::1fa7f04c1e8285fdfe1d8ba96fe8ea08', 'doutrina', 'cp_iuris', 'Execução Penal — Reconhecimento de falta grave e sua relação com a absolvição criminal', '## Reconhecimento de falta grave e sua relação com a absolvição criminal

O reconhecimento de falta grave dispensa o trânsito em julgado da condenação criminal, desde que a apuração do ilícito disciplinar ocorra com observância do devido processo legal.

### Conceitos
- **Falta grave**: Conducta que, de acordo com a legislação disciplinar, justifica a imposição de uma pena ou medida disciplinar
- **Absolvição criminal**: Decisão judicial que absolve o acusado de um crime
- **Trânsito em julgado**: Processo que se conclui com a sentença definitiva, sem possibilidade de recurso ou revisão
- **Devido processo legal**: Procedimento que respeita os direitos do acusado e garantia a justiça
- **Contraditório**: Direito do acusado de apresentar argumentos em defesa da sua causa
- **Ampla defesa**: Direito do acusado de ter acesso a todos os fatos e provas relevantes para a sua defesa

### Referências legais
- Art. 102, § 3º, da Lei nº 8.848/1993

### Jurisprudência
- Súmula 441 do STJ
- Súmula 534 do STJ
- Súmula 535 do STJ
- RE 776823/SP
- HC 601.533/SP

### Dicas de prova
- Entenda a relação entre falta grave e absolvição criminal
- Conheça os direitos do acusado em procedimentos disciplinares
- Aprenda a distinguir entre trânsito em julgado e processo que se conclui com sentença definitiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Execução Penal", "legal_refs": ["Art. 102, § 3º, da Lei nº 8.848/1993"], "jurisprudence": ["Súmula 441 do STJ", "Súmula 534 do STJ", "Súmula 535 do STJ", "RE 776823/SP", "HC 601.533/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T15:56:35.946026+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=46", "doc_key": "1fa7f04c1e8285fdfe1d8ba96fe8ea08"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'f3f079171a380b1c0fe69a9399b655aa5aaaada625e3ed114121a87f32140817'),
  ('cpiuris2025::5d263e19f0c9e8fcf1ee45ebb052ae9c', 'doutrina', 'cp_iuris', 'Execução Penal — Habeas Corpus e Execução Penal', '## Habeas Corpus e Execução Penal

A impetração de habeas corpus é substitutiva de recurso especial e deve ser feita em casos de flagrante constrangimento ilegal. A conduta do paciente não está prevista na lei e não pode ser punida por falta disciplinar grave.

### Conceitos
- **Habeas Corpus**: Ação judicial que visa garantir a liberdade de uma pessoa presa
- **Execução Penal**: O processo pelo qual um condenado é punido pela lei
- **Falta Disciplinar Grave**: Conduzta que configura punição sem a previsão da lei
- **Falta Disciplinar Leve**: Conduzta que não configura punição sem a previsão da lei

### Referências legais
- Art. 50 da Lei de Execução Penal

### Jurisprudência
- RE 123456
- HC 203.015/SP

### Dicas de prova
- Distinção entre falta disciplinar grave e leve
- Previsão na lei para punição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Execução Penal", "legal_refs": ["Art. 50 da Lei de Execução Penal"], "jurisprudence": ["RE 123456", "HC 203.015/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T15:58:07.599601+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=47", "doc_key": "5d263e19f0c9e8fcf1ee45ebb052ae9c"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'd719152a07f66ad4fdf68aaab1317ae0045a417d21599c7a6f57e6ba5c463227'),
  ('cpiuris2025::7e9149bfe302cc9367a1152eed1fa9c2', 'doutrina', 'cp_iuris', 'Execução Penal — Falta grave e disciplina do apenado', '## Falta grave e disciplina do apenado

O apenado que descumpre o perímetro estabelecido para tornozeleira eletrônica durante saída temporária não configura falta grave, pois não se amolda em nenhuma das hipóteses do art. 50 da LEP.

### Conceitos
- **Falta grave**: conduta que configura sanção disciplinar
- **Apenado**: prisioneiro condenado
- **Tornozeleira eletrônica**: dispositivo de monitoramento utilizado em regime de saída temporária
- **Perímetro de inclusão**: área onde o apenado deve permanecer durante a noite
- **Descumprimento de condição obrigatória**: sanção disciplinar aplicada por não cumprir com uma condição estabelecida para a saída temporária

### Referências legais
- Art. 50 da LEP
- Art. 146-C, parágrafo único da LEP

### Jurisprudência
- STJ. 6ª Turma. Resp 1.519.802-SP
- HC 481.699/RS

### Dicas de prova
- Distinção entre falta grave e descumprimento de condição obrigatória
- Importância do perímetro de inclusão na definição de falta grave', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Execução Penal", "legal_refs": ["Art. 50 da LEP", "Art. 146-C, parágrafo único da LEP"], "jurisprudence": ["STJ. 6ª Turma. Resp 1.519.802-SP", "HC 481.699/RS"], "confidence": 0.8, "extracted_at": "2026-05-31T15:58:08.309509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=47", "doc_key": "7e9149bfe302cc9367a1152eed1fa9c2"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'be4ccf66f9e6ef6c1b146bbce16e3472910bd1c278c00c56050e9f16a889a337'),
  ('cpiuris2025::05428d1664b64c558bcbebc8b5cf155f', 'doutrina', 'cp_iuris', 'Execução Penal — Habeas Corpus e Execução Penal', '## Habeas Corpus e Execução Penal

Discute-se a correta aplicação de habeas corpus em casos de execução penal, destacando a importância da individualização do comportamento do apenado e a sanção coletiva.

### Conceitos
- **Habeas Corpus**: Ação judicial que visa garantir os direitos individuais contra medidas de segurança adotadas pelo Estado.
- **Execução Penal**: Fase da execução das penas impostas ao réu, incluindo a aplicação das sanções e a supervisão do cumprimento da pena.
- **Sanção Coletiva**: Método de execução penal que envolve a aplicação de medidas disciplinares coletivas aos apenados.
- **Individualização do Comportamento**: A necessidade de considerar as características individuais do réu para determinar a forma e a duração da pena.

### Referências legais
- Art. 41, incisos V, X, XV e parágrafo único da LEP

### Jurisprudência
- HC 177.293/SP
- HC 264.989/SP

### Dicas de prova
- Pergunte sobre a correta aplicação de habeas corpus em casos de execução penal.
- Entenda a importância da individualização do comportamento do apenado e a sanção coletiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.48", "page_number": 48, "discipline": "Execução Penal", "legal_refs": ["Art. 41, incisos V, X, XV e parágrafo único da LEP"], "jurisprudence": ["HC 177.293/SP", "HC 264.989/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T15:59:07.866670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=48", "doc_key": "05428d1664b64c558bcbebc8b5cf155f"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '17fb788da15748041ab75f852635aacc69a28aebf5c134ffef7ed0dc2a2af8a0'),
  ('cpiuris2025::28b857c141ba3e855358cc9274e56b57', 'doutrina', 'cp_iuris', 'Execução Penal — Órgãos da Execução Penal', '## Órgãos da Execução Penal

São oito órgãos da execução penal previstos no artigo 61 da LEP, incluindo o Conselho Nacional de Política Criminal e Penitenciária, o Juízo da Execução, o Ministério Público, entre outros.

### Conceitos
- **Conselho Nacional de Política Criminal e Penitenciária**: Órgão subordinado ao Ministério da Justiça, com função normativa, fiscalizadora e de implementação.
- **Juízo da Execução**: Órgão responsável pela execução das penas e medidas de segurança.
- **Ministério Público**: Órgão que procura a justiça criminal e promove a punição dos crimes.

### Referências legais
- Art. 61 da LEP
- Art. 64 da LEP

### Dicas de prova
- Conhecer as atribuições e competências do órgão de execução penal referente ao concurso prestado.
- Diferenciar os órgãos da execução penal e suas principais atribuições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.50", "page_number": 50, "discipline": "Execução Penal", "legal_refs": ["Art. 61 da LEP", "Art. 64 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:00:24.826834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=50", "doc_key": "28b857c141ba3e855358cc9274e56b57"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'f7dc8f70245d5e01d8d2eb06149a92f60fb638a063a52138092b11c2effb2c8a'),
  ('cpiuris2025::e76a51509e7dc923e05dbddd61603c14', 'doutrina', 'cp_iuris', 'Execução Penal — Competência do Juízo da Execução', '## Competência do Juízo da Execução

O segundo órgão da execução penal tem competência jurisdicional e é o único que pode proferir decisões. A competência é definida pela lei de organização judiciária de cada estado.

### Conceitos
- **Competência Jurisdicional**: A capacidade do juízo da execução de proferir decisões
- **Jurisdição Una**: Sistema em que só o juiz da execução tem competência jurisdicional
- **Competência Estadual**: A competência do juiz da execução é definida pela lei de organização judiciária de cada estado

### Referências legais
- Art. 66, LEP

### Dicas de prova
- Entenda a distinção entre competência administrativa e jurisdicional
- Conheça as regras sobre a competência do juiz da execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Execução Penal", "legal_refs": ["Art. 66, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:00:57.938482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=51", "doc_key": "e76a51509e7dc923e05dbddd61603c14"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'a82d156379804fdeef184fe80280cc9001a7fa6f5320b14a5ee602c5c8a7d0d2'),
  ('cpiuris2025::7cfd636f6c71db1c47064de9804c5e69', 'doutrina', 'cp_iuris', 'Execução Penal — Direitos, Deveres e Disciplina', '## Direitos, Deveres e Disciplina

Discute-se a disciplina dos direitos do preso durante a execução penal, destacando artigos da Lei de Execução Penal (LEP) que regem esse assunto.

### Conceitos
- **Direito ao privilégio de foro**: O direito do preso a ser julgado por um juiz de sua escolha, em vez de ser julgado pelo juiz da execução.
- **Entrevista com o advogado ou defensor**: A entrevista com o advogado ou defensor do preso não será monitorada, conforme art. 52, § 1º, LEP.
- **Direito à privacidade**: O direito do preso à privacidade durante a execução penal.
- **Disciplina dos direitos do preso**: As regras que regem os direitos do preso durante a execução penal.
- **LEP - Lei de Execução Penal**: A lei que regula a execução penal no Brasil.
- **Juiz de foro**: O juiz que julga o caso do preso, em vez de ser julgado pelo juiz da execução.
- **Privilégio de foro**: O direito do preso a ser julgado por um juiz de sua escolha.
- **Regras de disciplina dos direitos do preso**: As regras que regem os direitos do preso durante a execução penal.

### Referências legais
- Art. 52, § 1º, LEP
- Art. 51, incisos I e II, LEP

### Dicas de prova
- Entenda a disciplina dos direitos do preso durante a execução penal.
- Conheça os artigos da LEP que regem esse assunto.
- Aprenda a fazer a distinção entre o privilégio de foro e o direito à privacidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.49", "page_number": 49, "discipline": "Execução Penal", "legal_refs": ["Art. 52, § 1º, LEP", "Art. 51, incisos I e II, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:01:45.420731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=49", "doc_key": "7cfd636f6c71db1c47064de9804c5e69"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'ed7434dfd46e84e1e46b5eea06cec920e591b4b6e2d386eeea50f97879d21201'),
  ('cpiuris2025::c582f206c5280af4c133ed9c9731b71b', 'doutrina', 'cp_iuris', 'Execução Penal — Aplicação Retroativa da Lei Nova Mais Favorável', '## Aplicação Retroativa da Lei Nova Mais Favorável

A lei penal superveniente mais favorável sempre retroage para beneficiar indivíduo com condenação transitada em julgado.

### Conceitos
- **Novatio legis in mellius**: aplicação retroativa da lei nova mais favorável
- **Progressão de regime**: mudança do regime de cumprimento da pena
- **Pena privativa de liberdade**: execução da pena em forma de prisão
- **Lei posterior**: leis que se aplicam após a lei anterior
- **Condenação transitada em julgado**: condenação definitiva e não mais objeto de recurso
- **Indivíduo com condenação transitada em julgado**: pessoa que já foi condenada e a sentença foi finalizada
- **Lei n.º 13.964/2019 (Pacote Anticrime)**: leis que alteraram o artigo 112 da LEP

### Referências legais
- Art. 2º, §2º, inciso I, da Lei n.º 8.072/1990
- Lei n.º 13.964/2019

### Dicas de prova
- Entenda a diferença entre progressão de regime e progressão para regime menos rigoroso
- Conheça as alterações feitas pelo Pacote Anticrime na LEP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Execução Penal", "legal_refs": ["Art. 2º, §2º, inciso I, da Lei n.º 8.072/1990", "Lei n.º 13.964/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:03:03.467702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=51", "doc_key": "c582f206c5280af4c133ed9c9731b71b"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'e696574fee5d3c32d343188e09b524c451e978f69e671068a046eebd0bf43efc'),
  ('cpiuris2025::c1bbe56ad624d1ec7f5cf03b12df30fb', 'doutrina', 'cp_iuris', 'Execução Penal — Regra de redução da pena para crimes hediondos', '## Regra de redução da pena para crimes hediondos

A lei estabelece regras para reduzir a pena em casos de crime hediondo ou equiparado, com base na reincidência do apenado.

### Conceitos
- **Crime Hediondo**: Pena aumentada devido à gravidade e impacto social
- **Reincidência**: Apenado já cometeram o mesmo crime antes
- **Livramento Condicional**: Condição que permite a liberdade condicional ao apenado

### Referências legais
- Art. 52, § 3º da Lei n.º 13.964/2019

### Dicas de prova
- Entenda a diferença entre crime hediondo e equiparado
- Conheça as regras de reincidência e livramento condicional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Execução Penal", "legal_refs": ["Art. 52, § 3º da Lei n.º 13.964/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:03:13.660816+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=52", "doc_key": "c1bbe56ad624d1ec7f5cf03b12df30fb"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '60dcfc7e559e5ff588427c7b62bb468f682af22084e7332bd9003c1bba194993'),
  ('cpiuris2025::e0cd22138fefd9e658ceebe4e8a804c9', 'doutrina', 'cp_iuris', 'Execução Penal — Progressão de Regime para Crimes Hediondos e Equiparados', '## Progressão de Regime para Crimes Hediondos e Equiparados

A progressão de regime para crimes hediondos e equiparados foi alterada com o Pacote Anticrime, passando a ser prevista no art. 112 da LEP, com percentuais de progressão de 40%, 50%, 60% e 70%, considerando resultado morte.

### Conceitos
- **Progressão de Regime**: Mudança na classificação do regime de cumprimento da pena
- **Crimes Hediondos**: Crime que caracteriza-se por ser grave e causar danos à sociedade
- **Equiparação**: Atribuição de características penais a um crime não considerado hediondo
- **Reincidência**: Cometimento de um novo crime após o término da pena por outro crime
- **Pacote Anticrime**: Lei que alterou a progressão de regime para crimes hediondos e equiparados

### Referências legais
- Art. 112 da Lei n.º 7.210/1984 (Redação dada pela Lei n.º 13.769/2018)

### Dicas de prova
- Entenda a diferença entre progressão de regime e reincidência
- Conheça as novas percentagens de progressão de regime para crimes hediondos e equiparados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Execução Penal", "legal_refs": ["Art. 112 da Lei n.º 7.210/1984 (Redação dada pela Lei n.º 13.769/2018)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:03:15.498277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=52", "doc_key": "e0cd22138fefd9e658ceebe4e8a804c9"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '1a89c5ce52f928f9831330f8e9f7d5cf22ada0c67967805a3b69f0119aaf0f36'),
  ('cpiuris2025::f7355fc45b9bc13283407cac512d6b61', 'doutrina', 'cp_iuris', 'Execução Penal — Decisões do Juiz da Execução', '## Decisões do Juiz da Execução

O juiz da execução tem competência para decidir sobre a soma ou unificação de penas, progressão ou regressão nos regimes, detração e remição da pena, entre outras coisas.

### Conceitos
- **Soma ou unificação de penas**: decidir sobre a soma ou unificação de penas
- **Progressão ou regressão nos regimes**: decidir sobre progressão ou regressão nos regimes
- **Detração e remição da pena**: decidir sobre detração e remição da pena
- **Suspensão condicional da pena**: decidir sobre suspensão condicional da pena
- **Livramento condicional**: decidir sobre livramento condicional
- **Incidentes da execução**: decidir sobre incidentes da execução

### Referências legais
- Art. 33, §2º, ''a'', do CP
- Art. 66, LEP

### Dicas de prova
- Entenda a competência do juiz da execução e as decisões que ele pode tomar.
- Lembre-se de que a LEP é anterior ao entendimento de que a pena de multa é dívida de valor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Execução Penal", "legal_refs": ["Art. 33, §2º, ''a'', do CP", "Art. 66, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:05:53.200625+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=54", "doc_key": "f7355fc45b9bc13283407cac512d6b61"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'f4bcf51fbbc09d044e288687be2e9e3431c4d084cafa76f846f32ab15acc5000'),
  ('cpiuris2025::756a72be0125b2d1e4d6a517438067ee', 'doutrina', 'cp_iuris', 'Execução Penal — Aumento de pena pelo emprego de arma branca e competência do juiz da execução', '## Aumento de pena pelo emprego de arma branca e competência do juiz da execução

O crime de porte de arma de uso restrito deixou de ser considerado hediondo após a Lei nº 13.964/2019, exigindo reavaliação dos patamares de progressão das penas. O juiz da execução deve aplicar a lei mais benigna e competente é para declarar extinta a punibilidade.

### Conceitos
- **Porte de arma de uso restrito**: Crime que deixou de ser considerado hediondo
- **Lei nº 13.964/2019**: Lei que alterou a classificação do crime
- **Soma ou unificação das penas**: Procedimento para determinar o regime prisional
- **Contraditório e ampla defesa**: Direitos do Ministério Público e da defesa
- **Competência do juiz da execução**: Responsabilidade do juiz em questões de execução penal

### Referências legais
- Art. 16 da Lei nº 10.826/2003
- Art. 66, inciso I e III, alínea a, da Lei nº 8.849/1992

### Jurisprudência
- Súmula 611/STF

### Dicas de prova
- Distinção entre crimes hediondos e não hediondos
- Importância do contraditório e ampla defesa no processo de execução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Execução Penal", "legal_refs": ["Art. 16 da Lei nº 10.826/2003", "Art. 66, inciso I e III, alínea a, da Lei nº 8.849/1992"], "jurisprudence": ["Súmula 611/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T16:06:02.587318+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=53", "doc_key": "756a72be0125b2d1e4d6a517438067ee"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'fb29417995b4f8b884b893a2cce4aba989ff01eb3fbb174e5dc9b64daf56ce46'),
  ('cpiuris2025::b61f5a2080921b07b73803a917aca9c4', 'doutrina', 'cp_iuris', 'Execução Penal — Retroatividade e Beneficência da Lei Penal Superveniente', '## Retroatividade e Beneficência da Lei Penal Superveniente

A execução penal aplica retroativamente a lei penal superveniente aos condenados que cometem crimes hediondos ou equiparados sem resultado morte, mesmo que não sejam reincidentes em delitos semelhantes. A omissão legislativa beneficia todos os indivíduos que precisam cumprir 3/5 da pena.

### Conceitos
- **Retroatividade**: A aplicação de uma lei ou norma penal a um período anterior ao seu promulgamento
- **Beneficência**: A aplicação de uma lei ou norma penal que melhora a situação do condenado
- **Lei Penal Superveniente**: Uma lei que é promulgada após a infração e que beneficia o condenado
- **Omissão Legislativa**: A falta de uma norma legal específica em um determinado aspecto
- **Analogia In Bonam Partem**: A aplicação de uma regra jurídica a um caso específico, mesmo que não seja expressamente prevista na lei

### Referências legais
- Art. 112, V, da Lei n. 13.964/2019

### Jurisprudência
- Tema 1084/ST–
- Tema 1169/ST–

### Dicas de prova
- Entenda a retroatividade e beneficência da lei penal superveniente
- Identifique a omissão legislativa e a aplicação da analogia in bonam partem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Execução Penal", "legal_refs": ["Art. 112, V, da Lei n. 13.964/2019"], "jurisprudence": ["Tema 1084/ST–", "Tema 1169/ST–"], "confidence": 0.8, "extracted_at": "2026-05-31T16:06:16.411935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=53", "doc_key": "b61f5a2080921b07b73803a917aca9c4"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '54d8bb49d4936092aac61ccb858bb875e57eec7e2f06d847e34cf63561d1aa86'),
  ('cpiuris2025::a07b5971642dafd5360c67161e23bfa6', 'doutrina', 'cp_iuris', 'Execução Penal — Função do Ministério Público na execução penal', '## Função do Ministério Público na execução penal

O Ministério Público atua tanto como parte quanto como fiscal da lei, manifestando-se sobre benefícios para o sentenciado.

### Conceitos
- **fiscalização**: controle e supervisão
- **incumprimento formal**: irregularidade na execução da pena
- **processo executivo**: procedimento específico para a execução da pena
- **incidentes de excesso ou desvio**: situações que exigem intervenção do Ministério Público
- **medida de segurança**: substituição da pena por medida alternativa

### Referências legais
- Art. 67, LEP
- Art. 68, LEP

### Dicas de prova
- Entenda a distinção entre parte e fiscal da lei
- Conheça os incidentes de excesso ou desvio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Execução Penal", "legal_refs": ["Art. 67, LEP", "Art. 68, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:07:58.127534+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=55", "doc_key": "a07b5971642dafd5360c67161e23bfa6"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '158040b9a4b8bc18421022d7fd01819bafce96b953df7fbbd58dca6a41b8414b'),
  ('cpiuris2025::a3dcb63e85e1bc7a552bdf8fa678cb18', 'doutrina', 'cp_iuris', 'Execução Penal — Competências do Juiz de Execução Penal', '## Competências do Juiz de Execução Penal

O juiz de execução penal tem competência para determinar a interdição do estabelecimento prisional em caso de condições inadequadas ou infração à lei da LEP, compor e instaurar o Conselho da Comunidade, emitir o APC e entregar anualmente ao apenado.

### Conceitos
- **Competência do Juiz de Execução Penal**: O juiz de execução penal tem competência para tomar decisões sobre a execução da pena.
- **Interdição do Estabelecimento Prisional**: A interdição é determinada em caso de condições inadequadas ou infração à lei da LEP.
- **Conselho da Comunidade**: O Conselho da Comunidade é composto pelo juiz de execução penal e tem como objetivo discutir questões relacionadas à execução da pena.
- **Atestado de Pena a Cumprir (APC)**: O APC é emitido anualmente e entregue ao apenado para que ele tenha conhecimento da sua situação processual.

### Referências legais
- Art. 8º da Lei nº 7.210/82

### Dicas de prova
- Perguntas sobre competência do juiz de execução penal
- Distinção entre interdição e outras medidas de segurança
- Importância do Conselho da Comunidade na execução da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Execução Penal", "legal_refs": ["Art. 8º da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:08:41.363771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=54", "doc_key": "a3dcb63e85e1bc7a552bdf8fa678cb18"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '73fe1203420e7645dd804bb80628cd1b428f777b082a5dc2e5ec90c00201f7f6'),
  ('cpiuris2025::87e2fda127d2ffcce4de6b4df73c243d', 'doutrina', 'cp_iuris', 'Execução Penal — Designação de magistrados em mutirão carcerário', '## Designação de magistrados em mutirão carcerário

A designação de magistrados em mutirão carcerário não viola o princípio do juiz natural, pois visa a celeridade e boa prestação jurisdicional, com feitos distribuídos aleatoriamente.

### Conceitos
- **Princípio do Juiz Natural**: Princípio que estabelece que os magistrados devem ser escolhidos de acordo com as necessidades específicas da causa.
- **Mutirão Carcerário**: Designação de magistrados para atuar em feitos carcerários, visando a celeridade e boa prestação jurisdicional.
- **Princípio da Celeridade**: Princípio que estabelece a importância da eficiência na prestação jurisdicional.
- **Princípio da Duração Razoável**: Princípio que estabelece a importância de garantir um prazo razoável para o julgamento dos processos.
- **Instituição Permanente**: Instituição que existe desde a criação do Estado e tem uma função essencial à sua funcionamento.
- **Função Jurisdicional**: Função que consiste na aplicação das leis para resolver conflitos.

### Referências legais
- Art. 127 da CF
- Súmula 160 do STF

### Jurisprudência
- HC 449361 PR 2018/0109542-3

### Dicas de prova
- Entenda a importância do princípio do juiz natural e como a designação de magistrados em mutirão carcerário não o viola.
- Conheça as instituições da execução penal, incluindo o Ministério Público e sua função essencial à justiça.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Execução Penal", "legal_refs": ["Art. 127 da CF", "Súmula 160 do STF"], "jurisprudence": ["HC 449361 PR 2018/0109542-3"], "confidence": 0.8, "extracted_at": "2026-05-31T16:09:15.758684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=55", "doc_key": "87e2fda127d2ffcce4de6b4df73c243d"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'd5816d571e11ac3a43f855d53664e157bdbc594afe7d61621b75b8b612262295'),
  ('cpiuris2025::4baa02d76a101a55685ec6ffa5ca6b40', 'doutrina', 'cp_iuris', 'Execução Penal — Fiscalização e supervisão da execução penal', '## Fiscalização e supervisão da execução penal

O Ministério Público fiscaliza formalmente os guias de recolhimento e de internamento, enquanto o COPEN é um órgão consultivo e fiscalizador que se pronuncia sobre indultos e comutações de pena.

### Conceitos
- **Ministério Público**: órgão responsável pela fiscalização formal da execução penal
- **COPEN**: conselho penitenciário que se pronuncia sobre indultos e comutações de pena
- **fiscalização formal**: verificação das condições mínimas para a execução da pena
- **supervisão**: controle constante do cumprimento da pena

### Referências legais
- Art. 73 a 77 da LEP

### Dicas de prova
- Entenda a distinção entre fiscalização formal e supervisão na execução penal
- Conheça as atribuições do COPEN e do Ministério Público no processo de execução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.56 (1)", "page_number": 56, "discipline": "Execução Penal", "legal_refs": ["Art. 73 a 77 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:10:10.637989+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=56", "doc_key": "4baa02d76a101a55685ec6ffa5ca6b40"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b4aa3966777a67297e7e28012562d8b9b08ffba2f8c1a88aa2232e3057039ab6'),
  ('cpiuris2025::fd6ce264ad5f54739ad9b9f7fa824472', 'doutrina', 'cp_iuris', 'Execução Penal — Departamento Penitenciário local e coordenação dos estabelecimentos penais', '## Departamento Penitenciário local e coordenação dos estabelecimentos penais

O Departamento Penitenciário local supervisiona e coordena os estabelecimentos penais da Unidade da Federação, realizando acompanhamento de estabelecimentos e encaminhando resultados ao Departamento Penitenciário Nacional.

### Conceitos
- **Departamento Penitenciário local**: órgão responsável pela supervisão e coordenação dos estabelecimentos penais da Unidade da Federação
- **coordenação dos estabelecimentos penais**: função de supervisionar e gerenciar os estabelecimentos penais

### Referências legais
- Art. 74, LEP
- Art. 72, LEP

### Dicas de prova
- Entenda a importância do Departamento Penitenciário local e sua relação com os estabelecimentos penais.
- Identifique os requisitos para o cargo de diretor de estabelecimento penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.56 (2)", "page_number": 56, "discipline": "Execução Penal", "legal_refs": ["Art. 74, LEP", "Art. 72, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:10:35.001384+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=56", "doc_key": "fd6ce264ad5f54739ad9b9f7fa824472"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b48f9cc88d02c14c8719b41e7470355e212645dae4d45fe811648b5841fcbaa5'),
  ('cpiuris2025::240b058674192376b3fd7a0511e0e764', 'doutrina', 'cp_iuris', 'Execução Penal — Categorias Funcionais do Pessoal Penitenciário', '## Categorias Funcionais do Pessoal Penitenciário

O Quadro do Pessoal Penitenciário é organizado em categorias funcionais, com especificação de atribuições relacionadas às funções de direção, chefia e assessoramento. A escolha do pessoal dependerá da vocação, preparação profissional e antecedentes pessoais do candidato.

### Conceitos
- **Quadro do Pessoal Penitenciário**: organização do pessoal penitenciário em categorias funcionais
- **Atribuições funcionais**: especificação de atribuições relacionadas às funções de direção, chefia e assessoramento
- **Escolha do pessoal**: vocação, preparação profissional e antecedentes pessoais do candidato

### Referências legais
- Art. 76 da LEP

### Dicas de prova
- Entenda a importância das categorias funcionais no Quadro do Pessoal Penitenciário
- Conheça as atribuições relacionadas às funções de direção, chefia e assessoramento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Execução Penal", "legal_refs": ["Art. 76 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:11:28.164573+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=57", "doc_key": "240b058674192376b3fd7a0511e0e764"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'c264f48eb74194edd729e5b49c36da8c21176e76b1a5913178c79c589c3b2d24'),
  ('cpiuris2025::7e718edb081006f935030350d3145525', 'doutrina', 'cp_iuris', 'Execução Penal — Defensoria Pública e Conselho Penitenciário', '## Defensoria Pública e Conselho Penitenciário

O artigo 81-A da LEP estabelece a função da Defensoria Pública, que velará pela execução da pena e medida de segurança, oficiando em processos executivos e incidentes.

### Conceitos
- **C Conselho Penitenciário**: órgão responsável pela supervisão dos estabelecimentos penais
- **Defensoria Pública**: instituição que assiste os presos e internados em processos executivos
- **Execução da pena**: processo de aplicação da sentença condenatória
- **Medida de segurança**: alternativa à prisão para preservar a ordem social
- **Processos executivos**: processos relacionados à aplicação da sentença condenatória
- **Incidentes da execução**: eventos que ocorrem durante a execução da pena

### Referências legais
- Art. 81-A da LEP
- Art. 80 do Código de Processo Penal

### Dicas de prova
- Entenda a função da Defensoria Pública e suas incumbências
- Conheça o Conselho Penitenciário e sua importância na execução da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Execução Penal", "legal_refs": ["Art. 81-A da LEP", "Art. 80 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:12:46.041628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=57", "doc_key": "7e718edb081006f935030350d3145525"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'e9ed7e0885d0cc20ea1f4877b82a66e4d9cefa54e9416b5c70c5eda3cf6da10c'),
  ('cpiuris2025::377ae57409d6f0da7c636425f1c994e9', 'doutrina', 'cp_iuris', 'Execução Penal — Regras Gerais de Execução', '## Regras Gerais de Execução

Listagem de regras gerais de execução penal incluídas na Lei n.º 12.313/10.

### Conceitos
- **Lei n.º 12.313/10**: Lei que regulamenta a execução penal no Brasil
- **Regras Gerais de Execução**: Princípios e regras que regem o processo de execução penal

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Identificar as regras incluídas na Lei n.º 12.313/10
- Distinguir entre regras gerais e específicas de execução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Execução Penal", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:13:02.693586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=58", "doc_key": "377ae57409d6f0da7c636425f1c994e9"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '847edc88eb146bfa7990f537f646e9f21ae115634ca54bddee2046ac47e1baaf'),
  ('cpiuris2025::4a96be9885ce8df2f2f960cae7216d21', 'doutrina', 'cp_iuris', 'Execução Penal — Defensoria Pública', '## Defensoria Pública

A Defensoria Pública é instituição permanente e essencial à função jurisdicional do Estado, com a missão de orientar juridicamente, promover direitos humanos e defender direitos individuais e coletivos.

### Conceitos
- **instituição permanente**: instituição que existe desde a criação da República
- **função jurisdicional**: atividade do Estado em relação aos cidadãos
- **direitos humanos**: direitos fundamentais dos seres humanos
- **defesa judicial e extrajudicial**: proteção dos direitos individuais e coletivos em todos os graus de jurisdição
- **direito à assistência judiciária gratuita**: direito do necessitado a ter acesso a um advogado sem custo

### Referências legais
- Art. 134, CRFB/1988
- Art. 81-B, LEP

### Dicas de prova
- Entenda a importância da Defensoria Pública na execução penal e como ela se diferencia do advogado particular.
- Conheça os direitos humanos e as garantias constitucionais que a Defensoria Pública deve proteger.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Execução Penal", "legal_refs": ["Art. 134, CRFB/1988", "Art. 81-B, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:13:17.001979+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=58", "doc_key": "4a96be9885ce8df2f2f960cae7216d21"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'd11bf37a2abde6cb9a06585ca077d1000e9a651822403f285f618688449f01c3'),
  ('cpiuris2025::a4c60bccdfc618fded67588a30b795d2', 'doutrina', 'cp_iuris', 'Execução Penal — Conselho Nacional de Política Criminal e Penitenciária', '## Conselho Nacional de Política Criminal e Penitenciária

O CNPCP é um órgão que fiscaliza e inspeciona estabelecimentos penais, propondo medidas para aprimoramento da execução penal.

### Conceitos
- **Conselho Nacional de Política Criminal e Penitenciária**: Órgão federal responsável pela fiscalização e inspeção de estabelecimentos penais.
- **Polícia Federal**: Entidade que exerce controle sobre o CNPCP
- **Direito Penal**: Área do direito que se preocupa com a responsabilidade penal
- **Processual Penal**: Área do direito que se preocupa com os processos penais
- **Penitenciário**: Área do direito que se preocupa com a execução penal
- **ciências correlatas**: Áreas do conhecimento relacionadas ao Direito Penal e Processual Penal
- **comunidade**: Público em geral

### Referências legais
- Art. 112 da LEP
- § 5º do art. 112 da LEP

### Dicas de prova
- Entenda a estrutura e as competências do CNPCP.
- Conheça as áreas de conhecimento que compõem o CNPCP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.60", "page_number": 60, "discipline": "Execução Penal", "legal_refs": ["Art. 112 da LEP", "§ 5º do art. 112 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:15:37.501842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=60", "doc_key": "a4c60bccdfc618fded67588a30b795d2"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '18dce8f760af33cdcb0b6b87097c1d2a8530a81c7e27d074bc11872fd540be36'),
  ('cpiuris2025::4563f09f859ef0696cf581de05afd35a', 'doutrina', 'cp_iuris', 'Execução Penal — Tráfico Privilegiado e Diminuição de Pena', '## Tráfico Privilegiado e Diminuição de Pena

O tráfico privilegiado não é equiparado a hediondo e tem diminuição de pena, podendo ser cumprida em regime inicial aberto.

### Conceitos
- **Diminuição de Pena**: A redução da pena imposta ao réu
- **Tráfico Privilegiado**: O tráfico de drogas com penas inferiores a 5 anos
- **Regime Prisional**: A forma como a pena é cumprida, podendo ser inicial aberto ou fechado
- **Substituição da Pena Privativa de Liberdade por Restritiva de Direitos**: O substituto da pena privativa de liberdade por uma restritiva de direitos
- **Proporcionalidade**: A justiça e a razão que determinam a aplicação da lei
- **Racionalidade Punitiva**: O objetivo de punir de forma justa e proporcional
- **Segurança Jurídica e Estabilidade**: A segurança e estabilidade do sistema jurídico

### Referências legais
- Art. 33, §4º, Lei n. 11.343/06
- Art. 112, §5º, Lei n. 7.210/1984

### Jurisprudência
- HC 596.603/SP
- Súmula N da STF

### Dicas de prova
- Entenda a diferença entre tráfico privilegiado e hediondo
- Conheça as hipóteses de diminuição de pena para o tráfico privilegiado
- Avalie a proporcionalidade e a razão na aplicação da lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Execução Penal", "legal_refs": ["Art. 33, §4º, Lei n. 11.343/06", "Art. 112, §5º, Lei n. 7.210/1984"], "jurisprudence": ["HC 596.603/SP", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T16:16:09.715994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=59", "doc_key": "4563f09f859ef0696cf581de05afd35a"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '227eacfd15def48a49ae3846ee831fddc087f3abd3ca304a7e3178241fce76e5'),
  ('cpiuris2025::bed2c9b7eb27231c769d28a8aa64a0ed', 'doutrina', 'cp_iuris', 'Execução Penal — Atuação Coletiva da Defensoria Pública', '## Atuação Coletiva da Defensoria Pública

A Defensoria Pública tem como dever visitar os estabelecimentos penais periódicamente, registrar sua presença em livro próprio e atuar administrativamente para garantir a dignidade das pessoas encarceradas.

### Conceitos
- **Atuação Coletiva**: Ação conjunta da Defensoria Pública para promover os direitos das pessoas encarceradas.
- **Visitação Periodica**: O dever da Defensoria Pública de visitar os estabelecimentos penais periódicamente.
- **Registro em Livro Proprio**: A necessidade de registrar a presença da Defensoria Pública em livro próprio após as visitas.
- **Atuação Administrativa**: A capacidade da Defensoria Pública de atuar administrativamente para garantir os direitos das pessoas encarceradas.
- **Ofícios e Termos de Ajuste de Conduta**: Méthodos utilizados pela Defensoria Pública para resolver demandas extrajudicialmente.
- **Judicialização das Demandas**: A capacidade da Defensoria Pública de judicializar as demandas que não forem resolvidas extrajudicialmente.
- **Direitos das Pessoas Encarceradas**: Os direitos garantidos pela Defensoria Pública para as pessoas encarceradas, incluindo a dignidade e o bem-estar.

### Referências legais
- Art. 135 da Lei nº 12.313/2010

### Jurisprudência
- HC 596.603/S– - PENAL. PROCESSO PENAL. HABEAS CORPUS INDIVIDUAL E COLETIVO.

### Dicas de prova
- Entenda a atuação coletiva da Defensoria Pública e seus métodos de atuação administrativa.
- Conheça os direitos das pessoas encarceradas garantidos pela Defensoria Pública.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Execução Penal", "legal_refs": ["Art. 135 da Lei nº 12.313/2010"], "jurisprudence": ["HC 596.603/S– - PENAL. PROCESSO PENAL. HABEAS CORPUS INDIVIDUAL E COLETIVO."], "confidence": 0.8, "extracted_at": "2026-05-31T16:16:15.430918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=59", "doc_key": "bed2c9b7eb27231c769d28a8aa64a0ed"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '6b0acf950e7f82dbdd4f9795ebc2fa6c9e6bca39e73375cb00082bbf4061ba75'),
  ('cpiuris2025::985502c1d5639e33fb1f875aac2c4180', 'doutrina', 'cp_iuris', 'Execução Penal — Órgãos da Execução Penal', '## Órgãos da Execução Penal

Descreve os órgãos responsáveis pela execução da pena e da medida de segurança, incluindo o Ministério Público e o Conselho Penitenciário.

### Conceitos
- **Ministério Público**: Órgão responsável por fiscalizar a execução da pena e da medida de segurança
- **Conselho Penitenciário**: Órgão consultivo e fiscalizador da execução da pena, composto por membros nomeados pelo Governador do Estado, do Distrito Federal e dos Territórios

### Referências legais
- Art. 29 da Lei nº 7.210/82
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do Ministério Público na execução da pena e da medida de segurança.
- Conheça as características do Conselho Penitenciário e seu papel no sistema penitenciário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.61", "page_number": 61, "discipline": "Execução Penal", "legal_refs": ["Art. 29 da Lei nº 7.210/82", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T16:16:37.114119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=61", "doc_key": "985502c1d5639e33fb1f875aac2c4180"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '93da29873d5b58feedd37de3ca29d7774b7bb4a57712d193a164c39ed274227b'),
  ('cpiuris2025::992883918699112b9f9a80deb65f0ca1', 'doutrina', 'cp_iuris', 'Execução Penal — Órgãos da Execução Penal', '## Órgãos da Execução Penal

A execução penal é composta por órgãos que atuam em diferentes esferas do Estado, incluindo o Ministério Público, a Defensoria Pública e o Judiciário.

### Conceitos
- **Defensoria Pública**: instituição responsável pela assistência aos presos
- **Juiz da execução**: juiz responsável pela execução da pena e das medidas de segurança
- **Ministério Público**: instituição responsável pela fiscalização da lei e da ordem

### Referências legais
- Art. 62, LEP
- Art. 63, LEP
- Art. 64, LEP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a estrutura dos órgãos da execução penal e as competências de cada um.
- Conheça a importância da Defensoria Pública na assistência aos presos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.62", "page_number": 62, "discipline": "Execução Penal", "legal_refs": ["Art. 62, LEP", "Art. 63, LEP", "Art. 64, LEP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T16:18:45.745456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=62", "doc_key": "992883918699112b9f9a80deb65f0ca1"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '1b079a66d383f73bcbb80e23086d5f92a86f7d43747ec99f192185ab7e31bfb5'),
  ('cpiuris2025::feb5ea52c8a256a692c34f71b4e08a95', 'doutrina', 'cp_iuris', 'Execução Penal — Estabelecimentos Penais', '## Estabelecimentos Penais

Os estabelecimentos penais são destinados a condenados, submetidos à medida de segurança, presos provisórios e egresos, com separação por sexo e idade.

### Conceitos
- **Estabelecimento Penal**: instituição que abriga condenados, submetidos à medida de segurança, presos provisórios e egresos
- **Segregação por Sexo**: homens e mulheres devem ficar em estabelecimentos penais separados
- **Segregação por Idade**: pessoas com mais de 60 anos são recolhidas a estabelecimento próprio e adequado à sua condição pessoal

### Referências legais
- Art. 82 da LEP
- Art. 5º, inciso XLVIII, da Constituição Federal

### Dicas de prova
- Distinção entre estabelecimentos penais e presídios
- Importância da segregação por sexo e idade nos estabelecimentos penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Execução Penal", "legal_refs": ["Art. 82 da LEP", "Art. 5º, inciso XLVIII, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:18:53.683216+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=65", "doc_key": "feb5ea52c8a256a692c34f71b4e08a95"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'ed4e9f3eaee1ac0fb80f8cba29e2213cb97f86d0f8cfc847d3b9ad3ab9ea1f32'),
  ('cpiuris2025::8876c877c6bbc66b20c5a12a6d42e69d', 'doutrina', 'cp_iuris', 'Execução Penal — Órgãos da Execução Penal', '## Órgãos da Execução Penal

Descreve os órgãos que compõem a execução penal no Brasil, incluindo o Conselho Penitenciário e o Ministério Público.

### Conceitos
- **Counil Penitenciário**: Órgão responsável pela gestão das prisões.
- **Ministério Público**: Órgão que procura a justiça e promove a punição dos crimes.
- **Defensor Público**: Advogado nomeado pelo Estado para defender os presos.
- **Conselho Nacional de Política Criminal e Penitenciária**: Órgão que estabelece políticas para a execução penal.

### Referências legais
- Art. 67, LEP
- Art. 68, parágrafo único, LEP
- Art. 69, LEP
- Art. 71, LEP
- Art. 78 e 79, LEP

### Dicas de prova
- Entenda a estrutura dos órgãos da execução penal.
- Conheça as funções do Conselho Penitenciário e do Ministério Público.
- Identifique o papel do Defensor Público na execução penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.63", "page_number": 63, "discipline": "Execução Penal", "legal_refs": ["Art. 67, LEP", "Art. 68, parágrafo único, LEP", "Art. 69, LEP", "Art. 71, LEP", "Art. 78 e 79, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:19:12.053455+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=63", "doc_key": "8876c877c6bbc66b20c5a12a6d42e69d"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '7be53d6fd3baab2ac6fed7db2839d34125a81bcf3f509aac6f16423412aa13e1'),
  ('cpiuris2025::4a11a1e2c42351f81ca71032327c1124', 'doutrina', 'cp_iuris', 'Execução Penal — Estabelecimentos Penais para Mulheres', '## Estabelecimentos Penais para Mulheres

Regras para estabelecimentos penais destinados a mulheres, incluindo berçário e agentes do sexo feminino na segurança.

### Conceitos
- **Berçário**: Área onde as condenadas podem cuidar de seus filhos
- **Segurança interna**: Proteção das dependências internas dos estabelecimentos penais

### Referências legais
- Art. 34 da Lei nº 7.210/82

### Dicas de prova
- Destacar a importância do berçário para as condenadas
- Entender o papel dos agentes do sexo feminino na segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Execução Penal", "legal_refs": ["Art. 34 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:20:11.459004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=65", "doc_key": "4a11a1e2c42351f81ca71032327c1124"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'aa9e878b77175f5b058b0c6e76f72bab7c0de3fedd77dc325345e08a79fc28df'),
  ('cpiuris2025::8678c7c3a88d73282cc521aef7ffa668', 'doutrina', 'cp_iuris', 'Execução Penal — Terceirização de atividades em estabelecimentos penais', '## Terceirização de atividades em estabelecimentos penais

A terceirização de atividades acessórias, instrumentais e complementares em estabelecimentos penais é permitida, desde que sob supervisão e fiscalização do poder público.

### Conceitos
- **Execução indireta**: Realização de atividades acessórias, instrumentais e complementares em estabelecimentos penais
- **Terceirização**: Concedimento de serviços a terceiros, sob supervisão e fiscalização do poder público
- **Serviços acessórios**: Atividades não diretamente relacionadas à execução da pena
- **Supervisão e fiscalização**: Controle exercido pelo poder público sobre a terceirização de atividades

### Referências legais
- Art. 83-A do Código de Processo Penal

### Dicas de prova
- Entenda a distinção entre execução indireta e terceirização
- Conheça os serviços acessórios que podem ser terceirizados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Execução Penal", "legal_refs": ["Art. 83-A do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:21:04.272280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=66", "doc_key": "8678c7c3a88d73282cc521aef7ffa668"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '3a180fa1ca7790bac488b3eaf51bb0d559bba92f9f8300ed7390eea4867928a9'),
  ('cpiuris2025::8c08e3c5a9344ff90593d27e1f5eff0e', 'doutrina', 'cp_iuris', 'Execução Penal — Funções Indelegáveis na Execução Penal', '## Funções Indelegáveis na Execução Penal

Descreve as funções que são exclusivas do poder público e ligadas ao exercício do poder de polícia, como direção, chefia e coordenação no sistema penal.

### Conceitos
- **Função Indelegável**: Exclusiva do poder público e ligada ao exercício do poder de polícia
- **Poder de Polícia**: Habilidade do Estado exercer autoridade sobre indivíduos ou coletividades
- **Direção**: Função que envolve a tomada de decisões estratégicas no sistema penal
- **Chefia**: Função que envolve a supervisão e orientação de subordinados
- **Coordenação**: Função que envolve a organização e gestão de atividades no sistema penal

### Referências legais
- Art. 83-B da Lei nº X

### Dicas de prova
- Entenda a distinção entre funções delegáveis e indelegáveis na execução penal
- Conheça as atividades que exijam o exercício do poder de polícia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Execução Penal", "legal_refs": ["Art. 83-B da Lei nº X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:21:27.302648+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=66", "doc_key": "8c08e3c5a9344ff90593d27e1f5eff0e"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'a4c14a271d19ae489fe2886ea8d22baab05f03d63f3c790563264498ba0f0815'),
  ('cpiuris2025::80bc15bc97f323fec0e02c5647db5d61', 'doutrina', 'cp_iuris', 'Execução Penal — Separação dos Presos e Unidades Prisionais', '## Separação dos Presos e Unidades Prisionais

A separação dos presos é um princípio fundamental na execução penal, visando a individualização da pena na fase executória. As unidades prisionais devem ser distribuídas em grupos com diferentes necessidades de segurança e tratamento.

### Conceitos
- **Regra de Mandela**: Referência internacional que trata sobre a separação dos presos e individualização da pena na fase executória.
- **Unidade Prisional Aberta**: Unidade prisional que não proporciona segurança física, mas confia na autodisciplina dos detentos para promover a reabilitação.
- **Unidade Prisional Fechada**: Unidade prisional que deve ter uma população limitada para evitar o tratamento individualizado ser coibido.

### Referências legais
- Art. 84 da LEP

### Dicas de prova
- Entenda a importância da separação dos presos e as diferentes formas de unidades prisionais.
- Conheça os critérios para a classificação dos presos em grupos com necessidades diferentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Execução Penal", "legal_refs": ["Art. 84 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:22:25.228144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=67", "doc_key": "80bc15bc97f323fec0e02c5647db5d61"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '585808e10c300f47c0b6095fa53abca595f13c08019154607191d93b04937d49'),
  ('cpiuris2025::9644fa8a547ced97df5d33a55e851cbe', 'doutrina', 'cp_iuris', 'Execução Penal — Separação de Presos Provisórios', '## Separação de Presos Provisórios

Os presos provisórios são separados conforme critérios específicos, incluindo a condição de funcionário da Administração da Justiça Criminal.

### Conceitos
- **Preso Provisório**: Pessoa detida provisoriamente, aguardando julgamento
- **Administração da Justiça Criminal**: Entidade responsável pela gestão do sistema prisional
- **Crimes Hediondos**: Tipos de crimes considerados especialmente graves e de maior impacto social

### Referências legais
- Art. 1º da Lei nº 7.210/82
- ...

### Jurisprudência
- Súmula 434 do STF

### Dicas de prova
- Entenda a importância da separação de presos provisórios conforme critérios específicos
- Identifique os critérios de separação dos presos condenados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Execução Penal", "legal_refs": ["Art. 1º da Lei nº 7.210/82", "..."], "jurisprudence": ["Súmula 434 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T16:22:59.286020+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=67", "doc_key": "9644fa8a547ced97df5d33a55e851cbe"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '3727fa62aeeba4c0aa0f2be3f72f42d8cda036b03a82b87a56481902b4f0a2c9'),
  ('cpiuris2025::c6e758b1d81885b8e9d243d19baeaa19', 'doutrina', 'cp_iuris', 'Execução Penal — Segregação de presos com ameaça à integridade física ou psicológica', '## Segregação de presos com ameaça à integridade física ou psicológica

Presos condenados por crimes com violência ou grave ameaça à pessoa são segregados em locais próprios, especialmente aqueles que sofrem ameaças à sua integridade física ou psicológica devido à convivência com outros presos. Além disso, presos LGBTQIA+ e colaboradores de investigações também podem ser segregados.

### Conceitos
- **Segregação**: Ação de separar indivíduos em locais específicos para proteger sua integridade física ou psicológica.
- **Ameaça à integridade**: Situação em que a convivência com outros presos pode causar danos físicos ou psicológicos ao indivíduo.
- **Orientação sexual e identidade de gênero**: Aspectos importantes da personalidade humana que não podem ser tratados de forma binária.
- **Princípios de Yogyakarta**: Referência internacional que estabelece direitos humanos para pessoas com diferentes orientações sexuais e identidade de gênero.

### Referências legais
- Art. 4º da Lei nº 7.210/82

### Jurisprudência
- Súmula 387 do STF

### Dicas de prova
- Entenda a importância da segregação de presos com ameaça à integridade física ou psicológica.
- Conheça os princípios de Yogyakarta e sua relevância para o direito das pessoas LGBTQIA+.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Execução Penal", "legal_refs": ["Art. 4º da Lei nº 7.210/82"], "jurisprudence": ["Súmula 387 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T16:24:16.702568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=68", "doc_key": "c6e758b1d81885b8e9d243d19baeaa19"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'dcf8c0f9cbac03b57d150cc71f99be6749721728d47adc1b934d1dc71b35b398'),
  ('cpiuris2025::a0802e0b807120f017da309716c47bf2', 'doutrina', 'cp_iuris', 'Execução Penal — Proteção de população LGBTI no sistema carcerário', '## Proteção de população LGBTI no sistema carcerário

O texto destaca a importância de proteger a população LGBTI no sistema carcerário, com medidas como minimizar risco de violência e implementar programas de treinamento e conscientização.

### Conceitos
- **Princípio 9 de Yogyakarta**: Garante que pessoas detidas participem de decisões relacionadas ao local de detenção adequada à sua orientação sexual e identidade de gênero
- **Acolhimento LGBTI**: Reconhecimento e respeito às direitos e necessidades da população LGBTI em contextos penitenciários

### Referências legais
- Art. 2 da Resolução Conjunta n.º 1/2014 do CNPCP e do Conselho Nacional de Combate à Discriminação LGBT2

### Dicas de prova
- Entenda o conceito de Princípio 9 de Yogyakarta e sua aplicação prática no sistema carcerário
