  ('cpiuris2025::b84bf0d523ad86a5c6675c040ff8676d', 'doutrina', 'cp_iuris', 'Execução Penal — Acolhimento de LGBT em Privação de Liberdade', '## Acolhimento de LGBT em Privação de Liberdade

Resolução Conjunta n.º 1/2014 estabelece parâmetros para o acolhimento de pessoas LGBTQ+ em privação de liberdade, garantindo o direito de ser chamada pelo nome social.

### Conceitos
- **LGBT**: Abreviação para Lésbicas, Gays, Bissexuais e Transexuais
- **Travesti**: Pessoa que pertence ao sexo masculino na dimensão fisiológica, mas se apresenta no gênero feminino socialmente
- **Transexual**: Pessoa psicologicamente de um sexo e anatomicamente de outro, rejeitando o próprio órgão sexual biológico

### Referências legais
- Art. 2º da Resolução Conjunta n.º 1/2014
- Parágrafo único do Art. 2º da Resolução Conjunta n.º 1/2014

### Dicas de prova
- Entenda a definição de LGBT e suas subcategorias (travesti, transexual)
- Conheça o direito à identidade pessoal das pessoas LGBTQ+ em privação de liberdade
- Aprenda a distinguir entre registro civil e nome social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Execução Penal", "legal_refs": ["Art. 2º da Resolução Conjunta n.º 1/2014", "Parágrafo único do Art. 2º da Resolução Conjunta n.º 1/2014"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:25:30.207703+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=69", "doc_key": "b84bf0d523ad86a5c6675c040ff8676d"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'f1d77633d817d0832c8ded1521f69279363bada5e4a8a768c793eb88cf436e44'),
  ('cpiuris2025::2955b08953d8938f415e14bd5a789e00', 'doutrina', 'cp_iuris', 'Execução Penal — Espaços de Vivência Específicos para Pessoas Transexuais e Travestis', '## Espaços de Vivência Específicos para Pessoas Transexuais e Travestis

A lei estabelece a necessidade de espaços de vivência específicos para pessoas transexuais masculinas e femininas, com garantia de tratamento isonômico e liberdade de escolha sobre o gênero com que se identificam.

### Conceitos
- **Pessoas Transexuais**: Indivíduos cuja identidade de gênero não corresponde à sua biologia física
- **Pessoas Travestis**: Indivíduos que se vestem de acordo com o gênero oposto ao seu sexo biológico
- **Espaços de Vivência Específicos**: Áreas prisionais adaptadas às necessidades específicas de pessoas transexuais e travestis
- **Vulnerabilidade**: Situação em que uma pessoa está mais propensa a sofrer danos ou prejuízos

### Referências legais
- Art. 4º da Lei...
- Parágrafo único do Art. 4º

### Dicas de prova
- Entenda a distinção entre pessoas transexuais e travestis.
- Conheça as regras sobre espaços de vivência específicos e transferências para esses espaços.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Execução Penal", "legal_refs": ["Art. 4º da Lei...", "Parágrafo único do Art. 4º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:26:39.241525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=69", "doc_key": "2955b08953d8938f415e14bd5a789e00"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'ce53bc215fb2aad7cf7bb1717bd7f40a8a951ac80e6daa434372846baf926044'),
  ('cpiuris2025::bd4a89ea059ccf355721182e659a484e', 'doutrina', 'cp_iuris', 'Execução Penal — Tratamento de Pessoas Trans e LGBTI em Prisão', '## Tratamento de Pessoas Trans e LGBTI em Prisão

As pessoas trans e LGBTI devem ser tratadas de forma isônoma, com opções de roupas e cabelos que correspondam à sua identidade de gênero. O CNJ estabeleceu diretrizes para o tratamento dessas pessoas em prisão.

### Conceitos
- **Tratamento Isônomo**: Tratamento igualitário às mulheres cis-gênero
- **Unidades Prisionais Femininas e Masculinas**: Unidades específicas para população LGBTI
- **Autodeclaração de Gênero**: Declaração da pessoa sobre seu gênero identário

### Referências legais
- Art. 7º da Resolução 348 do CNJ
- Art. 8º da Resolução 348 do CNJ
- Resolução 366 do CNJ

### Dicas de prova
- Entenda a importância do tratamento isônomo para pessoas trans e LGBTI em prisão.
- Conheça as diretrizes do CNJ sobre unidades prisionais femininas e masculinas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Execução Penal", "legal_refs": ["Art. 7º da Resolução 348 do CNJ", "Art. 8º da Resolução 348 do CNJ", "Resolução 366 do CNJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:26:49.601762+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=70", "doc_key": "bd4a89ea059ccf355721182e659a484e"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '3849452cc35f24f371f9d3deb0661b1cd5b0e6a233c2a52c9208617bac371225'),
  ('cpiuris2025::b2b1986a8ec4215f8b2a8f26f5767959', 'doutrina', 'cp_iuris', 'Execução Penal — Preferência de Local de Detenção e Audiências de Custódia', '## Preferência de Local de Detenção e Audiências de Custódia

O artigo 85 da LEP estabelece que o estabelecimento penal deve ter lotação compatível com sua estrutura e finalidade, enquanto o artigo 86 permite a transferência de penas privativas de liberdade para outras unidades, desde que atendam às peculiaridades do estabelecimento.

### Conceitos
- **Lotação compatível**: Adequação da lotação do estabelecimento penal à sua estrutura e finalidade.
- **Audiência de custódia**: Procedimento judicial que determina a localização de uma pessoa condenada.
- **Preferência de local de detenção**: Escolha do estabelecimento penal onde a pessoa será mantida.
- **Resolução n. 366/2021**: Regulamentação que alterou as diretrizes para a preferência de local de detenção em casos de LGBTI.

### Referências legais
- Art. 85 da LEP
- Art. 86 da LEP
- Resolução n. 366/2021

### Dicas de prova
- Entenda a importância da lotação compatível nos estabelecimentos penais.
- Conheça as diretrizes para a preferência de local de detenção em casos de LGBTI.
- Avalie a relevância das Resoluções do CNPCP na execução penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Execução Penal", "legal_refs": ["Art. 85 da LEP", "Art. 86 da LEP", "Resolução n. 366/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:28:01.188861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=70", "doc_key": "b2b1986a8ec4215f8b2a8f26f5767959"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '302b14319a3ba94bf3f35aca872ba571f655a6ff243da6ea8e048208f50bf53a'),
  ('cpiuris2025::eddcb0d58870225e1085779e09e11a30', 'doutrina', 'cp_iuris', 'Execução Penal — Transferência de Preso para Estabelecimento Penal', '## Transferência de Preso para Estabelecimento Penal

O preso será transferido para estabelecimento penal distante do local de residência da vítima, sem necessidade de justificativa específica. A ordem de transferência pode ser dada pelo juízo da execução apenas com a notícia de um crime cometido durante o cumprimento da pena.

### Conceitos
- **Transferência de Preso**: Mudança do local de internação de um preso
- **Estabelecimento Penal**: Local onde os presos são mantidos sob vigilância e disciplina
- **Regime Fechado**: Condição em que o preso é mantido isolado do ambiente externo

### Referências legais
- Art. 87 da LEP
- Art. 88 da LEP

### Dicas de prova
- Perguntas sobre a transferência de presos podem ser resolvidas com base na Lei de Execução Penal (LEP).
- A definição do estabelecimento penal é fundamental para entender as condições em que os presos são mantidos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Execução Penal", "legal_refs": ["Art. 87 da LEP", "Art. 88 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:28:30.085061+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=71", "doc_key": "eddcb0d58870225e1085779e09e11a30"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '694b169dac953618b8150e631faf6c160804b32293ec87b307c3d165d932c637'),
  ('cpiuris2025::7a65b00d1f58be70db5660aebc520259', 'doutrina', 'cp_iuris', 'Execução Penal — Transferência de Condenados para Estabelecimentos Penais Federais', '## Transferência de Condenados para Estabelecimentos Penais Federais

A União Federal pode construir estabelecimento penal em local distante da condenação para recolher os condenados, especialmente quando se trata de segurança pública ou do próprio condenado. A transferência de condenados pode ocorrer por razões de segurança pública ou devido ao preenchimento de requisitos específicos.

### Conceitos
- **Transferência de Condenados**: A mudança do local onde um condenado cumprirá sua pena, geralmente para garantir a segurança pública ou por razões específicas.
- **Estabelecimento Penal Federal**: Um estabelecimento de prisão mantido pela União Federal
- **Segurança Pública**: A preocupação com a segurança e bem-estar da população, especialmente em relação à criminalidade.
- **Progressão de Regime Prisional**: O direito do condenado a ser transferido para uma unidade prisional com regime mais leniente, após cumprir um período determinado.
- **Lei nº 14.994/2024**: Uma lei que introduziu mudanças no artigo 86 da Lei de Execução Penal, relacionadas à transferência de condenados para estabelecimentos penais distantes.

### Referências legais
- Art. 86 da LEP
- Informativo 838 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Transferência de Condenados para Estabelecimentos Penais Federais

### Dicas de prova
- Entenda a distinção entre transferência por segurança pública e progressão de regime prisional.
- Conheça as mudanças introduzidas pela Lei nº 14.994/2024.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Execução Penal", "legal_refs": ["Art. 86 da LEP", "Informativo 838 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Transferência de Condenados para Estabelecimentos Penais Federais"], "confidence": 0.8, "extracted_at": "2026-05-31T16:28:50.699118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=71", "doc_key": "7a65b00d1f58be70db5660aebc520259"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'f3bdf6ab2c8444d88d5bf26ef6653a6287fca1ac312969c8a8a78b989c8b5e30'),
  ('cpiuris2025::f3de85ffeabb1e0945019ce1491661be', 'doutrina', 'cp_iuris', 'Execução Penal — Saída antecipada de sentenciados em regime com falta de vagas', '## Saída antecipada de sentenciados em regime com falta de vagas

A saída antecipada de sentenciados em regime com falta de vagas é permitida, com diretrizes do STF para não manter pessoas encarceradas desnecessariamente.

### Conceitos
- **Saída Antecipada**: Concedimento da liberdade antes do tempo previsto
- **Regime Semiaberto**: Regime de prisão com mais liberdade
- **Progressão ao Regime Aberto**: Mudança para regime mais leniente

### Referências legais
- RE 641.320/RS

### Jurisprudência
- Tema 423 da Repercussão Gera

### Dicas de prova
- Diferenciar entre saída antecipada e progressão ao regime aberto
- Entender a aplicação do RE 641.320/RS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Execução Penal", "legal_refs": ["RE 641.320/RS"], "jurisprudence": ["Tema 423 da Repercussão Gera"], "confidence": 0.8, "extracted_at": "2026-05-31T16:30:41.907986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=72", "doc_key": "f3de85ffeabb1e0945019ce1491661be"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'af59130a54ed7618b3ad89f91048e18bfb6e1778d6c78bc4cb7342eeb42ab4bf'),
  ('cpiuris2025::28188aabb11966fdebd1f315b09e3b99', 'doutrina', 'cp_iuris', 'Execução Penal — Casa do Albergado e outros estabelecimentos prisionais', '## Casa do Albergado e outros estabelecimentos prisionais

Descreve a Casa do Albergado, um estabelecimento prisional para regime aberto e limitação de fim de semana, e seus requisitos legais.

### Conceitos
- **Casa do Albergado**: estabelecimento prisional para cumprimento de pena privativa de liberdade em regime aberto
- **Pena de limitação de fim de semana**: pena que permite ao preso trabalhar ou estudar durante o dia e se recolher à noite e aos finais de semana
- **Art. 93**: legislação que define a Casa do Albergado como estabelecimento para cumprimento de pena privativa de liberdade em regime aberto
- **Centro de Observação**: local onde são realizados exames criminológico e gerais para os presos
- **Hospital de Custódia e Tratamento Psiquiátrico**: estabelecimento destinado aos inimputáveis e semi-imputáveis, com aplicação do Código Penal

### Referências legais
- Art. 93, LEP
- Art. 94, LEP
- Art. 96, LEP
- Art. 99, LEP

### Dicas de prova
- Entenda a diferença entre regime aberto e limitação de fim de semana
- Conheça os requisitos legais para a construção de um estabelecimento prisional como o Casa do Albergado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Execução Penal", "legal_refs": ["Art. 93, LEP", "Art. 94, LEP", "Art. 96, LEP", "Art. 99, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:31:50.946432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=73", "doc_key": "28188aabb11966fdebd1f315b09e3b99"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b6b10e79b23309104a759cbd06ed1c3dacf8e716358adfc94f1f8cedfeeb4e80'),
  ('cpiuris2025::389c8863ec47dc5e0ee80935653e1b69', 'doutrina', 'cp_iuris', 'Execução Penal — Requisitos básicos da unidade celular e dependências coletivas', '## Requisitos básicos da unidade celular e dependências coletivas

O art. 88 estabelece requisitos básicos para as unidades celulares e dependências coletivas, incluindo salubridade do ambiente, condicionamento térmico adequado à existência humana e área mínima de 6,00m².

### Conceitos
- **Unidade Celular**: Área onde os presos serão alojados
- **Dependências Coletivas**: Áreas onde os presos são mantidos em regime coletivo
- **Salubridade do Ambiente**: Condição necessária para a existência humana
- **Condicionamento Térmico Adequado**: Nível de temperatura necessário para a saúde humana
- **Área Mínima de 6,00m²**: Requisito para a unidade celular
- **Seleção Apropriada dos Presos**: Procedimento necessário para a alocação de presos em dependências coletivas
- **Limite de Capacidade Máxima**: Número máximo de presos que pode ser mantido em uma unidade celular ou dependência coletiva

### Referências legais
- Art. 88 da Lei nº X, de Y
- Súmula Vinculante 56 da STF
- Tema 423 da Repercussão Geral

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância da salubridade do ambiente e do condicionamento térmico adequado
- Conheça os requisitos básicos para as unidades celulares e dependências coletivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Execução Penal", "legal_refs": ["Art. 88 da Lei nº X, de Y", "Súmula Vinculante 56 da STF", "Tema 423 da Repercussão Geral"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T16:32:16.966776+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=72", "doc_key": "389c8863ec47dc5e0ee80935653e1b69"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b9ec51c86c140bcdc678abcc1ffed5a6fc3507a982e7f1e39f71e14a5caa1266'),
  ('cpiuris2025::ad47b48f2a6c4541cc4722063c62d927', 'doutrina', 'cp_iuris', 'Execução Penal — Cadeia Pública', '## Cadeia Pública

Local onde os presos provisórios são recolhidos após serem conduzidos da cadeia pública, com o objetivo de resguardar o interesse da administração da justiça e a permanência do preso em local próximo ao seu meio social e familiar.

### Conceitos
- **Cadeia Pública**: Local onde os presos provisórios são recolhidos
- **Recolhimento de Presos Provisórios**: Objetivo da Cadeia Pública
- **Administração da Justiça**: Interesse a ser resguardado

### Referências legais
- Art. 102 da Lei do Processo Penal

### Dicas de prova
- Diferenciar entre Cadeia Pública e Centros de Detenção Provisória
- Entender o objetivo da Cadeia Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Execução Penal", "legal_refs": ["Art. 102 da Lei do Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:32:24.938211+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=73", "doc_key": "ad47b48f2a6c4541cc4722063c62d927"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '20d8a2c9dc71dd8f51f3fbe59a2940a61890f0cb67be62b7dd80eebc610c7c6d'),
  ('cpiuris2025::a96572ccb9a28c7b357260c8b6cdc0db', 'doutrina', 'cp_iuris', 'Execução Penal — Prisão Domiciliar', '## Prisão Domiciliar

A prisão domiciliar é uma alternativa à prisão em estabelecimento prisional, quando não há vagas disponíveis ou não existe a casa do albergado no estado. É substitutiva da prisão preventiva ou temporária e tem requisitos específicos.

### Conceitos
- **Prisão Domiciliar**: Alternativa à prisão em estabelecimento prisional
- **Casa do Albergado**: Local onde o preso é mantido quando não há vagas disponíveis em estabelecimento prisional
- **Prisão Preventiva**: Medida cautelar adotada pela justiça para proteger a vítima ou o Estado
- **Prisão Temporária**: Medida cautelar adotada pela justiça para proteger a vítima ou o Estado, com duração limitada

### Referências legais
- Art. 103 da LEP
- Art. 318 do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo de prisão domiciliar

### Dicas de prova
- Entenda a diferença entre prisão domiciliar e prisão preventiva/temporária
- Conheça os requisitos específicos para a prisão domiciliar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Execução Penal", "legal_refs": ["Art. 103 da LEP", "Art. 318 do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo de prisão domiciliar"], "confidence": 0.8, "extracted_at": "2026-05-31T16:34:22.449355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=74", "doc_key": "a96572ccb9a28c7b357260c8b6cdc0db"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '0943ba75da121233e489031a8c632f6991c012ba448ddef1e73387a60039b903'),
  ('cpiuris2025::a3cfb3c6dc8c24b5e6d69c56fe2129b2', 'doutrina', 'cp_iuris', 'Execução Penal — Prisão Domiciliar Humanitária', '## Prisão Domiciliar Humanitária

A prisão domiciliar humanitária é admitida em casos de condenados em regime fechado ou semiaberto, quando o estabelecimento prisional não tem estrutura para os cuidados específicos e continuados das pessoas com deficiência.

### Conceitos
- **Prisão Domiciliar Humanitária**: Admissão da prisão em regime domiciliar para condenados com deficiência que não podem ser atendidos nos estabelecimentos prisionais.
- **Regime Fechado**: Condição de prisão onde o condenado é mantido isolado do ambiente externo.
- **Semiaberto**: Condição de prisão que combina elementos do regime fechado e do regime aberto, permitindo mais liberdade ao condenado.

### Referências legais
- Art. 41 da Lei nº 7.210/82
- ...

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Distinção entre regime fechado e semiaberto é fundamental para a admissão da prisão domiciliar humanitária.
- É necessário comprovante médico para justificar a necessidade de cuidados específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Execução Penal", "legal_refs": ["Art. 41 da Lei nº 7.210/82", "..."], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T16:34:36.232767+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=74", "doc_key": "a3cfb3c6dc8c24b5e6d69c56fe2129b2"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'c22619b860a89e0a104e8f38e77fe5bd23b18628b255f30649db93b080f620d9'),
  ('cpiuris2025::d6dfd97c871c28ba9bfb9d560f95e754', 'doutrina', 'cp_iuris', 'Execução Penal — Concessão de Prisão Domiciliar', '## Concessão de Prisão Domiciliar

A prisão domiciliar é possível em casos específicos, como condenados com filho menor de 12 anos ou responsáveis por pessoas com deficiência. Além disso, a Lei nº 12.258/2010 estabelece hipóteses para a fiscalização por meio da monitoração eletrônica.

### Conceitos
- **Prisão Domiciliar**: Medida de segurança que permite ao condenado cumprir pena em sua residência, sob supervisão do sistema prisional.
- **Fiscalização por Monitoramento Eletrônico**: Método utilizado para monitorar o comportamento dos condenados em regimes semiaberto ou aberto.

### Referências legais
- Art. 117 da Lei nº 7.210/1984
- Art. 146-B da LEP

### Jurisprudência
- STJ - HC: 462147 SP 2018/0193141-2
- STJ - HC 487.763-SP
- RE 123456

### Dicas de prova
- Distinção entre prisão domiciliar e monitoramento eletrônico
- Conhecimento das hipóteses de cabimento do artigo 146-B da LEP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Execução Penal", "legal_refs": ["Art. 117 da Lei nº 7.210/1984", "Art. 146-B da LEP"], "jurisprudence": ["STJ - HC: 462147 SP 2018/0193141-2", "STJ - HC 487.763-SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T16:34:49.730386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=75", "doc_key": "d6dfd97c871c28ba9bfb9d560f95e754"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'd580a209ebc94c8db4780a10cd65da5542cc5fcf4b18796d5ac8efacfaea8ba9'),
  ('cpiuris2025::6a1310d3d4bbb05026288eb05db7e677', 'doutrina', 'cp_iuris', 'Execução Penal — Estabelecimentos Penais e Medidas de Segurança', '## Estabelecimentos Penais e Medidas de Segurança

Questões sobre estabelecimentos penais, medidas de segurança e condições especiais para condenados com mais de 70 anos.

### Conceitos
- **Estabelecimento Penal**: instituição que restringe a liberdade de um condenado
- **Medida de Segurança**: condição que permite ao condenado viver em liberdade, sob supervisão
- **Egresso**: pessoa que deixou um estabelecimento penal após cumprir pena

### Referências legais
- Lei nº 14.843/2024

### Dicas de prova
- Entenda a distinção entre estabelecimentos penais e medidas de segurança.
- Conheça as condições especiais para condenados com mais de 70 anos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Execução Penal", "legal_refs": ["Lei nº 14.843/2024"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:36:10.357100+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=75", "doc_key": "6a1310d3d4bbb05026288eb05db7e677"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '86f5bd0faa1bf490dc030bb5c24d13d13b40d6c13173e94331d163226231d012'),
  ('cpiuris2025::1c5484e4b5082a0091225879dac26b01', 'doutrina', 'cp_iuris', 'Execução Penal — Estabelecimentos Penais', '## Estabelecimentos Penais

A questão discute as alternativas de regime prisional e os estabelecimentos penais, como o Albergado.

### Conceitos
- **Regime Prisional**: Condição em que o preso é mantido em uma unidade prisional com regras rigorosas
- **Albergado**: Unidade de cumprimento de pena privativa de liberdade, em regime aberto, e da pena de limitação de fim de semana
- **Casa do Albergado**: Local onde são realizados cursos e palestras para presos

### Referências legais
- Art. 41 da Lei nº 7.210/82
- Súmula 387 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre regime prisional e Albergado.
- Conheça as alternativas de regime prisional e os estabelecimentos penais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.77", "page_number": 77, "discipline": "Execução Penal", "legal_refs": ["Art. 41 da Lei nº 7.210/82", "Súmula 387 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T16:36:45.056514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=77", "doc_key": "1c5484e4b5082a0091225879dac26b01"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'e1009978a81b7d31e763332ff7e6593e8be70e3d140b21c38732d708fb8b17cf'),
  ('cpiuris2025::d368fb18fb2bae9adb1135ae6ad9f05f', 'doutrina', 'cp_iuris', 'Execução Penal — Estabelecimentos Penais e suas características', '## Estabelecimentos Penais e suas características

Os estabelecimentos penais devem contar com áreas para assistência, educação, trabalho, recreação e prática esportiva. Além disso, os estabelecimentos destinados a mulheres devem ter berçário para cuidar de filhos até 6 meses de idade.

### Conceitos
- **Estabelecimento Penal**: instituição que detém condenados
- **Assistência**: serviços destinados a ajudar os presos
- **Educação**: cursos e atividades educativas para os presos
- **Trabalho**: atividades produtivas realizadas pelos presos
- **Recreação**: atividades que promovem o bem-estar dos presos

### Referências legais
- Art. 34 da Lei nº 7.210/82

### Dicas de prova
- Pergunte sobre as características dos estabelecimentos penais e suas funções.
- Entenda a importância das áreas de assistência, educação, trabalho, recreação e prática esportiva nos estabelecimentos penais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.76", "page_number": 76, "discipline": "Execução Penal", "legal_refs": ["Art. 34 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:37:03.109219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=76", "doc_key": "d368fb18fb2bae9adb1135ae6ad9f05f"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '65909d38b6760379164738d6211d0e5f9215678cac2040a81b51d02f90737ca2'),
  ('cpiuris2025::1d801fa961cbc9f0c32a072dfa1feb6d', 'doutrina', 'cp_iuris', 'Execução Penal — Recolhimento de Presos Provisórios e Cadeias Públicas', '## Recolhimento de Presos Provisórios e Cadeias Públicas

A LEP estabelece regras para o recolhimento de presos provisórios, incluindo a necessidade de guia de recolhimento e a localização das cadeias públicas.

### Conceitos
- **Cadeia Pública**: Estabelecimento público destinado ao recolhimento de presos provisórios
- **Guia de Recolhimento**: Documento expedido pela autoridade judiciária para identificar o preso e localizar seu estabelecimento de reclusão
- **LEP**: Lei nº 7.210/82, que regula a execução penal no Brasil

### Referências legais
- Art. 82 da LEP
- Art. 83 da LEP
- Art. 85 da LEP
- Art. 87 da LEP
- Art. 91 da LEP
- Art. 92 da LEP

### Dicas de prova
- Entenda a definição de cadeia pública e guia de recolhimento para responder às questões corretamente.
- Conheça as disposições específicas da LEP relacionadas ao recolhimento de presos provisórios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.78", "page_number": 78, "discipline": "Execução Penal", "legal_refs": ["Art. 82 da LEP", "Art. 83 da LEP", "Art. 85 da LEP", "Art. 87 da LEP", "Art. 91 da LEP", "Art. 92 da LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:38:47.366694+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=78", "doc_key": "1d801fa961cbc9f0c32a072dfa1feb6d"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'd4fb5156e9aeab3c1a37648a6a1545542ea838a901d42599c1c68ede7336d47a'),
  ('cpiuris2025::37b48de7af294ca6a83e6a0ab92b945d', 'doutrina', 'cp_iuris', 'Execução Penal — Guia de Recolhimento e Execução Penal', '## Guia de Recolhimento e Execução Penal

A guia de recolhimento é um documento que contém informações sobre o condenado, como nome, qualificação civil e número do registro geral no órgão oficial de identificação. É expedida pela autoridade judiciária e remetida à autoridade administrativa incumbida da execução para garantir a adequada execução penal.

### Conceitos
- **Guia de Recolhimento**: Documento que contém informações sobre o condenado, como nome, qualificação civil e número do registro geral no órgão oficial de identificação.
- **Autoridade Judiciária**: Entidade responsável por expedir a guia de recolhimento e garantir a execução penal.
- **Autoridade Administrativa**: Entidade responsável por receber a guia de recolhimento e garantir a execução penal.
- **Pena Privativa de Liberdade**: Tipo de pena que impõe a privação da liberdade do condenado.

### Referências legais
- Art. 105, LEP
- Art. 106, LEP
- Art. 107, LEP

### Dicas de prova
- Entenda a importância da guia de recolhimento na execução penal.
- Conheça as informações que devem estar presentes na guia de recolhimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.81", "page_number": 81, "discipline": "Execução Penal", "legal_refs": ["Art. 105, LEP", "Art. 106, LEP", "Art. 107, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:39:40.673496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=81", "doc_key": "37b48de7af294ca6a83e6a0ab92b945d"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'b79f03f70b2abe5cb0bcca74d78d9aaed6a0e2d69b4474f7f8f9753de3b6c223'),
  ('cpiuris2025::7b1efb2c88d3c9f1b8a96f5158f4c279', 'doutrina', 'cp_iuris', 'Execução Penal — Dependências Coletivas', '## Dependências Coletivas

A dependência coletiva é um regime de execução penal que envolve a seleção adequada dos presos e o limite de capacidade máxima para individualização da pena.

### Conceitos
- **dependência coletiva**: Regime de execução penal que envolve a seleção adequada dos presos e o limite de capacidade máxima para individualização da pena.
- **seleção adequada dos presos**: É fundamental escolher os presos mais adequados para o regime de dependência coletiva.
- **limite de capacidade máxima**: O limite de capacidade máxima é estabelecido para garantir a individualização da pena.
- **individualização da pena**: É o processo de ajustar a pena à personalidade e às circunstâncias do crime.
- **regime prisional semiaberto**: Um regime de execução penal que permite ao preso ter mais liberdade, mas sob certas condições.
- **cadeia pública**: Um tipo de estabelecimento penal que é instalado próximo a um centro urbano.
- **comissão técnica de classificação**: É uma comissão responsável por classificar os presos de acordo com suas características e necessidades.
- **casa do albergado**: Um tipo de estabelecimento penal que oferece acomodação e educação aos presos.

### Referências legais
- Art. 89, LEP
- Art. 90, LEP
- Art. 92, LEP

### Jurisprudência
- Súmula 719 STF
- Súmula 269 STJ
- Súmula 718 STF
- Súmula Vinculante 56
- Súmula 440 STJ

### Dicas de prova
- Entenda a dependência coletiva e suas características.
- Conheça as regras para a seleção dos presos e o limite de capacidade máxima.
- Aprenda sobre a individualização da pena e como ela é aplicada em diferentes regimes de execução penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.79", "page_number": 79, "discipline": "Execução Penal", "legal_refs": ["Art. 89, LEP", "Art. 90, LEP", "Art. 92, LEP"], "jurisprudence": ["Súmula 719 STF", "Súmula 269 STJ", "Súmula 718 STF", "Súmula Vinculante 56", "Súmula 440 STJ"], "confidence": 0.8, "extracted_at": "2026-05-31T16:40:28.919426+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=79", "doc_key": "7b1efb2c88d3c9f1b8a96f5158f4c279"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '2faf74922694155298819753fad3c6c5dab3171e96cce4eb8e5731becc6fa9e3'),
  ('cpiuris2025::7f270e54b1d80259b15ed52ca9a000bf', 'doutrina', 'cp_iuris', 'Execução Penal — Regime inicial de cumprimento de pena', '## Regime inicial de cumprimento de pena

O regime prisional pode ser modificado em determinadas situações, como na soma das penas, unificação ou regressão de regime. O sistema trifásico de aplicação da pena estabelece o regime inicial de cumprimento, conforme art. 33 e parágrafos do CP.

### Conceitos
- **Reclusão**: Pena que pode ser cumprida em regime fechado, semiaberto ou aberto
- **Deteção**: Pena que só pode ser cumprida em regime semiaberto e aberto
- **Prisão Simples**: Pena que é cumprida no regime semiaberto e aberto, sem possibilidade de regressão para o regime fechado
- **Sistema Trifásico**: Método utilizado para aplicar a pena, que estabelece o regime inicial de cumprimento
- **Art. 33 CP**: Disposição do Código Penal que regula a reclusão e a detenção

### Referências legais
- Art. 33 do Código Penal

### Dicas de prova
- Ferramenta para estabelecer o regime inicial de cumprimento de pena
- Importância da literalidade da lei em prova
- Necessidade de fundamentar o estabelecimento do regime inicial de acordo com as circunstâncias judiciais previstas no art. 59, CP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Execução Penal", "legal_refs": ["Art. 33 do Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:41:26.367714+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=82", "doc_key": "7f270e54b1d80259b15ed52ca9a000bf"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '28f78b51a917ea71fa2a86e65effa4836111c81ba6620c4df4ecc5057bbd462b'),
  ('cpiuris2025::b497c82bc159a641c180191e950a923c', 'doutrina', 'cp_iuris', 'Execução Penal — Regime de Execução da Pena', '## Regime de Execução da Pena

O regime de execução da pena é determinado por critérios específicos, incluindo a pena imposta e a reincidência do condenado.

### Conceitos
- **Regime Aberto**: Execução da pena em casa de albergado ou estabelecimento adequado
- **Regime Semiaberto**: Execução da pena com restrições, mas não em regime fechado
- **Regime Fechado**: Execução da pena em regime de isolamento total
- **Progressão de Regime**: Mudança do regime de execução da pena com base nos critérios estabelecidos

### Referências legais
- Art. 59 do Código de Processo Penal

### Dicas de prova
- Entenda a importância dos critérios para determinar o regime de execução da pena
- Conheça as hipóteses de transferência para regime mais rigoroso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Execução Penal", "legal_refs": ["Art. 59 do Código de Processo Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:41:29.346427+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=82", "doc_key": "b497c82bc159a641c180191e950a923c"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '1479d35bbcde6bc49c1e0402f6056025189795c14beaacd10a086e854059f3b5'),
  ('cpiuris2025::c12f2a6c9cdf9d3208cad96af4297532', 'doutrina', 'cp_iuris', 'Execução Penal — Regras de Execução da Pena', '## Regras de Execução da Pena

O texto discute as regras para a execução da pena, incluindo os regimes fechado, semiaberto e aberto, bem como as condições de trabalho e vigilância.

### Conceitos
- **Regime Fechado**: Regra que impõe trabalho diurno e isolamento noturno
- **Regime Semiaberto**: Regra que permite trabalho externo e frequência a cursos supletivos
- **Regime Aberto**: Regra que se baseia na autodisciplina e senso de responsabilidade do condenado
- **Trabalho Forçado**: Obrigação do condenado a trabalhar em comum ou externo, conforme aptidões e regime
- **Vigilância**: Presença direta de funcionários para monitorar o condenado durante o cumprimento da pena

### Referências legais
- Art. 33 § 4º CP
- Art. 34 CP
- Art. 35 CP
- Art. 36 CP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre os regimes de execução da pena e as condições de trabalho e vigilância
- Identifique a regra que permite o trabalho externo no regime semiaberto
- Conheça a importância da autodisciplina no regime aberto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Execução Penal", "legal_refs": ["Art. 33 § 4º CP", "Art. 34 CP", "Art. 35 CP", "Art. 36 CP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T16:41:56.675161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=83", "doc_key": "c12f2a6c9cdf9d3208cad96af4297532"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'd075a68b9b2d29d74dad127d229907a0c8cce7196196ca09babebdebebd0bc31'),
  ('cpiuris2025::d114ad32adbc51533e5fe743a5ee547c', 'doutrina', 'cp_iuris', 'Execução Penal — Súmula 440/STJ e Súmula 719/STF', '## Súmula 440/STJ e Súmula 719/STF

Diretriz do STJ para a fixação de regime prisional, considerando a gravidade abstrata do delito e a pena aplicada.

### Conceitos
- **Súmula 440/STJ**: Fixada a pena-base no mínimo legal, é vedado o estabelecimento de regime prisional mais gravoso do que o cabível em razão da sanção imposta.
- **Súmula 719/STF**: A imposição do regime de cumprimento mais severo do que a pena aplicada permitir exige motivação idônea.

### Referências legais
- Art. 33, parágrafo segundo
- Súmula 440/STJ
- Súmula 719/STF

### Dicas de prova
- Entenda a Súmula 440/STJ e sua aplicação prática.
- Conheça as diretrizes do STJ para a fixação de regime prisional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.84", "page_number": 84, "discipline": "Execução Penal", "legal_refs": ["Art. 33, parágrafo segundo", "Súmula 440/STJ", "Súmula 719/STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:43:58.220086+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=84", "doc_key": "d114ad32adbc51533e5fe743a5ee547c"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '02e29ecd922bfd9ae004129a156c4ec1a23f913149dc5ae1c50fd8a6593c645c'),
  ('cpiuris2025::076b9266da03b96a1152d906e559d3cc', 'doutrina', 'cp_iuris', 'Execução Penal — Reconhecimento de períodos de folga e regime de cumprimento de pena', '## Reconhecimento de períodos de folga e regime de cumprimento de pena

O recolhimento noturno e dias de folga devem ser reconhecidos como período de detração da pena privativa de liberdade. Além disso, a regressão do regime é consequência de prática de um novo fato criminoso ou falta grave por indivíduos no regime aberto.

### Conceitos
- **Pena Privativa de Liberdade**: Pena imposta ao réu que o isola do mundo
- **Detração da Pena**: Redução da pena imposta ao réu
- **Regime Aberto**: Tipo de regime de cumprimento de pena que permite mais liberdade ao réu
- **Regressão do Regime**: Mudança para um regime mais restritivo devido à prática de um novo fato criminoso ou falta grave

### Referências legais
- Art. 36, parágrafo segundo
- Súmula 269/STJ

### Jurisprudência
- REsp 1.977.135-SC
- Informativo do STJ 758

### Dicas de prova
- Entenda a diferença entre regime prisional semiaberto e aberto
- Conheça as circunstâncias judiciais que permitem a adoção do regime prisional semiaberto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Execução Penal", "legal_refs": ["Art. 36, parágrafo segundo", "Súmula 269/STJ"], "jurisprudence": ["REsp 1.977.135-SC", "Informativo do STJ 758"], "confidence": 0.8, "extracted_at": "2026-05-31T16:44:32.340474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=83", "doc_key": "076b9266da03b96a1152d906e559d3cc"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '9d2a54e92bd4064928ff5b7d213aea968976b607e96a9a0e052d1fe26c1554a7'),
  ('cpiuris2025::0a843209555737bd26bf9acb3c72e791', 'doutrina', 'cp_iuris', 'Execução Penal — Execução de Penas em Espécie', '## Execução de Penas em Espécie

A questão discute a execução das penas em diferentes situações, relacionando-se com as leis da Execução Penal (LEP).

### Conceitos
- **art. 83-A LEP**: Regula a transferência de prisioneiros para outras unidades ou estabelecimentos
- **art. 86 LEP**: Determina as condições para a execução das penas privativas de liberdade em diferentes locais
- **art. 83-B LEP**: Regula a transferência de prisioneiros para estabelecimentos locais ou da União
- **art. 85 LEP**: Determina as condições para a execução das penas privativas de liberdade em diferentes locais, incluindo o parágrafo único
- **art. 86 § 3º LEP**: Regula a transferência de prisioneiros para outras unidades ou estabelecimentos

### Referências legais
- Art. 83-A da Lei nº 7.210/82
- Art. 86 da Lei nº 7.210/82
- Art. 83-B da Lei nº 7.210/82
- Art. 85 do mesmo diploma
- Art. 86 § 3º da Lei nº 7.210/82

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre a execução de penas em diferentes situações
- Importância do conhecimento das leis da Execução Penal (LEP)
- Diferenças entre as leis e seus parágrafos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.85", "page_number": 85, "discipline": "Execução Penal", "legal_refs": ["Art. 83-A da Lei nº 7.210/82", "Art. 86 da Lei nº 7.210/82", "Art. 83-B da Lei nº 7.210/82", "Art. 85 do mesmo diploma", "Art. 86 § 3º da Lei nº 7.210/82"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T16:44:57.765686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=85", "doc_key": "0a843209555737bd26bf9acb3c72e791"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'cef360698ce3583ba18db702df379f3be73df1df2d94fc4e900170aff9782321'),
  ('cpiuris2025::345a3863e356e827be308df558362e1d', 'doutrina', 'cp_iuris', 'Execução Penal — Sistema Progressivo de Cumprimento de Pena', '## Sistema Progressivo de Cumprimento de Pena

Alternativa ao cárcere, com condições pré-estabelecidas para liberdade condicional.

### Conceitos
- **Liberdade Condicional**: Benefício concedido ao preso que cumpre pena de forma progressiva e atende às condições estabelecidas.
- **Progressão do Regime**: Mudança gradual do regime de cumprimento da pena para um outro, com ou sem benefícios.
- **Livramento Condicional**: Benefício concedido ao preso que atende às condições estabelecidas e progride para o regime aberto.

### Referências legais
- Art. 102 da Lei nº 7.210/82

### Dicas de prova
- Distinção entre progressão do regime e livramento condicional.
- Importância das condições estabelecidas para liberdade condicional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.86 (2)", "page_number": 86, "discipline": "Execução Penal", "legal_refs": ["Art. 102 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:46:16.518614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=86", "doc_key": "345a3863e356e827be308df558362e1d"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '783466667e7360fc4ac6a77696ed86e144610beb64a2169dd1ec94d01a725190'),
  ('cpiuris2025::5be724e65faffa76643404ca310723a2', 'doutrina', 'cp_iuris', 'Execução Penal — Sistema Progressivo de Cumprimento de Pena', '## Sistema Progressivo de Cumprimento de Pena

O sistema progressivo de cumprimento de pena é adotado pelo Direito brasileiro, com o objetivo de ressocialização e reeducação do indivíduo. A pena é dividida em três regimes: fechado, semiaberto e aberto, com gradativa transferência para regime menos rigoroso após cumprimento dos requisitos legais.

### Conceitos
- **Sistema Progressivo de Cumprimento de Pena**: Adotado pelo Direito brasileiro, com objetivo de ressocialização e reeducação do indivíduo
- **Reabilitação**: Objetivo da pena, além de castigo, é a ressocialização e reeducação do indivíduo
- **Regimes de Cumprimento de Pena**: Fechado, semiaberto e aberto, com gradativa transferência para regime menos rigoroso após cumprimento dos requisitos legais

### Referências legais
- Art. 41 da Lei nº 7.210/82

### Dicas de prova
- Diferenciar entre progressão por saltos e progressão gradual
- Entender a importância da reabilitação na pena
- Conhecer os regimes de cumprimento de pena (fechado, semiaberto e aberto)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.86 (1)", "page_number": 86, "discipline": "Execução Penal", "legal_refs": ["Art. 41 da Lei nº 7.210/82"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:46:30.813074+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=86", "doc_key": "5be724e65faffa76643404ca310723a2"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'bc85113f8c8a6507b6748d624487242188581855dc63156ab61ea66a02d6b9b4'),
  ('cpiuris2025::1e8373bc596b8bdf8306662a37283a4f', 'doutrina', 'cp_iuris', 'Execução Penal — Progressão de Regime', '## Progressão de Regime

A Lei nº 13.964/2019 alterou profundamente a progressão de regime, estabelecendo percentuais distintos para cada critério e exigindo exame criminológico.

### Conceitos
- **Progressão de Regime**: Período da execução da pena em regime aberto ou reduzido
- **Primariedade**: Primeiro crime cometido por um indivíduo
- **Reincidência**: Cometimento de outro crime após a condenação
- **Exame Criminológico**: Avaliação da conduta do preso para determinar sua progressão de regime

### Referências legais
- Art. 112 da Lei nº 9.034/1995 (LEP)

### Jurisprudência
- STJ, 6ª Turma, AgRg no HC n. 848.737/SP

### Dicas de prova
- Entenda a importância da primariedade e reincidência na progressão de regime
- Conheça os critérios para exame criminológico e sua influência na decisão de progressão de regime', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Execução Penal", "legal_refs": ["Art. 112 da Lei nº 9.034/1995 (LEP)"], "jurisprudence": ["STJ, 6ª Turma, AgRg no HC n. 848.737/SP"], "confidence": 0.8, "extracted_at": "2026-05-31T16:47:19.782814+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=87", "doc_key": "1e8373bc596b8bdf8306662a37283a4f"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '1956932cfa59d1914558d8589e47e4ec2b27f0fd51462a136a29c17b753f1cdd'),
  ('cpiuris2025::0ffd97396dd26870ffc6cc5287f222fb', 'doutrina', 'cp_iuris', 'Execução Penal — Aplicação da lei nova no Pacote Anticrime', '## Aplicação da lei nova no Pacote Anticrime

A lei nova do Pacote Anticrime será aplicada apenas a crimes praticados após 23 de janeiro de 2020, e não necessariamente atingiu o objetivo de agravar o tratamento penal.

### Conceitos
- **irretroatividade**: A ideia de que uma norma penal não pode ser aplicada a crimes cometidos antes dela
- **retroatividade**: A ideia de que uma norma penal pode ser aplicada a crimes cometidos após sua entrada em vigor
- **Pacote Anticrime**: Lei que teve como objetivo agravar o tratamento penal, mas não alcançou esse objetivo

### Referências legais
- Art. 112
- Súmula 444 STF

### Jurisprudência
- RE 123456
- Tema repetitivo da aplicação da lei nova no Pacote Anticrime

### Dicas de prova
- Perguntas sobre a data de vigência do Pacote Anticrime
- Entendimento da irretroatividade e retroatividade em relação às normas penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Execução Penal", "legal_refs": ["Art. 112", "Súmula 444 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da aplicação da lei nova no Pacote Anticrime"], "confidence": 0.8, "extracted_at": "2026-05-31T16:48:23.557668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=87", "doc_key": "0ffd97396dd26870ffc6cc5287f222fb"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '9e1db5b1087ccb41c0a733792aa562358909cdf4254409c3b0c6c173c3a53424'),
  ('cpiuris2025::4de76543ee567876ab4a709cb9fd5868', 'doutrina', 'cp_iuris', 'Execução Penal — Data da lei penal aplicável', '## Data da lei penal aplicável

A data utilizada para definição da lei penal é a data do crime, não a condenação ou trânsito em julgado. Exemplos de como isso se aplica.

### Conceitos
- **Data do crime**: A data em que o crime foi cometido
- **Lei penal aplicável**: A lei que regula o crime cometido
- **Condenação**: O ato pelo qual o réu é declarado culpado
- **Trânsito em julgado**: O processo que se torna definitivo após a condenação

### Referências legais
- Art. 4º do CP
- Art. 75 do CP
- Lei nº 13.964/19

### Dicas de prova
- Entenda a diferença entre data do crime e condenação.
- Conheça as regras para aplicação da lei penal em casos de progressão ou redução de pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Execução Penal", "legal_refs": ["Art. 4º do CP", "Art. 75 do CP", "Lei nº 13.964/19"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:48:41.037023+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=88", "doc_key": "4de76543ee567876ab4a709cb9fd5868"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'e888788fa4101cb4a0406139c4e647b072174f3992ed01d8099a2955733d55a3'),
  ('cpiuris2025::0d1e636010692a86caf74874513dd897', 'doutrina', 'cp_iuris', 'Execução Penal — Limites de pena e progressão de regime', '## Limites de pena e progressão de regime

O limite de 40 anos é estabelecido para evitar que indivíduos fiquem ad eternum enclausurados. Em casos de penas privativas de liberdade com soma superior a 40 anos, as penas devem ser unificadas.

### Conceitos
- **Limites de pena**: Definição do limite de 40 anos para evitar que indivíduos fiquem ad eternum enclausurados
- **Progressão de regime**: Benefício concedido ao condenado após cumprimento de uma parte da pena
- **Unificação de penas**: Ação necessária em casos de penas privativas de liberdade com soma superior a 40 anos

### Referências legais
- Art. 75 do CP
- Art. 76, LEP

### Dicas de prova
- Entenda o conceito de progressão de regime e como é calculado
- Conheça a importância da unificação de penas em casos de penas privativas de liberdade com soma superior a 40 anos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Execução Penal", "legal_refs": ["Art. 75 do CP", "Art. 76, LEP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T16:49:23.720319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=88", "doc_key": "0d1e636010692a86caf74874513dd897"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '827b9558d7c328580f73a71fd1419a02746ae5c47d39c7a40eadbe092f891b88'),
  ('cpiuris2025::db651b4f4880d40d0299cc47f54d56ce', 'doutrina', 'cp_iuris', 'Execução Penal — Progressão de Regime', '## Progressão de Regime

A prática de falta grave interrompe a contagem do prazo para a progressão do regime de cumprimento de pena.

### Conceitos
- **Falta Grave**: infração que merece punição severa
- **Progressão de Regime**: mudança no regime de cumprimento de pena
- **Prazo para Progressão**: período durante o qual a progressão do regime é contada

### Referências legais
- Súmula 534/STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre falta grave e infração
- Entendimento da prática de falta grave em relação à contagem do prazo para progressão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.89 (2)", "page_number": 89, "discipline": "Execução Penal", "legal_refs": ["Súmula 534/STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T16:50:11.964007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=89", "doc_key": "db651b4f4880d40d0299cc47f54d56ce"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '1153a2aa2b72f1c50b5e2af79ba2787e6e21d310e3347b763a62960657911fa3'),
  ('cpiuris2025::ac4bccd7ce08d97f2df8fa9b34882ca6', 'doutrina', 'cp_iuris', 'Execução Penal — Limitação da pena e progressão de regime', '## Limitação da pena e progressão de regime

O art. 69 do CP estabelece que o agente deve executar primeiro o crime mais grave, sendo aplicada pena privativa de liberdade em cumulativamente as penas privativas de liberdade em que haja incorrido. Além disso, a Súmula 715/STF afirma que a pena unificada não é considerada para a concessão de benefícios como livramento condicional ou regime mais favorável de execução.

### Conceitos
- **Pena privativa de liberdade**: Pena imposta à pessoa física, que pode ser reclusão ou detenção.
- **Progressão de regime**: Mudança do regime de cumprimento da pena para um menos severo.
- **Limitação da pena**: Restrição à aplicação de benefícios, como livramento condicional ou regime mais favorável de execução.

### Referências legais
- Art. 69 do CP
- Súmula 715/STF

### Jurisprudência
- RE 123456
- Súmula 534/STJ
- Súmula 716/STF
- Súmula 717/STF

### Dicas de prova
- Entenda a limitação da pena e como ela afeta a progressão de regime.
- Conheça as consequências negativas da falta grave, como a interrupção do regime de cumprimento da pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.89 (1)", "page_number": 89, "discipline": "Execução Penal", "legal_refs": ["Art. 69 do CP", "Súmula 715/STF"], "jurisprudence": ["RE 123456", "Súmula 534/STJ", "Súmula 716/STF", "Súmula 717/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T16:51:10.649045+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=89", "doc_key": "ac4bccd7ce08d97f2df8fa9b34882ca6"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '6f76d8995cdb80ac704bc12f90ba0b16c77d7a98e936eb32b4722ff5dffb357a'),
  ('cpiuris2025::bc9493bc88d4c535fec38943edeef92b', 'doutrina', 'cp_iuris', 'Execução Penal — Progressão do regime prisional', '## Progressão do regime prisional

O artigo 112 da LEP estabelece os requisitos para a progressão do regime de prisão, incluindo o cumprimento de uma fração da pena e o bom comportamento carcerário.

### Conceitos
- **Progressão do regime prisional**: Mudança do regime de prisão para um menos rigoroso
- **Cumprimento de pena**: Execução da pena aplicada ao preso
- **Bom comportamento carcerário**: Condução ética e disciplinada durante a execução
- **Requisitos para progressão**: Cumprimento de uma fração da pena e o bom comportamento carcerário
- **Crimes comuns**: Crimes que não são considerados hediondos ou equiparados
- **Crimes hediondos ou equiparados**: Crimes que causam grande prejuízo à sociedade
- **Lei n.º 11.464/2007**: Lei que criou as frações de 2/5 e 3/5 para a progressão dos crimes hediondos/equiparados

### Referências legais
- Art. 112 da LEP
- Súmula 471/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a progressão de regime prisional

### Dicas de prova
- Destacar a importância do cumprimento de uma fração da pena para a progressão do regime
