  ('cpiuris2025::0a8fdd73f18c53a82810ec1d570da5ae', 'doutrina', 'cp_iuris', 'Execução Penal — Exame Criminológico e Progressão de Regime', '## Exame Criminológico e Progressão de Regime

O exame criminológico pode ser admitido em casos específicos, especialmente quando o indivíduo demonstra recalcitrância. A Súmula Vinculante 26 estabelece que o juiz da execução deve observar a inconstitucionalidade do artigo 2º da Lei 8.072/1990 e avaliar se o condenado preenche os requisitos objetivos e subjetivos do benefício.

### Conceitos
- **Exame Criminológico**: Avaliação psicológica para determinar a responsabilidade de um indivíduo
- **Progressão de Regime**: Mudança da classificação do regime de cumprimento de pena
- **Súmula Vinculante 26**: Estabelece as diretrizes para a avaliação da progressão de regime em crimes hediondos

### Referências legais
- Art. 2º da Lei 8.072/1990
- Súmula 439/STJ
- Súmula Vinculante 26

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do exame criminológico em casos de recalcitrância.
- Conheça as diretrizes da Súmula Vinculante 26 para a progressão de regime.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Execução Penal", "legal_refs": ["Art. 2º da Lei 8.072/1990", "Súmula 439/STJ", "Súmula Vinculante 26"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T16:52:43.250756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=90", "doc_key": "0a8fdd73f18c53a82810ec1d570da5ae"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '96d8d738be06c73082da971a3249560a9e341d5d6d5fa076046ea70d355f7fe5'),
  ('cpiuris2025::51a6cb1849027bbbf61bbeb4f5a32c3b', 'doutrina', 'cp_iuris', 'Execução Penal — Requisito Obrigatório do Exame Criminológico', '## Requisito Obrigatório do Exame Criminológico

O exame criminológico não é mais obrigatório para a progressão de regime, mas pode ser determinado pelo juiz da execução se houver elementos concretos que o justifiquem.

### Conceitos
- **Exame Criminológico**: Avaliação psicológica do réu para determinar a sua aptidão à cumprimento de pena em regime fechado
- **Progressão de Regime**: A possibilidade de um condenado ser transferido de uma pena mais severa para uma menos, com base na sua conduta durante a execução penal
- **Reincidência**: O ato de cometer um novo crime após ter sido condenado anteriormente

### Referências legais
- Art. 77, § 3º, da Lei nº 7.210/82

### Jurisprudência
- HC 94577 SP
- HC 103352 RS

### Dicas de prova
- Entenda a importância do exame criminológico na execução penal e como ele pode afetar a progressão de regime.
- Conheça as peculiaridades do caso e como eles podem ser utilizados para determinar a necessidade do exame.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Execução Penal", "legal_refs": ["Art. 77, § 3º, da Lei nº 7.210/82"], "jurisprudence": ["HC 94577 SP", "HC 103352 RS"], "confidence": 0.8, "extracted_at": "2026-05-31T16:53:43.981178+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=91", "doc_key": "51a6cb1849027bbbf61bbeb4f5a32c3b"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', 'bac1967a83f159afa476e8892fd6cf16346ecdf28c0b7fa2e519dcf541cdd9b5'),
  ('cpiuris2025::58d72ef81f2f4e81225eb110effc8316', 'doutrina', 'cp_iuris', 'Execução Penal — Exame Criminológico e Progressão de Regime', '## Exame Criminológico e Progressão de Regime

A jurisprudência da STJ estabelece que o exame criminológico não é obrigatório para a concessão da progressão de regime, mas deve ser realizado em cada caso, com fundamentação concreta na conduta do apenado.

### Conceitos
- **Exame Criminológico**: Análise psicológica e médica realizada ao apenado para avaliar sua conduta durante a execução penal.
- **Progressão de Regime**: Mudança do regime de cumprimento da pena, podendo ser para regime semiaberto ou outro mais leniente.
- **Lei n. 10.792/2003**: Lei que aboliu a obrigatoriedade do exame criminológico como requisito para a concessão da progressão de regime.

### Referências legais
- Art. 112 da Lei de Execução Penal

### Jurisprudência
- HC 323553/SP (Sexta Turma, Relator Ministro NEFI CORDEIRO, Julgado em 18/8/2015)

### Dicas de prova
- Distinção entre o exame criminológico e a progressão de regime.
- Importância da fundamentação concreta na decisão sobre o exame criminológico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Execução Penal", "legal_refs": ["Art. 112 da Lei de Execução Penal"], "jurisprudence": ["HC 323553/SP (Sexta Turma, Relator Ministro NEFI CORDEIRO, Julgado em 18/8/2015)"], "confidence": 0.8, "extracted_at": "2026-05-31T16:54:26.846555+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=91", "doc_key": "58d72ef81f2f4e81225eb110effc8316"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '832328b93b16560ffd2eef989138bc14718123f8fe320cb78a83d56b3510855e'),
  ('cpiuris2025::0cb1a0d0a459116d65e1a120fb8dc80a', 'doutrina', 'cp_iuris', 'Execução Penal — Progressão de Regime', '## Progressão de Regime

Com a mudança legislativa trazida pela Lei nº 14.843, de 2024, o exame criminológico passou a ser obrigatório para a progressão de regimes.

### Conceitos
- **Progressão de Regime**: A transferência do preso para um regime menos rigoroso, após cumprir uma pena determinada
- **Exame Criminológico**: Um exame realizado para avaliar a conduta carcerária do apenado e determinar sua progressão de regime
- **Lei nº 14.843/2024**: Uma lei que alterou as regras de progressão de regimes e tornou o exame criminológico obrigatório
- **Art. 112 da LEP**: Apenas a pena privativa de liberdade será executada em forma progressiva com a transferência para regime menos rigoroso

### Referências legais
- Art. 112 da LEP
- Lei nº 14.843/2024

### Jurisprudência
- Súmula Vinculante 26
- Súmula 439 do STJ
- RE 123456

### Dicas de prova
- Entenda a mudança legislativa trazida pela Lei nº 14.843/2024 e como ela afeta a progressão de regimes
- Conheça as regras atualizadas de progressão de regimes e o papel do exame criminológico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf", "source_ref": "IURIS - Execução Penal - Vol. 09 - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Execução Penal", "legal_refs": ["Art. 112 da LEP", "Lei nº 14.843/2024"], "jurisprudence": ["Súmula Vinculante 26", "Súmula 439 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T16:54:34.872202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Execução Penal - Vol. 09 - 2025.pdf#page=92", "doc_key": "0cb1a0d0a459116d65e1a120fb8dc80a"}'::jsonb, '{"materia": "Execução Penal"}'::jsonb, 'cp_iuris_2025', '2bfa76f0da134544ef9757eab20c3c041f73c105178565c3eb4a45f554cd1479'),
  ('cpiuris2025::769f5373bb4042b308f1d0eebbb0f75c', 'doutrina', 'cp_iuris', 'Execução Penal — Percentuais da pena para condenados por crimes hediondos ou equiparados', '## Percentuais da pena para condenados por crimes hediondos ou equiparados

Resumo sobre os percentuais da pena aplicáveis a condenados por crimes hediondos ou equiparados, considerando primário e reincidente.

### Conceitos
- **Crime Hediondo**: crime que resulta em morte ou grave dano à saúde
- **Organização Criminosa Estruturada**: organização criminosa com estrutura organizacional definida
- **Feminicídio**: homicídio cometido contra uma mulher, geralmente por razões de gênero
- **Reincidente**: condenado que cometeu o mesmo crime mais de uma vez

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre reincidente genérica e específica
